import { useState, useEffect, useCallback, useRef, lazy, Suspense } from 'react';
import { Analytics } from '@vercel/analytics/react';
import { Sidebar } from './components/Sidebar';
import { GlobalInjest } from './components/GlobalInjest';
import { Upload, ArrowUp, ArrowDown } from 'lucide-react';

import type { WeekSummary, Action, Incident, StaffMember, Page } from './lib/types';
import { loadWeekData, loadActions, saveActions, loadIncidents, saveIncidents, loadStaff, saveStaff } from './lib/storage';
import { loadClients, type FullClient } from './lib/client-store';
import { getAllEntriesAsync, appendEntriesAsync } from './lib/entry-store';
import { buildWeekSummary } from './lib/universal-parser';
import { ErrorBoundary } from './components/ErrorBoundary';
import { getSectionByPage } from './lib/navigation';
import { canAccessPage, normalizeUserRole, type UserRole } from './lib/rbac';

const Dashboard = lazy(() => import('./pages/Dashboard').then(m => ({ default: m.Dashboard })));
const UploadPage = lazy(() => import('./pages/UploadPage').then(m => ({ default: m.UploadPage })));
const TemplatesPage = lazy(() => import('./pages/TemplatesPage').then(m => ({ default: m.TemplatesPage })));
const ActionsPage = lazy(() => import('./pages/ActionsPage').then(m => ({ default: m.ActionsPage })));
const IncidentsPage = lazy(() => import('./pages/IncidentsPage').then(m => ({ default: m.IncidentsPage })));
const StaffPage = lazy(() => import('./pages/StaffPage').then(m => ({ default: m.StaffPage })));
const StaffNotePage = lazy(() => import('./pages/StaffNotePage').then(m => ({ default: m.StaffNotePage })));
const HandoverPage = lazy(() => import('./pages/HandoverPage').then(m => ({ default: m.HandoverPage })));
const CommunicationsPage = lazy(() => import('./pages/CommunicationsPage').then(m => ({ default: m.CommunicationsPage })));
const BriefingPage = lazy(() => import('./pages/BriefingPage').then(m => ({ default: m.BriefingPage })));
const CompliancePage = lazy(() => import('./pages/CompliancePage').then(m => ({ default: m.CompliancePage })));
const ReportsPage = lazy(() => import('./pages/ReportsPage').then(m => ({ default: m.ReportsPage })));
const RiskScoresPage = lazy(() => import('./pages/RiskScoresPage').then(m => ({ default: m.RiskScoresPage })));
const ClientDocsPage = lazy(() => import('./pages/ClientDocsPage').then(m => ({ default: m.ClientDocsPage })));
const ClientDiaryPage = lazy(() => import('./pages/ClientDiaryPage').then(m => ({ default: m.ClientDiaryPage })));
const AgencyPortalPage = lazy(() => import('./pages/AgencyPortalPage').then(m => ({ default: m.AgencyPortalPage })));
const StaffMonitoringPage = lazy(() => import('./pages/StaffMonitoringPage').then(m => ({ default: m.StaffMonitoringPage })));
const NoteWorkspace = lazy(() => import('./pages/NoteWorkspace').then(m => ({ default: m.NoteWorkspace })));
const SettingsPage = lazy(() => import('./pages/SettingsPage').then(m => ({ default: m.SettingsPage })));
const AdminPage = lazy(() => import('./pages/AdminPage').then(m => ({ default: m.AdminPage })));
const EmpireMatrix = lazy(() => import('./pages/EmpireMatrix').then(m => ({ default: m.EmpireMatrix })));
const SovereignTrainingHub = lazy(() => import('./pages/SovereignTrainingHub'));
const NourishTaskPack = lazy(() => import('./pages/NourishTaskPack').then(m => ({ default: m.NourishTaskPack })));


export default function App() {
  const [authed, setAuthed] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(() => normalizeUserRole(localStorage.getItem('hc-user-role')));
  const [sessionLoaded, setSessionLoaded] = useState(false);
  const [pageId, setPageId] = useState<Page>(() => {
    const saved = (localStorage.getItem('hc_current_page') as Page) || 'briefing';
    const role = normalizeUserRole(localStorage.getItem('hc-user-role'));
    return canAccessPage(role, saved) ? saved : 'briefing';
  });
  const [pageCtx, setPageCtx] = useState<any>(null);
  const mainRef = useRef<HTMLElement>(null);

  const setPage = useCallback((p: Page, ctx?: any) => {
    if (!canAccessPage(userRole, p)) {
      setPageId('briefing');
      setPageCtx(null);
      localStorage.setItem('hc_current_page', 'briefing');
      return;
    }
    setPageId(p);
    setPageCtx(ctx || null);
    localStorage.setItem('hc_current_page', p);
  }, [userRole]);

  useEffect(() => {
    if (!canAccessPage(userRole, pageId)) {
      setPageId('briefing');
      setPageCtx(null);
      localStorage.setItem('hc_current_page', 'briefing');
    }
  }, [userRole, pageId]);

  useEffect(() => {
    if (mainRef.current) {
      mainRef.current.scrollTop = 0;
    }
  }, [pageId]);

  const scrollToTop = () => {
    const clinicalList = document.getElementById('clinical-workspace-list');
    if (clinicalList) {
      clinicalList.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (mainRef.current) {
      mainRef.current.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const scrollToBottom = () => {
    const clinicalList = document.getElementById('clinical-workspace-list');
    if (clinicalList) {
      clinicalList.scrollTo({ top: clinicalList.scrollHeight, behavior: 'smooth' });
    } else if (mainRef.current) {
      mainRef.current.scrollTo({ top: mainRef.current.scrollHeight, behavior: 'smooth' });
    }
  };

  const page = pageId;
  const activeSection = getSectionByPage(page);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    const saved = localStorage.getItem('hc-theme');
    return saved === 'dark' ? 'dark' : 'light';
  });
  const [isDraggingFile, setIsDraggingFile] = useState(false);
  const [globalInjestFile, setGlobalInjestFile] = useState<File | null>(null);
  const [buildTag, setBuildTag] = useState('unknown');

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('hc-theme', theme);
    
    // Apply UI persistent settings
    const isCompact = localStorage.getItem('hc-compact-density') === 'true';
    const shadowDepth = Number(localStorage.getItem('hc-shadow-depth')) || 3;
    document.documentElement.classList.toggle('compact-density', isCompact);
    document.documentElement.style.setProperty('--shadow-depth', String(shadowDepth / 3));
  }, [theme]);

  useEffect(() => {
    const script = document.querySelector('script[type="module"][src*="assets/index-"]') as HTMLScriptElement | null;
    if (!script?.src) return;
    const m = script.src.match(/assets\/(index-[^./]+)\.js/i);
    if (m?.[1]) setBuildTag(m[1]);
  }, []);

  const [weekData, setWeekData] = useState<WeekSummary | null>(() => loadWeekData());
  const [actions, setActions] = useState<Action[]>(() => loadActions());
  const [incidents, setIncidents] = useState<Incident[]>(() => loadIncidents());
  const [staff, setStaff] = useState<StaffMember[]>(() => loadStaff());
  const [clients] = useState<FullClient[]>(() => loadClients());

  useEffect(() => {
    // Avoid full-history rebuild on startup when session week data already exists.
    // This prevents first-load stalls on large IndexedDB datasets.
    if (weekData) return;
    getAllEntriesAsync().then(entries => {
      if (entries && entries.length > 0) {
        const generated = buildWeekSummary(entries);
        setWeekData(generated);
      }
    }).catch(err => console.error('[Pipeline] Core Hydration Failure:', err));
  }, [weekData]);

  const handleWeekDataUpdate = useCallback(async (data: WeekSummary) => {
    const newEntries = Object.values(data.houses).flatMap(h => h.entries);
    if (newEntries.length > 0) {
      await appendEntriesAsync(newEntries);
      const fullHistory = await getAllEntriesAsync();
      const generated = buildWeekSummary(fullHistory);
      setWeekData(generated);
    } else {
      setWeekData(data);
    }
  }, []);

  const handleDataParsed = useCallback(async (data: WeekSummary) => {
    await handleWeekDataUpdate(data);
    setPage('dashboard');
  }, [handleWeekDataUpdate, setPage]);

  const handleGlobalDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDraggingFile(false);
    const file = e.dataTransfer.files?.[0];
    if (file) setGlobalInjestFile(file);
  }, [setGlobalInjestFile, setIsDraggingFile]);

  useEffect(() => {
    const controller = new AbortController();
    const timeoutId = window.setTimeout(() => {
      controller.abort();
      setSessionLoaded(true);
    }, 8000);

    fetch('/api/auth/session', { credentials: 'include', signal: controller.signal })
      .then((r) => r.json())
      .then((d) => {
        if (d?.authed) {
          setAuthed(true);
          const role = normalizeUserRole(d?.role || localStorage.getItem('hc-user-role'));
          localStorage.setItem('hc-user-role', role);
          setUserRole(role);
        }
        setSessionLoaded(true);
      })
      .catch(() => setSessionLoaded(true))
      .finally(() => window.clearTimeout(timeoutId));

    return () => {
      controller.abort();
      window.clearTimeout(timeoutId);
    };
  }, []);

  const handleSignOut = async () => {
    // Remove this session from the registry before signing out
    const sessionId = sessionStorage.getItem('hc-session-id');
    if (sessionId) {
      const raw = localStorage.getItem('hc-registered-sessions');
      if (raw) {
        const sessions = JSON.parse(raw).filter((s: { id: string }) => s.id !== sessionId);
        localStorage.setItem('hc-registered-sessions', JSON.stringify(sessions));
      }
    }
    sessionStorage.removeItem('hc-pin-unlocked');
    await fetch('/api/auth/session', { method: 'DELETE', credentials: 'include' });
    window.location.reload();
  };

  // Register/refresh session record when authenticated
  useEffect(() => {
    if (!authed) return;

    let sessionId = sessionStorage.getItem('hc-session-id');
    if (!sessionId) {
      sessionId = `sess_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
      sessionStorage.setItem('hc-session-id', sessionId);
    }

    const raw = localStorage.getItem('hc-registered-sessions');
    const sessions: { id: string; device: string; browser: string; timestamp: string; lastActive: string; revoked: boolean }[] = raw ? JSON.parse(raw) : [];

    // If another device revoked this session, sign out
    const thisEntry = sessions.find(s => s.id === sessionId);
    if (thisEntry?.revoked) {
      handleSignOut();
      return;
    }

    const ua = navigator.userAgent;
    const device = /Mobile|Android|iPhone|iPad/.test(ua) ? 'Mobile' : 'Desktop';
    const browser = /Edg/.test(ua) ? 'Edge' : /Firefox/.test(ua) ? 'Firefox' : /Chrome/.test(ua) ? 'Chrome' : /Safari/.test(ua) ? 'Safari' : 'Browser';
    const now = new Date().toISOString();

    const others = sessions.filter(s => s.id !== sessionId);
    others.push({ id: sessionId, device, browser, timestamp: thisEntry?.timestamp || now, lastActive: now, revoked: false });
    localStorage.setItem('hc-registered-sessions', JSON.stringify(others.slice(-20)));
  }, [authed]); 
  if (!sessionLoaded) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-hc-bg">
        <div className="w-12 h-12 rounded-full border-4 border-hc-teal/20 border-t-hc-teal animate-spin" />
      </div>
    );
  }

  if (!authed) {
    return <LoginGate onUnlock={(role) => {
      const normalized = normalizeUserRole(role);
      localStorage.setItem('hc-user-role', normalized);
      setUserRole(normalized);
      setAuthed(true);
    }} />;
  }

  return (
    <div
      className="relative min-h-screen bg-hc-bg"
      onDragOver={e => { e.preventDefault(); setIsDraggingFile(true); }}
      onDragLeave={() => setIsDraggingFile(false)}
      onDrop={handleGlobalDrop}
    >
      <Analytics />
      <ErrorBoundary>
        <div className="flex h-screen overflow-hidden">
          <Sidebar page={page} setPage={setPage} weekData={weekData} actions={actions} theme={theme} setTheme={setTheme} onSignOut={handleSignOut} />

          <main ref={mainRef} className="flex-1 overflow-y-auto bg-hc-bg relative scrollbar-thin">
            <div className="relative z-10 w-full min-h-screen ">
              <div className="sticky top-0 z-20 px-6 pt-4 pb-3 bg-hc-bg/90 backdrop-blur-md border-b border-hc-border/10">
                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-2 overflow-x-auto scrollbar-none flex-1">
                  {activeSection.tabs.filter(tab => canAccessPage(userRole, tab.id)).map(tab => {
                    const active = page === tab.id;
                    return (
                      <button
                        key={tab.id}
                        onClick={() => setPage(tab.id)}
                        className={`shrink-0 px-3 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                          active
                            ? 'hc-clay-pressed text-hc-teal border border-hc-teal/20'
                            : 'hc-clay-raised text-hc-muted hover:text-hc-text'
                        }`}
                      >
                        {tab.label}
                      </button>
                    );
                  })}
                  </div>
                  <span className="shrink-0 px-2.5 py-1 rounded-lg hc-clay-inset text-[9px] font-black uppercase tracking-widest text-hc-muted border border-hc-border/20">
                    Build {buildTag}
                  </span>
                </div>
              </div>
              <Suspense fallback={
                <div className="px-4 sm:px-6 py-10">
                  <div className="w-10 h-10 rounded-full border-4 border-hc-teal/20 border-t-hc-teal animate-spin" />
                </div>
              }>
                {page === 'briefing' && <BriefingPage weekData={weekData} actions={actions} setPage={setPage} />}
                {page === 'dashboard' && <Dashboard weekData={weekData} setPage={setPage} actions={actions} incidents={incidents} />}
                {page === 'communications' && <CommunicationsPage />}
                {page === 'upload' && <UploadPage onDataParsed={handleDataParsed} setPage={setPage} />}
                {page === 'templates' && <TemplatesPage weekData={weekData} />}
                {page === 'actions' && <ActionsPage actions={actions} onUpdate={(u) => { setActions(u); saveActions(u); }} />}
                {page === 'incidents' && <IncidentsPage incidents={incidents} onUpdate={(u) => { setIncidents(u); saveIncidents(u); }} />}
                {page === 'staff' && <StaffPage staff={staff} onUpdate={(u) => { setStaff(u); saveStaff(u); }} />}
                {(page === 'staff-tools' || page === 'notes') && <StaffNotePage setPage={setPage} />}
                {page === 'note-workspace' && <NoteWorkspace />}
                {page === 'training-hub' && <SovereignTrainingHub />}
                {page === 'handover' && <HandoverPage weekData={weekData} />}
                {page === 'compliance' && <CompliancePage staff={staff} onUpdate={(u) => { setStaff(u); saveStaff(u); }} />}
                {page === 'reports' && <ReportsPage weekData={weekData} setPage={setPage} />}
                {page === 'risk' && <RiskScoresPage weekData={weekData} onQuickAction={() => {}} />}
                {page === 'client-docs' && <ClientDocsPage />}
                {page === 'client-diary' && <ClientDiaryPage weekData={weekData} setPage={setPage} pageCtx={pageCtx} onQuickAction={() => {}} />}
                {page === 'agency' && <AgencyPortalPage />}
                {page === 'staff-monitoring' && <StaffMonitoringPage weekData={weekData} onDataParsed={handleWeekDataUpdate} setPage={setPage} />}
                {page === 'settings' && canAccessPage(userRole, 'settings') && <SettingsPage onSignOut={handleSignOut} setPage={setPage} />}
                {page === 'admin' && canAccessPage(userRole, 'admin') && <AdminPage weekData={weekData} clients={clients} />}
                {page === 'empire-matrix' && <EmpireMatrix weekData={weekData} setPage={setPage} />}
                {page === 'nourish-tasks' && <NourishTaskPack />}
              </Suspense>
            </div>

            {/* Floating Navigation Hub */}
            <div className="fixed bottom-6 right-4 z-[100] flex flex-col gap-1.5 opacity-50 hover:opacity-100 transition-opacity">
              <button
                onClick={scrollToTop}
                title="Scroll to Top"
                className="p-2 hc-clay-raised rounded-xl text-hc-teal hover:scale-110 active:scale-95 transition-all group shadow-md bg-hc-surface/80 backdrop-blur-md"
              >
                <ArrowUp className="w-3.5 h-3.5" />
              </button>
              <button
                onClick={scrollToBottom}
                title="Scroll to Bottom"
                className="p-2 hc-clay-raised rounded-xl text-hc-teal hover:scale-110 active:scale-95 transition-all group shadow-md bg-hc-surface/80 backdrop-blur-md"
              >
                <ArrowDown className="w-3.5 h-3.5" />
              </button>
            </div>
          </main>
        </div>
      </ErrorBoundary>

      {isDraggingFile && (
        <div className="fixed inset-0 z-[200] pointer-events-none animate-in fade-in duration-300">
           <div className="absolute inset-0 bg-hc-teal/10 backdrop-blur-sm border-[8px] border-dashed border-hc-teal/40 m-8 rounded-[4rem]" />
           <div className="absolute inset-0 flex items-center justify-center">
              <div className="hc-clay-raised p-12 flex flex-col items-center gap-6 animate-bounce shadow-2xl border border-hc-teal/5">
                 <Upload className="w-16 h-16 text-hc-teal" />
                 <div className="text-xl font-black text-hc-text uppercase tracking-[0.4em]">Injest Sovereign Stream</div>
              </div>
           </div>
        </div>
      )}

      {globalInjestFile && (
        <GlobalInjest
          file={globalInjestFile}
          onClose={() => setGlobalInjestFile(null)}
          onDataParsed={handleDataParsed}
          setPage={setPage}
        />
      )}
    </div>
  );
}

function LoginGate({ onUnlock }: { onUnlock: (role?: string) => void }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    const res = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
      credentials: 'include',
    });
    if (res.ok) {
      const payload = await res.json().catch(() => ({}));
      const role = normalizeUserRole(payload?.role || localStorage.getItem('hc-user-role'));
      localStorage.setItem('hc-user-role', role);
      onUnlock(role);
    }
    else setError('Invalid credentials');
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-hc-bg p-6">
      <form onSubmit={handleLogin} className="w-full max-w-sm hc-clay-raised p-10 space-y-8 rounded-[3rem] shadow-2xl border border-hc-muted/5">
        <div>
          <h1 className="text-2xl font-black text-hc-text uppercase tracking-tighter">CareOps Access</h1>
          <p className="text-[10px] font-black text-hc-muted uppercase tracking-[0.2em] mt-2">Enter credentials to open the care operations hub</p>
        </div>
        <div className="space-y-4">
          <label className="block space-y-2">
            <span className="text-[9px] font-black text-hc-muted uppercase tracking-widest">Personnel ID</span>
            <input
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="Personnel ID"
              autoComplete="username"
              className="w-full hc-clay-inset px-6 py-4 text-sm font-black text-hc-text shadow-inner focus:outline-none focus:ring-2 focus:ring-hc-teal/40"
            />
          </label>
          <label className="block space-y-2">
            <span className="text-[9px] font-black text-hc-muted uppercase tracking-widest">Access Key</span>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              placeholder="Access Key"
              autoComplete="current-password"
              className="w-full hc-clay-inset px-6 py-4 text-sm font-black text-hc-text shadow-inner focus:outline-none focus:ring-2 focus:ring-hc-teal/40"
            />
          </label>
        </div>
        {error && <div className="text-[10px] font-black text-flag-red uppercase tracking-widest text-center">{error}</div>}
        <button type="submit" className="w-full py-5 btn-tactical text-hc-bg rounded-2xl text-[11px] font-black uppercase tracking-[0.3em] shadow-xl active:scale-95 transition-all hover:scale-[1.02]">Establish Connection</button>
      </form>
    </div>
  );
}

import { useState } from 'react';
import { Calendar } from 'lucide-react';
import { getStoreBounds } from '../lib/entry-store';

export interface DateRange {
  from: string | null; // DD/MM/YYYY
  to: string | null;
}

export type RangePreset = 'all' | 'today' | 'this-week' | 'last-week' | 'this-month' | 'last-month' | 'custom';

function toddmmyyyy(d: Date): string {
  return [
    String(d.getDate()).padStart(2, '0'),
    String(d.getMonth() + 1).padStart(2, '0'),
    d.getFullYear(),
  ].join('/');
}

export function getPresetRange(preset: RangePreset): DateRange {
  const now = new Date();
  if (preset === 'all' || preset === 'custom') return { from: null, to: null };
  if (preset === 'today') {
    const t = toddmmyyyy(now);
    return { from: t, to: t };
  }
  if (preset === 'this-week') {
    const dow = now.getDay() || 7;
    const mon = new Date(now); mon.setDate(now.getDate() - dow + 1);
    const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
    return { from: toddmmyyyy(mon), to: toddmmyyyy(sun) };
  }
  if (preset === 'last-week') {
    const dow = now.getDay() || 7;
    const lastMon = new Date(now); lastMon.setDate(now.getDate() - dow - 6);
    const lastSun = new Date(lastMon); lastSun.setDate(lastMon.getDate() + 6);
    return { from: toddmmyyyy(lastMon), to: toddmmyyyy(lastSun) };
  }
  if (preset === 'this-month') {
    const first = new Date(now.getFullYear(), now.getMonth(), 1);
    const last = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    return { from: toddmmyyyy(first), to: toddmmyyyy(last) };
  }
  if (preset === 'last-month') {
    const first = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const last = new Date(now.getFullYear(), now.getMonth(), 0);
    return { from: toddmmyyyy(first), to: toddmmyyyy(last) };
  }
  return { from: null, to: null };
}

function toInputVal(s: string | null): string {
  if (!s) return '';
  const p = s.split('/');
  return p.length === 3 ? `${p[2]}-${p[1]}-${p[0]}` : '';
}

function fromInputVal(s: string): string {
  if (!s) return '';
  const p = s.split('-');
  return p.length === 3 ? `${p[2]}/${p[1]}/${p[0]}` : '';
}

const PRESETS: { id: RangePreset; label: string }[] = [
  { id: 'all',        label: 'All Time' },
  { id: 'this-week',  label: 'This Week' },
  { id: 'last-week',  label: 'Last Week' },
  { id: 'this-month', label: 'This Month' },
  { id: 'last-month', label: 'Last Month' },
  { id: 'custom',     label: 'Custom' },
];

interface Props {
  range: DateRange;
  onChange: (r: DateRange) => void;
  entryCount?: number;
  compact?: boolean;
}

export function DateRangePicker({ range, onChange, entryCount, compact }: Props) {
  const [activePreset, setActivePreset] = useState<RangePreset>('all');
  const bounds = getStoreBounds();

  const applyPreset = (preset: RangePreset) => {
    setActivePreset(preset);
    if (preset !== 'custom') onChange(getPresetRange(preset));
  };

  return (
    <div className={`hc-clay-raised rounded-2xl flex flex-wrap items-center gap-3 ${compact ? 'p-3' : 'p-4'}`}>
      <div className="flex items-center gap-2 shrink-0">
        <Calendar className="w-4 h-4 text-hc-teal" />
        {!compact && (
          <span className="text-[10px] font-black text-hc-muted uppercase tracking-widest">Time Range</span>
        )}
        {bounds && !compact && (
          <span className="text-[9px] font-black text-hc-muted/50 uppercase">
            · {bounds.count.toLocaleString()} entries · {bounds.from} → {bounds.to}
          </span>
        )}
        {bounds && compact && (
          <span className="text-[9px] font-black text-hc-muted/50 tabular-nums">{bounds.count.toLocaleString()} stored</span>
        )}
      </div>

      <div className="flex flex-wrap gap-1.5">
        {PRESETS.map(p => (
          <button
            key={p.id}
            onClick={() => applyPreset(p.id)}
            className={`text-[9px] font-black uppercase tracking-widest px-3 py-1.5 rounded-xl transition-all ${
              activePreset === p.id
                ? 'bg-hc-teal text-hc-bone shadow-md'
                : 'hc-clay-inset text-hc-muted hover:text-hc-text'
            }`}
          >
            {p.label}
          </button>
        ))}
      </div>

      {activePreset === 'custom' && (
        <div className="flex items-center gap-2 animate-in slide-in-from-top-2 duration-300">
          <input
            type="date"
            value={toInputVal(range.from)}
            onChange={e => onChange({ ...range, from: fromInputVal(e.target.value) })}
            className="hc-clay-inset rounded-xl px-3 py-1.5 text-[10px] font-black text-hc-text focus:outline-none"
          />
          <span className="text-hc-muted text-[10px] font-black">→</span>
          <input
            type="date"
            value={toInputVal(range.to)}
            onChange={e => onChange({ ...range, to: fromInputVal(e.target.value) })}
            className="hc-clay-inset rounded-xl px-3 py-1.5 text-[10px] font-black text-hc-text focus:outline-none"
          />
        </div>
      )}

      {entryCount !== undefined && (
        <div className="ml-auto flex items-center gap-2 hc-clay-inset rounded-xl px-4 py-2">
          <div className="w-1.5 h-1.5 rounded-full bg-hc-teal animate-pulse" />
          <span className="text-[10px] font-black text-hc-text tabular-nums">
            {entryCount.toLocaleString()} in range
          </span>
        </div>
      )}
    </div>
  );
}

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false
  };

  public static getDerivedStateFromError(_: Error): State {
    return { hasError: true };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
    // Auto-clear corrupt localStorage keys on first catch — preserves week data
    try {
      localStorage.removeItem('hazelcare-ops');
      localStorage.removeItem('hc_current_page');
      localStorage.removeItem('hc-registered-sessions');
      localStorage.removeItem('hc-entry-store-v3');
      indexedDB.deleteDatabase('hazel-care-ops');
    } catch { /* ignore */ }
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-hc-bg flex items-center justify-center p-10 font-sans">
          <div className="hc-clay-raised p-12 max-w-md w-full text-center space-y-6 border border-flag-red/20">
            <div className="w-16 h-16 bg-flag-red/10 rounded-2xl flex items-center justify-center text-flag-red mx-auto animate-pulse">
              <AlertTriangle size={32} />
            </div>
            <div>
              <h1 className="text-xl font-black text-hc-text uppercase tracking-tighter">System Recovery Mode</h1>
              <p className="text-[11px] font-bold text-hc-muted uppercase tracking-widest mt-2 leading-relaxed">
                State reset complete. Reload to resume.
              </p>
            </div>
            <button
              onClick={() => window.location.reload()}
              className="w-full py-4 rounded-xl btn-tactical flex items-center justify-center gap-3 font-black text-[10px] uppercase tracking-[0.2em] shadow-xl"
            >
              <RefreshCw size={14} className="animate-spin-slow" />
              Reload System
            </button>
            <p className="text-[9px] font-black text-hc-muted uppercase opacity-40">Ops · Safe Mode Active</p>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import { useState, useEffect } from 'react';
import { RefreshCw, FileText, CheckCircle, AlertTriangle, Sparkles, Zap, ArrowRight, X, Archive } from 'lucide-react';
import JSZip from 'jszip';
import { buildEnvelopeFromRaw } from '../lib/import-profiles';
import { extractFileText } from '../lib/universal-extractor';
import { routeImport } from '../lib/import-router';
import { loadWeekData } from '../lib/storage';
import { appendEntries } from '../lib/entry-store';
import { enrichEntriesWithRoster, parseClientRosterCSV, saveRosterShifts } from '../lib/roster-store';
import { parseRosterCSV as parseGroupedRosterCSV } from '../lib/universal-parser';
import type { NormalizedImportEnvelope } from '../lib/import-intelligence';
import type { Page } from '../lib/types';
import { ORG_CONFIG } from '../lib/config';

interface Props {
  file: File | null;
  onClose: () => void;
  onDataParsed: (data: any) => void;
  setPage: (p: Page) => void;
}

export function GlobalInjest({ file, onClose, onDataParsed, setPage }: Props) {
  const [loading, setLoading] = useState(false);
  const [envelope, setEnvelope] = useState<NormalizedImportEnvelope | null>(null);
  const [zipEnvelopes, setZipEnvelopes] = useState<NormalizedImportEnvelope[]>([]);
  const [error, setError] = useState('');
  const [done, setDone] = useState(false);
  const [resultSummary, setResultSummary] = useState('');

  useEffect(() => {
    if (file) {
      void processFile(file);
    }
  }, [file]);

  const processFile = async (f: File) => {
    setLoading(true);
    setError('');
    try {
      const ext = f.name.split('.').pop()?.toLowerCase();
      if (ext === 'zip') {
        const zip = await JSZip.loadAsync(await f.arrayBuffer());
        const entries = Object.values(zip.files).filter(entry => !entry.dir);
        const supported = entries.filter(entry => /\.(txt|csv|tsv|md|pdf|docx|xlsx|xls|xlsm)$/i.test(entry.name));

        if (!supported.length) {
          throw new Error('No supported clinical files found in this ZIP.');
        }

        const envs: NormalizedImportEnvelope[] = [];
        for (const entry of supported) {
          const displayName = entry.name.split('/').pop() || entry.name;
          let text = '';
          const entryExt = entry.name.split('.').pop()?.toLowerCase();

          if (entryExt === 'pdf' || entryExt === 'docx' || entryExt === 'xlsx' || entryExt === 'xls' || entryExt === 'xlsm') {
            const blob = await entry.async('blob');
            const nestedFile = new File([blob], displayName);
            text = await extractFileText(nestedFile);
          } else {
            text = await entry.async('text');
          }

          const env = buildEnvelopeFromRaw(displayName, text);
          envs.push(env);
        }
        setZipEnvelopes(envs);
        // Create a summary envelope for the UI.
        const summary = buildEnvelopeFromRaw(f.name, '');
        summary.source.detectedType = 'unknown';
        summary.source.confidence = 1.0;
        setEnvelope(summary);
      } else {
        const text = await extractFileText(f);
        const env = buildEnvelopeFromRaw(f.name, text);
        setEnvelope(env);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'File extraction failed');
    } finally {
      setLoading(false);
    }
  };

  const mapBatchTargets = (env: NormalizedImportEnvelope, fallback: 'reports' | 'templates' | 'client-docs') => {
    if (env.source.detectedType === 'roster' || env.shifts?.length) return ['roster' as const];
    if (env.diaryEntries?.length || env.weekSummary) return ['reports' as const];
    if (env.admission || env.supportPlan) return ['client-docs' as const];
    return [fallback];
  };

  const saveRosterEnvelope = async (env: NormalizedImportEnvelope) => {
    let shifts = parseClientRosterCSV(env.rawText || '');
    if (shifts.length === 0) {
      const grouped = parseGroupedRosterCSV(env.rawText || '', env.source.fileName);
      shifts = grouped.map(shift => ({
        id: shift.id,
        client: shift.house || shift.staffId || 'Unassigned',
        clientRaw: shift.house || shift.staffId || 'Unassigned',
        house: '',
        date: shift.date,
        startTime: shift.startTime,
        endTime: shift.endTime,
        carers: shift.staffId ? [shift.staffId] : [],
        durationHours: shift.hours,
        shiftType: shift.type === 'long_day' ? 'long' : shift.type,
      }));
    }
    if (shifts.length) await saveRosterShifts(shifts);
    return shifts.length;
  };

  const handleRoute = async (target: 'reports' | 'templates' | 'client-docs') => {
    if (!envelope && !zipEnvelopes.length) return;

    setLoading(true);
    try {
      if (zipEnvelopes.length > 0) {
        let totalAdded = 0;
        let totalShifts = 0;
        let successCount = 0;

        for (const env of zipEnvelopes) {
          const targets = mapBatchTargets(env, target);
          if (targets.includes('roster')) {
            const added = await saveRosterEnvelope(env);
            if (added > 0) {
              totalShifts += added;
              successCount++;
            }
            continue;
          }

          const res = routeImport(env, { targets, clientMode: 'auto' });
          if (res.ok) {
            successCount++;
            if (env.diaryEntries?.length) {
              const enriched = await enrichEntriesWithRoster(env.diaryEntries);
              totalAdded += appendEntries(enriched);
            }
          }
        }

        setResultSummary(`Batch processed: ${successCount} files, ${totalAdded} entries and ${totalShifts} roster shifts added.`);
        if (target === 'reports') {
          const data = loadWeekData();
          if (data) onDataParsed(data);
        }
      } else if (envelope) {
        const res = routeImport(envelope, { targets: [target], clientMode: 'auto' });
        if (res.ok) {
          if (envelope.diaryEntries?.length) {
            const enriched = await enrichEntriesWithRoster(envelope.diaryEntries);
            appendEntries(enriched);
          }
          if (target === 'reports') {
            const data = loadWeekData();
            if (data) onDataParsed(data);
          }
          setResultSummary(res.messages[0] || 'Ingest successful');
        } else {
          throw new Error(res.warnings[0] || 'Routing failed');
        }
      }

      setDone(true);
      setTimeout(() => {
        onClose();
      }, 2000);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Routing failed');
    } finally {
      setLoading(false);
    }
  };

  if (!file) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-hc-text/20 backdrop-blur-md" onClick={onClose} />

      <div className="w-full max-w-xl hc-clay-raised relative overflow-hidden animate-in zoom-in-95 slide-in-from-bottom-8 duration-500">
        <div className="absolute top-0 left-0 w-full h-1 bg-hc-teal" />

        {/* Header */}
        <div className="p-8 border-b border-hc-muted/10 flex items-center justify-between bg-black/[0.02]">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-2xl hc-clay-inset flex items-center justify-center">
              <Zap className={`w-6 h-6 text-hc-teal ${loading ? 'animate-pulse' : ''}`} />
            </div>
            <div>
              <h2 className="text-xl font-black text-hc-text tracking-tighter uppercase leading-none">Quick Import</h2>
              <p className="text-[10px] font-black text-hc-muted uppercase tracking-[0.2em] mt-1.5 opacity-60">File detected: {file.name}</p>
            </div>
          </div>
          <button onClick={onClose} className="text-hc-muted hover:text-hc-text transition-colors">
            <X className="w-6 h-6" strokeWidth={3} />
          </button>
        </div>

        <div className="p-10">
          {loading && (
            <div className="py-10 flex flex-col items-center gap-6">
              <RefreshCw className="w-12 h-12 text-hc-teal animate-spin" strokeWidth={1.5} />
              <div className="text-[11px] font-black text-hc-text uppercase tracking-[0.3em]">Decoding Clinical Stream...</div>
            </div>
          )}

          {error && (
            <div className="p-8 rounded-2xl hc-clay-inset bg-flag-red/5 border border-flag-red/20 flex flex-col items-center gap-4">
              <AlertTriangle className="w-10 h-10 text-flag-red" />
              <div className="text-[11px] font-black text-flag-red uppercase tracking-widest text-center leading-loose">{error}</div>
              <button onClick={onClose} className="mt-4 px-8 py-3 rounded-xl hc-clay-raised text-[10px] font-black uppercase text-hc-text hover:brightness-90 transition-all">Dismiss Fault</button>
            </div>
          )}

          {envelope && !loading && !done && (
            <div className="animate-in fade-in duration-700 space-y-10">
              <div className="grid grid-cols-2 gap-4">
                <div className="hc-clay-inset p-5 flex items-center gap-4">
                   {zipEnvelopes.length > 0 ? <Archive className="w-5 h-5 text-hc-teal" /> : <Zap className="w-5 h-5 text-hc-teal" />}
                   <div>
                     <div className="text-[8px] font-black text-hc-muted uppercase tracking-widest mb-1">Import Type</div>
                     <div className="text-sm font-black text-hc-teal uppercase tracking-tighter">
                       {zipEnvelopes.length > 0 ? `ZIP BATCH (${zipEnvelopes.length})` : envelope.source.detectedType}
                     </div>
                   </div>
                </div>
                <div className="hc-clay-inset p-5">
                   <div className="text-[8px] font-black text-hc-muted uppercase tracking-widest mb-1">Confidence</div>
                   <div className="text-sm font-black text-hc-text tabular-nums">{Math.round(envelope.source.confidence * 100)}%</div>
                </div>
              </div>

              {zipEnvelopes.length > 0 && (
                <div className="hc-clay-inset p-4 max-h-[120px] overflow-y-auto scrollbar-thin space-y-2">
                   {zipEnvelopes.map((env, i) => (
                     <div key={i} className="flex items-center justify-between text-[9px] font-black uppercase text-hc-muted">
                        <span className="truncate max-w-[70%]">{env.source.fileName}</span>
                        <span className="text-hc-teal">{env.source.detectedType}</span>
                     </div>
                   ))}
                </div>
              )}

              <div className="space-y-4">
                <p className="text-[10px] font-black text-hc-text uppercase tracking-[0.3em] opacity-40 px-1">Choose where this should go</p>
                <div className="flex flex-col gap-3">
                  <button onClick={() => handleRoute('reports')}
                    className="w-full p-6 hc-clay-raised hover:border-hc-teal/40 group flex items-center justify-between transition-all active:scale-[0.98]">
                    <div className="flex items-center gap-5">
                      <FileText className="w-5 h-5 text-hc-teal" />
                      <div className="text-left">
                        <div className="text-xs font-black text-hc-text uppercase tracking-widest">Add to Live Records</div>
                        <div className="text-[9px] font-black text-hc-muted uppercase tracking-widest mt-1">Route to Client Diaries & Quality Monitoring</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-hc-muted opacity-0 group-hover:opacity-100 transition-all" />
                  </button>

                  <button onClick={() => handleRoute('client-docs')}
                    className="w-full p-6 hc-clay-raised hover:border-hc-teal/40 group flex items-center justify-between transition-all active:scale-[0.98]">
                    <div className="flex items-center gap-5">
                      <Sparkles className="w-5 h-5 text-hc-teal" />
                      <div className="text-left">
                        <div className="text-xs font-black text-hc-text uppercase tracking-widest">Client Documents</div>
                        <div className="text-[9px] font-black text-hc-muted uppercase tracking-widest mt-1">Update Care Plans, Risk Matrices & PBS Protocols</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-hc-muted opacity-0 group-hover:opacity-100 transition-all" />
                  </button>
                </div>
              </div>
            </div>
          )}

          {done && (
            <div className="py-12 flex flex-col items-center gap-8 animate-in zoom-in-95 duration-500">
              <div className="w-24 h-24 rounded-3xl bg-flag-green/10 border-2 border-flag-green/30 flex items-center justify-center shadow-2xl">
                <CheckCircle className="w-12 h-12 text-flag-green" strokeWidth={3} />
              </div>
              <div className="text-center">
                <h3 className="text-2xl font-black text-hc-text tracking-tighter uppercase">Import Complete</h3>
                <p className="text-[10px] font-black text-flag-green uppercase tracking-[0.2em] mt-2 font-mono italic">{resultSummary}</p>
                <p className="text-[10px] font-black text-hc-muted uppercase tracking-[0.2em] mt-4">OS state synchronized with {ORG_CONFIG.name} registration</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
