import type { FullClient } from './client-store';
import { emptyClient, loadClients, resolveClientMatch, saveClient } from './client-store';
import { mergeClientIdentity } from './client-identity-merge';
import { mergeCarePlanData, mergeRiskData, mergeSupportPlanData } from './intel-merge';
import type { ImportTarget, NormalizedImportEnvelope } from './import-intelligence';
import type { TemplateType } from './types';
import { exportOpsSnapshot, importOpsSnapshot, loadWeekData, mergeWeekSummaries, saveWeekData, loadShifts, saveShifts } from './storage';
import type { Page } from './types';

const TEMPLATE_CONTEXT_KEY = 'hc-template-import-context';

export type ClientMode = 'specific' | 'auto' | 'global';

export interface RouteImportOptions {
  targets: ImportTarget[];
  clientMode: ClientMode;
  selectedClientId?: string | null;
  selectedTemplateIds?: TemplateType[];
}

export interface RouteImportResult {
  ok: boolean;
  page: Page;
  messages: string[];
  warnings: string[];
  requiresManualClientSelection?: boolean;
}

function pickClient(envelope: NormalizedImportEnvelope, opts: RouteImportOptions): { client: FullClient; existed: boolean; requiresManualSelection: boolean } {
  if (opts.clientMode === 'specific' && opts.selectedClientId) {
    const selected = loadClients().find(c => c.id === opts.selectedClientId);
    if (selected) return { client: { ...selected }, existed: true, requiresManualSelection: false };
  }

  const candidate = envelope.clientCandidates[0] || {};
  const resolution = resolveClientMatch({
    name: candidate.name,
    nhs: candidate.nhs,
    dob: candidate.dob,
  });

  if (resolution.best) {
    // In global mode we still try to prevent duplicates:
    // - always trust deterministic matches (NHS / name+DOB)
    // - trust strong fuzzy matches only (>=0.9)
    const canAutoUseGlobal =
      opts.clientMode === 'global' &&
      (resolution.best.strategy === 'nhs' || resolution.best.strategy === 'name_dob' || resolution.best.score >= 0.9);

    if (opts.clientMode !== 'global' || canAutoUseGlobal) {
      return {
        client: { ...resolution.best.client },
        existed: true,
        requiresManualSelection: opts.clientMode === 'global' ? false : resolution.requiresManualSelection,
      };
    }
  }

  return { client: emptyClient(), existed: false, requiresManualSelection: opts.clientMode !== 'global' };
}

export function routeImport(envelope: NormalizedImportEnvelope, opts: RouteImportOptions): RouteImportResult {
  const messages: string[] = [];
  const warnings: string[] = [...envelope.warnings];
  const previousWeekData = loadWeekData();
  const snapshot = exportOpsSnapshot();

  try {
    const selectedClient = opts.selectedClientId ? loadClients().find(c => c.id === opts.selectedClientId) : null;
    if (opts.clientMode === 'specific' && !opts.selectedClientId) {
      return { ok: false, page: 'upload', messages: [], warnings: ['Specific client mode requires selecting a client.'] };
    }
    if (opts.clientMode === 'specific' && opts.selectedClientId && !selectedClient) {
      return { ok: false, page: 'upload', messages: [], warnings: ['Selected client no longer exists. Choose a valid client and retry.'] };
    }

    const needsClientWrite = (opts.targets.includes('client-docs') || opts.targets.includes('templates')) && !!(envelope.admission || envelope.supportPlan);
    let preValidatedPick: { client: FullClient; existed: boolean; requiresManualSelection: boolean } | null = null;
    if (needsClientWrite) {
      preValidatedPick = pickClient(envelope, opts);
      if (opts.clientMode === 'auto' && preValidatedPick.requiresManualSelection) {
        return {
          ok: false,
          page: 'upload',
          messages: [],
          warnings: ['Client match confidence is low. Select a specific client before importing.'],
          requiresManualClientSelection: true,
        };
      }
    }

    if (opts.targets.includes('reports') || opts.targets.includes('templates')) {
      if (envelope.weekSummary) {
        const currentWeekData = loadWeekData();
        const mergedWeekData = mergeWeekSummaries(currentWeekData, envelope.weekSummary);
        saveWeekData(mergedWeekData);
        messages.push(`Loaded ${envelope.weekSummary.totalEntries} diary entries (${mergedWeekData.totalEntries} total in reporting state).`);
      } else if (opts.targets.includes('reports')) {
        warnings.push('Reports target selected but no diary summary data was parsed.');
      }
    }

    let requiresManualClientSelection = false;
    if (opts.targets.includes('client-docs') || opts.targets.includes('templates')) {
      if (envelope.admission || envelope.supportPlan) {
        const picked = preValidatedPick || pickClient(envelope, opts);
        const client = picked.client;
        const today = new Date().toLocaleDateString('en-GB');
        requiresManualClientSelection = picked.requiresManualSelection;

        if (envelope.clientCandidates[0]?.name && !client.name) {
          client.name = envelope.clientCandidates[0].name || '';
          client.preferredName = envelope.clientCandidates[0].preferredName || client.name.split(' ')[0] || '';
        }

        if (envelope.admission) {
          const mergedIdentity = mergeClientIdentity(client as FullClient, envelope.admission.client);
          Object.assign(client, mergedIdentity);

          // ADDITIVE MERGE for Care Plan and Risk
          client.carePlan = mergeCarePlanData(client.carePlan || null, envelope.admission.carePlan, today);
          if (envelope.admission.client.risk) {
            client.risk = mergeRiskData(client.risk || null, envelope.admission.client.risk, today);
          }

          messages.push(`${client.name || 'Client'} ${picked.existed ? 'merged' : 'created'} from admission/risk/care-plan data.`);
        }

        if (envelope.supportPlan) {
          const previousCount = client.supportPlan?.needs?.length || 0;
          client.supportPlan = mergeSupportPlanData(client.supportPlan || null, envelope.supportPlan);
          const mergedCount = client.supportPlan?.needs?.length || 0;
          const delta = Math.max(0, mergedCount - previousCount);
          messages.push(`${client.name || 'Client'} support plan merged (${mergedCount} areas, +${delta} new).`);
        }

        saveClient(client as FullClient);
      } else if (opts.targets.includes('client-docs')) {
        warnings.push('Client docs target selected but no client-doc source fields were parsed.');
      }
    }

    if (opts.targets.includes('templates')) {
      let prev: Record<string, unknown> = {};
      try {
        const raw = localStorage.getItem(TEMPLATE_CONTEXT_KEY);
        if (raw) prev = JSON.parse(raw) as Record<string, unknown>;
      } catch {
        /* ignore */
      }
      const selectedTemplateIds =
        opts.selectedTemplateIds !== undefined
          ? opts.selectedTemplateIds
          : ((prev.selectedTemplateIds as TemplateType[] | undefined) ?? []);
      const context = {
        ...prev,
        at: new Date().toISOString(),
        parserProfile: envelope.source.parserProfile,
        detectedType: envelope.source.detectedType,
        hasWeekSummary: !!envelope.weekSummary,
        hasAdmission: !!envelope.admission,
        hasSupportPlan: !!envelope.supportPlan,
        selectedTemplateIds,
      };
      localStorage.setItem(TEMPLATE_CONTEXT_KEY, JSON.stringify(context));
      messages.push(
        (opts.selectedTemplateIds?.length || 0) > 0
          ? `Template context prepared (${opts.selectedTemplateIds!.length} selected).`
          : 'Template context prepared from imported source data.'
      );
    }

    const page: Page = opts.targets.includes('templates') && !!envelope.weekSummary
      ? 'templates'
      : opts.targets.includes('client-docs')
      ? 'client-docs'
      : opts.targets.includes('roster')
      ? 'dashboard'
      : 'reports';

    if (opts.targets.includes('roster') && envelope.shifts.length > 0) {
      const existingShifts = loadShifts();
      const staff = (() => {
        try {
          return JSON.parse(localStorage.getItem('hazelcare-staff') || '[]');
        } catch { return []; }
      })();

      const resolvedShifts = envelope.shifts.map(s => {
        const found = staff.find((sm: any) => sm.name.toLowerCase().includes(s.staffId.toLowerCase()) || s.staffId.toLowerCase().includes(sm.name.toLowerCase()));
        return {
          ...s,
          staffId: found ? found.id : s.staffId // fallback to name if not found
        };
      });

      // Filter out duplicate shifts (same staff, same date, same type)
      const merged = [...existingShifts];
      let added = 0;
      for (const rs of resolvedShifts) {
        const isDuplicate = merged.some(es => es.staffId === rs.staffId && es.date === rs.date && es.type === rs.type);
        if (!isDuplicate) {
          merged.push(rs);
          added++;
        }
      }
      saveShifts(merged);
      messages.push(`Imported ${added} new shifts to the Live Roster.`);
    }

    return { ok: true, page, messages, warnings, requiresManualClientSelection };
  } catch (err) {
    const rollback = importOpsSnapshot(snapshot);
    saveWeekData(previousWeekData);
    const msg = err instanceof Error ? err.message : 'Unknown import error';
    const rollbackMsg = rollback.ok ? '' : ` Rollback failed: ${rollback.error}`;
    return { ok: false, page: 'upload', messages: [], warnings: [`Import rolled back: ${msg}.${rollbackMsg}`.trim()] };
  }
}

import fs from 'node:fs';
import path from 'node:path';
import JSZip from 'jszip';
import { describe, expect, it } from 'vitest';
import { buildEnvelopeFromRaw } from './import-profiles';
import { extractFileText } from './universal-extractor';

const ROOTS = [
  'C:\\Users\\brook\\Downloads\\type of datasets extracts from careplanner or similar',
  'C:\\Users\\brook\\Downloads\\WJ.zip',
  'C:\\Users\\brook\\Downloads\\careplanner-extracts.zip',
  'C:\\Users\\brook\\Downloads\\Client-diary (57).csv',
  'C:\\Users\\brook\\Downloads\\Client-diary (56).csv',
  'C:\\Users\\brook\\Downloads\\Client-diary (55).csv',
  'C:\\Users\\brook\\Downloads\\Client-diarykm (53).csv',
  'C:\\Users\\brook\\Downloads\\Client-roster-from-01_04_2026-to-20_05_2026.pdf',
  'C:\\Users\\brook\\Downloads\\Client-medication-administration-report.pdf',
];

const SUPPORTED = new Set(['txt', 'csv', 'tsv', 'md', 'pdf', 'docx', 'xlsx', 'xls', 'xlsm', 'zip']);
const BINARY_TEXT_EXTS = new Set(['pdf', 'docx', 'xlsx', 'xls', 'xlsm']);
const REPORT_PATH = path.join(process.cwd(), 'docs', 'audits', 'import-stress-report-2026-05-21.json');

type StressCase = {
  source: string;
  fileName: string;
  size: number;
  kind: 'file' | 'zip-entry';
  zipPath?: string;
};

type CaseResult = StressCase & {
  detectedType?: string;
  parserProfile?: string;
  diaryEntries?: number;
  weekEntries?: number;
  clientCandidates?: number;
  supportNeeds?: number;
  warnings?: string[];
  textLength?: number;
  ms?: number;
  error?: string;
};

function extOf(fileName: string): string {
  return fileName.split('.').pop()?.toLowerCase() || '';
}

function collectFiles(inputPath: string): StressCase[] {
  if (!fs.existsSync(inputPath)) return [];
  const stat = fs.statSync(inputPath);
  if (stat.isFile()) {
    const ext = extOf(inputPath);
    return SUPPORTED.has(ext)
      ? [{ source: inputPath, fileName: path.basename(inputPath), size: stat.size, kind: 'file' }]
      : [];
  }

  const out: StressCase[] = [];
  const stack = [inputPath];
  while (stack.length) {
    const current = stack.pop() as string;
    for (const item of fs.readdirSync(current, { withFileTypes: true })) {
      const full = path.join(current, item.name);
      if (item.isDirectory()) {
        stack.push(full);
        continue;
      }
      const ext = extOf(item.name);
      if (SUPPORTED.has(ext)) {
        out.push({ source: full, fileName: item.name, size: fs.statSync(full).size, kind: 'file' });
      }
    }
  }
  return out;
}

async function expandZip(file: StressCase): Promise<StressCase[]> {
  const zip = await JSZip.loadAsync(fs.readFileSync(file.source));
  const cases: StressCase[] = [];
  for (const entry of Object.values(zip.files)) {
    if (entry.dir) continue;
    const innerName = entry.name.split('/').pop() || entry.name;
    const ext = extOf(innerName);
    if (!SUPPORTED.has(ext) || ext === 'zip') continue;
    cases.push({
      source: entry.name,
      fileName: innerName,
      size: 0,
      kind: 'zip-entry',
      zipPath: file.source,
    });
  }
  return cases;
}

async function readCaseText(testCase: StressCase): Promise<string> {
  const ext = extOf(testCase.fileName);
  if (testCase.kind === 'zip-entry') {
    if (!testCase.zipPath) throw new Error('Zip entry missing zipPath');
    const zip = await JSZip.loadAsync(fs.readFileSync(testCase.zipPath));
    const entry = zip.file(testCase.source);
    if (!entry) throw new Error(`Zip entry not found: ${testCase.source}`);
    if (BINARY_TEXT_EXTS.has(ext)) {
      const blob = await entry.async('blob');
      return extractFileText(new File([blob], testCase.fileName));
    }
    return entry.async('text');
  }

  if (BINARY_TEXT_EXTS.has(ext)) {
    return extractFileText(new File([fs.readFileSync(testCase.source)], testCase.fileName));
  }
  return fs.readFileSync(testCase.source, 'utf8');
}

describe('import stress report', () => {
  it('parses the selected real files and zip entries and writes a report', async () => {
    const directFiles = ROOTS.flatMap(collectFiles);
    const expanded: StressCase[] = [];
    for (const file of directFiles) {
      if (extOf(file.fileName) === 'zip') {
        expanded.push(...await expandZip(file));
      } else {
        expanded.push(file);
      }
    }

    const seen = new Set<string>();
    const cases = expanded.filter((item) => {
      const key = `${item.kind}:${item.zipPath || ''}:${item.source}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });

    const results: CaseResult[] = [];
    for (const testCase of cases) {
      const started = Date.now();
      try {
        const text = await readCaseText(testCase);
        const envelope = buildEnvelopeFromRaw(testCase.fileName, text);
        results.push({
          ...testCase,
          detectedType: envelope.source.detectedType,
          parserProfile: envelope.source.parserProfile,
          diaryEntries: envelope.diaryEntries?.length || 0,
          weekEntries: envelope.weekSummary?.totalEntries || 0,
          clientCandidates: envelope.clientCandidates?.length || 0,
          supportNeeds: envelope.supportPlan?.needs?.length || 0,
          warnings: envelope.warnings,
          textLength: text.length,
          ms: Date.now() - started,
        });
      } catch (error: any) {
        results.push({
          ...testCase,
          error: error?.message || String(error),
          ms: Date.now() - started,
        });
      }
    }

    const typeCounts = results.reduce<Record<string, number>>((acc, item) => {
      const key = item.error ? 'error' : item.detectedType || 'unknown';
      acc[key] = (acc[key] || 0) + 1;
      return acc;
    }, {});
    const totals = {
      roots: ROOTS.filter((root) => fs.existsSync(root)).length,
      cases: results.length,
      failures: results.filter((item) => item.error).length,
      diaryEntries: results.reduce((sum, item) => sum + (item.diaryEntries || 0), 0),
      weekEntries: results.reduce((sum, item) => sum + (item.weekEntries || 0), 0),
      clientCandidates: results.reduce((sum, item) => sum + (item.clientCandidates || 0), 0),
      supportNeeds: results.reduce((sum, item) => sum + (item.supportNeeds || 0), 0),
      typeCounts,
      slowest: [...results].sort((a, b) => (b.ms || 0) - (a.ms || 0)).slice(0, 10),
      largestText: [...results].sort((a, b) => (b.textLength || 0) - (a.textLength || 0)).slice(0, 10),
    };

    fs.mkdirSync(path.dirname(REPORT_PATH), { recursive: true });
    fs.writeFileSync(REPORT_PATH, JSON.stringify({ generatedAt: new Date().toISOString(), totals, results }, null, 2));

    // eslint-disable-next-line no-console
    console.log('[import stress report]', totals);

    expect(results.length).toBeGreaterThan(0);
    expect(totals.failures).toBe(0);
    expect(totals.diaryEntries + totals.weekEntries).toBeGreaterThan(0);
  }, 180000);
});

import type { FullClient, CarePlanData, CarePlanDomain, RiskData, RiskItem, PBSData, DiagnosisRow, FunctionRow, WarningSignRow, MedicationRow, AgencyRow, SupportPlanData, SupportPlanNeed } from './client-store';
import { emptyRisk, emptyRisk_item } from './client-store';

/**
 * HAZELCARE INTEL MERGE — Additive Data Syncing
 * Ensures that new imports/uploads append to or refine existing data rather than wiping it.
 */

function clean(text: string | undefined | null): string {
  if (!text) return '';
  return text.split('\u0000').join('').replace(/\s+/g, ' ').trim();
}

function hasText(text: string | undefined | null): boolean {
  return clean(text).length > 0;
}

export function hasMeaningfulRiskData(risk: RiskData | null | undefined): boolean {
  if (!risk) return false;
  return (risk.risks || []).some((r) =>
    hasText(r.title) ||
    hasText(r.description) ||
    (r.controls || []).some(hasText) ||
    (r.triggers || []).some(hasText) ||
    (r.earlyWarnings || []).some(hasText)
  );
}

export function hasMeaningfulCarePlanData(carePlan: CarePlanData | null | undefined): boolean {
  if (!carePlan) return false;
  if (hasText(carePlan.biography) || hasText(carePlan.criticalInfo) || hasText(carePlan.emergencyInfo)) return true;
  return (carePlan.domains || []).some((d) =>
    d.enabled ||
    hasText(d.identifiedNeed) ||
    hasText(d.plannedOutcomes) ||
    hasText(d.howToAchieve) ||
    hasText(d.riskTitle) ||
    hasText(d.riskMitigation)
  );
}

function hasMeaningfulSupportPlanData(plan: SupportPlanData | null | undefined): boolean {
  if (!plan) return false;
  return (plan.needs || []).some((n) =>
    hasText(n.area) ||
    hasText(n.canDoMyself) ||
    hasText(n.risks) ||
    hasText(n.howToSupport)
  );
}

function splitSentences(text: string): string[] {
  return clean(text)
    .split(/[.!?]\s+/)
    .map(s => s.trim())
    .filter(s => s.length > 3);
}

function mergeText(base: string, incoming: string): string {
  const baseNorm = clean(base);
  const incNorm = clean(incoming);
  if (!incNorm) return baseNorm;
  if (!baseNorm) return incNorm;

  const baseSentences = splitSentences(baseNorm);
  const incSentences = splitSentences(incNorm);

  const merged = [...baseSentences];
  for (const s of incSentences) {
    if (!merged.some(existing => existing.toLowerCase().includes(s.toLowerCase()) || s.toLowerCase().includes(existing.toLowerCase()))) {
      merged.push(s);
    }
  }

  return merged.join('. ') + (merged.length > 0 ? '.' : '');
}

function mergeArrays(base: string[], incoming: string[]): string[] {
  const seen = new Set(base.map(s => s.toLowerCase().trim()));
  const merged = [...base];
  for (const s of incoming) {
    const norm = s.toLowerCase().trim();
    if (norm && !seen.has(norm)) {
      seen.add(norm);
      merged.push(s.trim());
    }
  }
  return merged;
}

// ─── RISK MERGING ─────────────────────────────────────────────────────────────

function mergeRiskItem(base: RiskItem, incoming: RiskItem): RiskItem {
  return {
    ...base,
    description: mergeText(base.description, incoming.description),
    behaviours: mergeArrays(base.behaviours, incoming.behaviours),
    affectedPeople: mergeArrays(base.affectedPeople, incoming.affectedPeople),
    triggers: mergeArrays(base.triggers, incoming.triggers),
    earlyWarnings: mergeArrays(base.earlyWarnings, incoming.earlyWarnings),
    controls: mergeArrays(base.controls, incoming.controls),
    dynamicControls: mergeArrays(base.dynamicControls, incoming.dynamicControls),
    secondaryRisk: mergeText(base.secondaryRisk, incoming.secondaryRisk),
    contingencyPlan: mergeText(base.contingencyPlan, incoming.contingencyPlan),
    leastRestrictive: mergeText(base.leastRestrictive, incoming.leastRestrictive),
    // Use higher risk scores if they differ
    likelihood: Math.max(base.likelihood, incoming.likelihood),
    impact: Math.max(base.impact, incoming.impact),
    reviewTrigger: mergeText(base.reviewTrigger, incoming.reviewTrigger),
  };
}

export function mergeRiskData(base: RiskData | null, incoming: RiskData | null, today: string): RiskData {
  const target = base || emptyRisk(today);
  if (!incoming) return target;

  const mergedRisks = [...target.risks];
  for (const incRisk of incoming.risks) {
    if (!incRisk.title) continue;
    const existingIdx = mergedRisks.findIndex(r => r.title.toLowerCase().trim() === incRisk.title.toLowerCase().trim());
    if (existingIdx >= 0) {
      mergedRisks[existingIdx] = mergeRiskItem(mergedRisks[existingIdx], incRisk);
    } else {
      mergedRisks.push({ ...emptyRisk_item(), ...incRisk });
    }
  }

  return {
    ...target,
    leastRestrictivePractice: mergeText(target.leastRestrictivePractice, incoming.leastRestrictivePractice),
    escalationProcedure: mergeText(target.escalationProcedure, incoming.escalationProcedure),
    reviewSchedule: mergeText(target.reviewSchedule, incoming.reviewSchedule),
    risks: mergedRisks.filter(r => r.title || r.description),
    planDate: incoming.planDate || target.planDate || today,
  };
}

// ─── CARE PLAN MERGING ────────────────────────────────────────────────────────

function mergeDomain(base: CarePlanDomain, incoming: CarePlanDomain): CarePlanDomain {
  if (!incoming.enabled && !incoming.identifiedNeed) return base;

  return {
    ...base,
    enabled: base.enabled || incoming.enabled,
    identifiedNeed: mergeText(base.identifiedNeed, incoming.identifiedNeed),
    plannedOutcomes: mergeText(base.plannedOutcomes, incoming.plannedOutcomes),
    howToAchieve: mergeText(base.howToAchieve, incoming.howToAchieve),
    riskTitle: mergeText(base.riskTitle, incoming.riskTitle),
    riskMitigation: mergeText(base.riskMitigation, incoming.riskMitigation),
    // Use the non-zero / more specific values
    levelOfNeed: Math.max(base.levelOfNeed, incoming.levelOfNeed),
    riskLikelihood: Math.max(base.riskLikelihood, incoming.riskLikelihood),
    riskImpact: Math.max(base.riskImpact, incoming.riskImpact),
    reviewNote: mergeText(base.reviewNote, incoming.reviewNote),
  };
}

export function mergeCarePlanData(base: CarePlanData | null, incoming: CarePlanData | null, today: string): CarePlanData | null {
  if (!incoming) return base;
  if (!hasMeaningfulCarePlanData(incoming)) return base;
  if (!base) return incoming;

  const mergedDomains = base.domains.map(baseDom => {
    const incDom = incoming.domains.find(d => d.title === baseDom.title);
    return incDom ? mergeDomain(baseDom, incDom) : baseDom;
  });

  return {
    ...base,
    biography: mergeText(base.biography, incoming.biography),
    criticalInfo: mergeText(base.criticalInfo, incoming.criticalInfo),
    emergencyInfo: mergeText(base.emergencyInfo, incoming.emergencyInfo),
    domains: mergedDomains,
    planDate: incoming.planDate || base.planDate || today,
  };
}

function supportNeedKey(need: SupportPlanNeed): string {
  const area = clean(need.area).toLowerCase();
  if (area) return area;
  return [clean(need.canDoMyself), clean(need.risks), clean(need.howToSupport)].join('|').toLowerCase();
}

function mergeSupportNeed(base: SupportPlanNeed, incoming: SupportPlanNeed): SupportPlanNeed {
  return {
    area: clean(incoming.area) || clean(base.area),
    canDoMyself: mergeText(base.canDoMyself, incoming.canDoMyself),
    risks: mergeText(base.risks, incoming.risks),
    howToSupport: mergeText(base.howToSupport, incoming.howToSupport),
  };
}

export function mergeSupportPlanData(base: SupportPlanData | null, incoming: SupportPlanData | null): SupportPlanData | null {
  if (!incoming) return base;
  if (!hasMeaningfulSupportPlanData(incoming)) return base;
  if (!base) return incoming;

  const out: SupportPlanNeed[] = [...base.needs];
  const indexByKey = new Map<string, number>();
  out.forEach((need, idx) => indexByKey.set(supportNeedKey(need), idx));

  for (const need of incoming.needs || []) {
    const key = supportNeedKey(need);
    if (!key) continue;
    const existingIdx = indexByKey.get(key);
    if (existingIdx === undefined) {
      indexByKey.set(key, out.length);
      out.push({
        area: clean(need.area),
        canDoMyself: clean(need.canDoMyself),
        risks: clean(need.risks),
        howToSupport: clean(need.howToSupport),
      });
      continue;
    }
    out[existingIdx] = mergeSupportNeed(out[existingIdx], need);
  }

  return {
    ...base,
    needs: out,
    planDate: incoming.planDate || base.planDate,
  };
}

// ─── PBS MERGING ──────────────────────────────────────────────────────────────

export function mergePBSData(base: PBSData | null, incoming: PBSData | null): PBSData | null {
  if (!incoming) return base;
  if (!base) return incoming;

  const mergeRows = <T extends object>(b: T[], i: T[], keyField: keyof T): T[] => {
    const merged = [...b];
    for (const row of i) {
      const val = clean(row[keyField] as string).toLowerCase();
      if (val && !merged.some(existing => clean(existing[keyField] as string).toLowerCase() === val)) {
        merged.push(row);
      }
    }
    return merged;
  };

  return {
    ...base,
    aboutText: mergeText(base.aboutText, incoming.aboutText),
    whatMatters: mergeArrays(base.whatMatters, incoming.whatMatters),
    communicatesBest: mergeArrays(base.communicatesBest, incoming.communicatesBest),
    findsDifficult: mergeArrays(base.findsDifficult, incoming.findsDifficult),
    diagnosisRows: mergeRows(base.diagnosisRows, incoming.diagnosisRows, 'diagnosis'),
    functionRows: mergeRows(base.functionRows, incoming.functionRows, 'behaviour'),
    envStrategies: mergeArrays(base.envStrategies, incoming.envStrategies),
    routineStrategies: mergeArrays(base.routineStrategies, incoming.routineStrategies),
    relationshipStrategies: mergeArrays(base.relationshipStrategies, incoming.relationshipStrategies),
    communicationStrategies: mergeArrays(base.communicationStrategies, incoming.communicationStrategies),
    onlineSafetyStrategies: mergeArrays(base.onlineSafetyStrategies, incoming.onlineSafetyStrategies),
    warningSignRows: mergeRows(base.warningSignRows, incoming.warningSignRows, 'sign'),
    whatWorks: mergeArrays(base.whatWorks, incoming.whatWorks),
    doesntWork: mergeArrays(base.doesntWork, incoming.doesntWork),
    medicationRows: mergeRows(base.medicationRows, incoming.medicationRows, 'name'),
    agencyRows: mergeRows(base.agencyRows, incoming.agencyRows, 'service'),
    planDate: incoming.planDate || base.planDate,
  };
}

