import { useState, useMemo, useRef, useCallback, useEffect } from 'react';
import type { WeekSummary, CareEntry, Page } from '../lib/types';
import { loadClients } from '../lib/client-store';

// ── PDF import types ──────────────────────────────────────────────────────────
interface PdfDiaryEntry {
  client: string;
  carer: string;
  date: string;
  type: string;
  entry: string;
}

async function parseDiaryPdf(file: File): Promise<PdfDiaryEntry[]> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const pdfjsLib = await import('pdfjs-dist') as any;
  pdfjsLib.GlobalWorkerOptions.workerSrc = new URL('pdfjs-dist/build/pdf.worker.mjs', import.meta.url).toString();

  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;
  let fullText = '';
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const tc = await page.getTextContent();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    fullText += (tc.items as any[]).map((it: { str: string }) => it.str).join(' ') + '\n';
  }

  // Best-effort extraction: split on date patterns and build entries
  const entries: PdfDiaryEntry[] = [];
  // Match lines like: "08/04/2026" or "8 April 2026" followed by content
  const datePattern = /(\d{1,2}[/-]\d{1,2}[/-]\d{4}|\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\w*\s+\d{4})/gi;
  const blocks = fullText.split(datePattern).filter(s => s.trim());

  // Attempt to extract client name from first block
  const clientMatch = fullText.match(/(?:Client|Service User|Name)[:\s]+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)/);
  const clientName = clientMatch ? clientMatch[1] : file.name.replace(/\.pdf$/i, '').replace(/[-_]/g, ' ').replace(/[()]/g, '').trim();

  // Attempt to extract carer names - lines starting with known patterns
  let currentDate = '';
  for (let i = 0; i < blocks.length; i++) {
    const b = blocks[i].trim();
    if (!b) continue;
    if (datePattern.test(b)) {
      currentDate = b;
      continue;
    }
    if (currentDate && b.length > 10) {
      // Try to extract carer from "Written by" or "Staff:" patterns
      const carerMatch = b.match(/(?:Written by|Staff|Carer|Author)[:\s]+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)/);
      const carer = carerMatch ? carerMatch[1] : 'Unknown';

      // Determine type
      const lower = b.toLowerCase();
      const type = lower.includes('medication') ? 'Medication'
        : lower.includes('personal care') || lower.includes('shower') || lower.includes('bath') ? 'Personal Care'
        : lower.includes('incident') ? 'Incident'
        : lower.includes('handover') ? 'Handover'
        : lower.includes('activity') || lower.includes('engagement') ? 'Activity'
        : '1:1 Support';

      entries.push({
        client: clientName,
        carer,
        date: currentDate,
        type,
        entry: b,
      });
      currentDate = '';
    }
  }

  // Fallback: if no structured entries found, create one block per page-worth of text
  if (entries.length === 0 && fullText.trim()) {
    const paragraphs = fullText.split(/\n{2,}/).filter(p => p.trim().length > 20);
    for (const p of paragraphs.slice(0, 50)) {
      entries.push({
        client: clientName,
        carer: 'Unknown',
        date: '',
        type: '1:1 Support',
        entry: p.trim(),
      });
    }
  }

  return entries;
}

interface Props {
  weekData: WeekSummary | null;
  setPage: (p: Page) => void;
  pageCtx?: { client?: string; house?: string; severity?: string };
  onQuickAction: (opts: { type: 'action' | 'incident'; content?: string; house?: string; client?: string }) => void;
}

function typeColor(type: string) {
  const t = type?.toLowerCase() || '';
  if (t.includes('incident') || t.includes('safeguarding') || t.includes('police')) return '#ef4444';
  if (t.includes('medication') || t.includes('doctor')) return '#14b8a6';
  if (t.includes('handover') || t.includes('staff')) return '#3b82f6';
  if (t.includes('activity') || t.includes('engagement')) return '#8b5cf6';
  if (t.includes('health') || t.includes('personal')) return '#f59e0b';
  return '#7a95b0';
}

function ClientStats({ entries }: { entries: CareEntry[] }) {
  const byType = useMemo(() => {
    const typeMatrix: Record<string, number> = {};
    entries.forEach(e => { typeMatrix[e.type] = (typeMatrix[e.type] || 0) + 1; });
    return Object.entries(typeMatrix).sort((a, b) => b[1] - a[1]);
  }, [entries]);

  const red = entries.filter(e => e.severity === 'red').length;
  const amber = entries.filter(e => e.severity === 'amber').length;
  const total = entries.length;

  return (
    <div className="space-y-6 mb-8">
      <div className="grid grid-cols-3 gap-3">
        <div className="hc-clay-raised border border-white/5 rounded-xl p-4 transition-all hover:scale-[1.02] shadow-lg">
          <div className="text-2xl font-black text-hc-text mb-0.5">{total}</div>
          <div className="section-header text-hc-muted text-[11px]">Total Entries</div>
        </div>
        <div className={`hc-clay-raised border border-flag-red/20 rounded-xl p-4 transition-all hover:scale-[1.02] shadow-lg ${red > 0 ? 'glow-red' : ''}`}>
          <div className={`text-2xl font-black mb-0.5 ${red > 0 ? 'text-flag-red' : 'text-hc-muted'}`}>{red}</div>
          <div className="section-header text-hc-muted text-[11px]">Red Flags</div>
        </div>
        <div className={`hc-clay-raised border border-flag-amber/20 rounded-xl p-4 transition-all hover:scale-[1.02] shadow-lg ${amber > 0 ? 'glow-amber' : ''}`}>
          <div className={`text-2xl font-black mb-0.5 ${amber > 0 ? 'text-flag-amber' : 'text-hc-muted'}`}>{amber}</div>
          <div className="section-header text-hc-muted text-[11px]">Amber Flags</div>
        </div>
      </div>

      {/* Type breakdown bar */}
      <div className="hc-clay-raised border border-white/5 rounded-xl p-5">
        <h3 className="section-header text-hc-text mb-4 flex items-center gap-2">
          <span className="w-1.5 h-1.5 rounded-full bg-hc-teal animate-pulse" />
          Weekly Patterns
        </h3>
        <div className="space-y-3">
          {byType.slice(0, 8).map(([type, count]) => (
            <div key={type} className="flex items-center gap-4 group/row cursor-default">
              <div className="text-[11px] font-bold text-hc-muted w-40 truncate group-hover/row:text-hc-text transition-colors uppercase tracking-wider">{type}</div>
              <div className="flex-1 h-2 bg-hc-dark/80 rounded-full overflow-hidden shadow-inner">
                <div className="h-full rounded-full transition-all duration-700 ease-out shadow-[0_0_8px_rgba(20,184,166,0.2)]" 
                  style={{ width: `${(count / total) * 100}%`, background: `linear-gradient(90deg, ${typeColor(type)}99, ${typeColor(type)})` }} />
              </div>
              <div className="text-xs font-black text-hc-text w-8 text-right tabular-nums">{count}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export function ClientDiaryPage({ weekData, setPage, pageCtx, onQuickAction }: Props) {
  const [search, setSearch] = useState('');
  const [selectedClient, setSelectedClient] = useState<string | null>(null);
  const [typeFilter, setTypeFilter] = useState('');
  const [severityFilter, setSeverityFilter] = useState('');
  const [houseFilter, setHouseFilter] = useState('');

  // Context Router Receiver
  useEffect(() => {
    if (pageCtx) {
      if (pageCtx.client) setSelectedClient(pageCtx.client);
      if (pageCtx.house) setHouseFilter(pageCtx.house);
      if (pageCtx.severity) setSeverityFilter(pageCtx.severity);
    }
  }, [pageCtx]);

  // PDF import state
  const [pdfEntries, setPdfEntries] = useState<PdfDiaryEntry[]>([]);
  const [pdfLoading, setPdfLoading] = useState(false);
  const [pdfError, setPdfError] = useState('');
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePdfDrop = useCallback(async (file: File) => {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      setPdfError('Only PDF files are supported');
      return;
    }
    setPdfError('');
    setPdfLoading(true);
    try {
      const entries = await parseDiaryPdf(file);
      setPdfEntries(entries);
      if (entries.length > 0) setSelectedClient(entries[0].client);
    } catch (e) {
      setPdfError(`Could not parse PDF: ${e instanceof Error ? e.message : 'Unknown error'}`);
    } finally {
      setPdfLoading(false);
    }
  }, []);

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) void handlePdfDrop(file);
  }, [handlePdfDrop]);

  const storedClients = useMemo(() => loadClients().map(c => c.name.toLowerCase()), []);

  const clientDiary = weekData?.clientDiary || {};

  // Merge PDF entries into clientDiary view
  const mergedDiary = useMemo(() => {
    const d: Record<string, CareEntry[]> = { ...clientDiary };
    for (const pe of pdfEntries) {
      const key = pe.client;
      if (!d[key]) d[key] = [];
      // Avoid duplicates
      const exists = d[key].some(e => e.entry === pe.entry && e.date === pe.date);
      if (!exists) {
        d[key].push({
          id: `pdf-${pe.date}-${pe.carer}-${pe.entry.slice(0, 20)}`,
          client: pe.client,
          carer: pe.carer,
          date: pe.date,
          type: pe.type,
          category: 'daily',
          entry: pe.entry,
          house: '',
          severity: 'none',
          flags: [],
        } as unknown as CareEntry);
      }
    }
    return d;
  }, [clientDiary, pdfEntries]);

  const diaryStats = useMemo(() => {
    const stats: Record<string, { red: number; amber: number; houses: Set<string> }> = {};
    for (const [client, entries] of Object.entries(mergedDiary)) {
      let red = 0;
      let amber = 0;
      const houses = new Set<string>();
      for (const e of entries) {
        if (e.severity === 'red') red++;
        if (e.severity === 'amber') amber++;
        if (e.house) houses.add(e.house.toLowerCase());
      }
      stats[client] = { red, amber, houses };
    }
    return stats;
  }, [mergedDiary]);

  const allClients = useMemo(() =>
    Object.keys(mergedDiary)
      .filter(name => {
        if (!name || ['Maintenance', 'Station', 'On Call'].includes(name)) return false;
        if (houseFilter) {
          const stat = diaryStats[name];
          if (!stat || !stat.houses.has(houseFilter.toLowerCase())) return false;
        }
        return true;
      })
      .sort((a, b) => {
        const ra = diaryStats[a]?.red || 0;
        const rb = diaryStats[b]?.red || 0;
        if (rb !== ra) return rb - ra;
        const aa = diaryStats[a]?.amber || 0;
        const ab = diaryStats[b]?.amber || 0;
        if (ab !== aa) return ab - aa;
        return a.localeCompare(b);
      }),
    [mergedDiary, diaryStats, houseFilter]
  );

  const filteredClients = useMemo(() =>
    search.trim()
      ? allClients.filter(n => n.toLowerCase().includes(search.toLowerCase()))
      : allClients,
    [allClients, search]
  );

  const allTypes = useMemo(() => {
    const s = new Set<string>();
    Object.values(mergedDiary).flat().forEach(e => s.add(e.type));
    return [...s].sort();
  }, [mergedDiary]);

  const selectedEntries = useMemo(() => {
    if (!selectedClient) return [];
    let entries = mergedDiary[selectedClient] || [];
    if (houseFilter) entries = entries.filter(e => e.house?.toLowerCase() === houseFilter.toLowerCase());
    if (typeFilter) entries = entries.filter(e => e.type === typeFilter);
    if (severityFilter) {
      if (severityFilter === 'none') entries = entries.filter(e => e.severity === 'none');
      else entries = entries.filter(e => e.severity === severityFilter);
    }
    return [...entries].sort((a, b) => b.date.localeCompare(a.date));
  }, [selectedClient, mergedDiary, houseFilter, typeFilter, severityFilter]);

  // PDF drop zone — shown when no weekData AND no PDF entries yet
  const showDropZone = !weekData && pdfEntries.length === 0;

  if (showDropZone) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] text-center p-8 animate-in fade-in zoom-in duration-500"
        onDragOver={e => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={onDrop}
      >
        <input ref={fileInputRef} type="file" accept=".pdf" className="hidden"
          onChange={e => { const f = e.target.files?.[0]; if (f) void handlePdfDrop(f); }} />
        <div
          onClick={() => fileInputRef.current?.click()}
          className="cursor-pointer rounded-[2rem] p-10 mb-6 transition-all duration-300 flex flex-col items-center gap-4 hc-clay-raised"
          style={{
            border: isDragging ? '2px dashed rgba(20,184,166,0.6)' : '2px dashed rgba(255,255,255,0.1)',
            boxShadow: isDragging ? '0 0 40px rgba(20,184,166,0.15)' : '0 8px 40px rgba(0,0,0,0.5)',
          }}
        >
          <svg className={`w-14 h-14 transition-colors ${isDragging ? 'text-hc-teal' : 'text-hc-muted'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
          <div className="text-[11px] font-black tracking-[0.3em] text-hc-teal uppercase">
            {pdfLoading ? 'Reading PDF…' : isDragging ? 'Drop it' : 'Client Diary'}
          </div>
          <div className="text-hc-text font-black text-xl tracking-tight">
            {pdfLoading ? 'Parsing entries…' : 'Drop a diary PDF here'}
          </div>
          <div className="text-hc-muted text-xs max-w-xs leading-relaxed">
            Drop a CarePlanner diary export (PDF) directly here. No redirects.
          </div>
          {!pdfLoading && (
            <span className="text-[11px] font-bold text-hc-teal-light uppercase tracking-widest">or click to browse</span>
          )}
        </div>
        {pdfError && <div className="text-flag-red text-xs font-bold mt-2">{pdfError}</div>}
        <div className="h-px w-20 bg-white/5 my-5" />
        <button onClick={() => setPage('upload')} className="text-[11px] text-hc-muted hover:text-hc-text uppercase tracking-widest transition-colors">
          Or sync from global import
        </button>
      </div>
    );
  }

  return (
    <div className="flex h-screen overflow-hidden animate-in fade-in duration-700"
      onDragOver={e => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={onDrop}
    >
      {/* Full-screen drop overlay */}
      {isDragging && (
        <div className="fixed inset-0 z-50 flex items-center justify-center pointer-events-none"
          style={{background:'rgba(10,12,18,0.85)',backdropFilter:'blur(8px)'}}>
          <div className="rounded-[2rem] p-12 flex flex-col items-center gap-4"
            style={{border:'2px dashed rgba(20,184,166,0.6)',boxShadow:'0 0 60px rgba(20,184,166,0.2)'}}>
            <svg className="w-16 h-16 text-hc-teal" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <div className="text-hc-text font-black text-xl">Drop diary PDF</div>
          </div>
        </div>
      )}
      <input ref={fileInputRef} type="file" accept=".pdf" className="hidden"
        onChange={e => { const f = e.target.files?.[0]; if (f) void handlePdfDrop(f); }} />

      {/* Client list sidebar */}
      <div className="w-72 flex-shrink-0 border-r border-white/5 flex flex-col hc-clay-raised backdrop-blur-3xl">
        <div className="p-4 border-b border-white/5 hc-clay-inset">
          {/* Import button */}
          <button onClick={() => fileInputRef.current?.click()}
            className="w-full mb-3 py-2.5 rounded-xl text-[11px] font-black tracking-widest uppercase text-hc-teal-light cursor-pointer transition-all duration-200 hover:opacity-90"
            style={{background:'rgba(20,184,166,0.08)',border:'1px solid rgba(20,184,166,0.25)'}}>
            {pdfLoading ? 'Reading…' : '+ Import diary PDF'}
          </button>
          {pdfError && <div className="text-flag-red text-[11px] font-bold mb-2">{pdfError}</div>}
          <p className="section-header text-hc-muted text-[11px] mb-3 px-1">
            {allClients.length} clients{weekData ? ` · ${weekData.dateFrom}–${weekData.dateTo}` : ' · PDF import'}
          </p>
          <div className="relative group">
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search entries…"
              className="w-full bg-hc-dark/60 border border-white/5 rounded-xl px-4 py-2.5 text-xs text-hc-text focus:outline-none focus:border-hc-teal/50 focus:bg-hc-dark transition-all placeholder:text-hc-muted shadow-inner"
            />
            <div className="absolute right-3 top-1/2 -translate-y-1/2 text-hc-muted group-focus-within:text-hc-teal-light transition-colors">
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto scrollbar-thin">
          {filteredClients.map(name => {
            const entries = mergedDiary[name] || [];
            const red = diaryStats[name]?.red || 0;
            const amber = diaryStats[name]?.amber || 0;
            const hasDocs = storedClients.some(n => n.includes(name.toLowerCase().split(' ')[0]));
            const isSelected = selectedClient === name;
            return (
              <button key={name} onClick={() => { setSelectedClient(name); setTypeFilter(''); setSeverityFilter(''); }}
                className={`w-full text-left px-4 py-4 border-b border-white/5 transition-all duration-500 group active:scale-95
                  ${isSelected ? 'bg-hc-teal/10 accent-bar z-10' : 'hover:bg-white/5'}`}>
                <div className="flex items-start justify-between gap-3 mb-2 relative z-10 transition-transform duration-500 group-hover:translate-x-1">
                  <span className={`text-[14px] font-black tracking-tight leading-tight transition-colors group-hover:text-hc-text
                    ${isSelected ? 'text-hc-teal-light' : 'text-hc-text'}`}>
                    {name}
                  </span>
                  <div className="flex gap-1.5 flex-shrink-0">
                    {red > 0 && <span className="pill pill-red text-[11px] px-1.5 py-0 shadow-lg animate-pulse-soft">{red}</span>}
                    {amber > 0 && <span className="pill pill-amber text-[11px] px-1.5 py-0 shadow-lg">{amber}</span>}
                  </div>
                </div>
                <div className="flex items-center gap-3 relative z-10 transition-transform duration-500 group-hover:translate-x-1">
                  <span className="text-[11px] font-black text-hc-muted group-hover:text-hc-muted/80 transition-colors uppercase tracking-[0.15em] tabular-nums">
                    {entries.length} TRANSMISSIONS
                  </span>
                  {hasDocs && (
                    <span className="flex items-center gap-1.5 text-[11px] font-black text-hc-teal-light/70 uppercase tracking-widest animate-pulse-soft">
                      <div className="w-1 h-1 rounded-full bg-hc-teal shadow-[0_0_5px_#14b8a6]" />
                      VIEW FILE
                    </span>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Main content */}
      <div className="flex-1 overflow-y-auto scrollbar-thin mesh-bg relative">
        {!selectedClient ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8 animate-in fade-in duration-1000">
            <div className="w-24 h-24 rounded-3xl hc-clay-raised border border-white/10 flex items-center justify-center mb-8 glow-blue group">
              <span className="text-5xl grayscale group-hover:grayscale-0 transition-all duration-700 group-hover:scale-110 group-hover:rotate-3 text-hc-muted">👤</span>
            </div>
            <p className="text-hc-text font-black tracking-[0.3em] uppercase text-xs">Select a house to view notes</p>
            <div className="h-px w-12 bg-white/10 my-4" />
            <p className="text-[11px] text-hc-text font-black uppercase tracking-[0.4em]">{allClients.length} people found</p>

          </div>
        ) : (
          <div className="p-4 md:p-6 lg:p-8 max-w-[1200px] mx-auto animate-in slide-in-from-bottom-4 duration-700">
            {/* Header */}
            <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-xl md:text-2xl font-black text-hc-text mb-1 tracking-tighter uppercase text-shimmer">{selectedClient}</h2>
                <div className="flex items-center gap-3">
                  <span className="pill pill-teal text-[11px] uppercase tracking-[0.2em] font-black shadow-xl">Care Entries</span>
                  {weekData && (
                    <span className="text-hc-muted text-[11px] font-black uppercase tracking-[0.2em] ml-2 tabular-nums">
                      DATE RANGE: {weekData.dateFrom} – {weekData.dateTo}
                    </span>
                  )}
                </div>
              </div>
              <div className="flex gap-4">
                {storedClients.some(n => n.includes(selectedClient.toLowerCase().split(' ')[0])) && (
                  <button onClick={() => setPage('client-docs')}
                    className="px-8 py-3.5 hc-clay-raised border border-hc-teal/30 text-[11px] font-black uppercase tracking-[0.2em] text-hc-teal-light rounded-2xl hover:bg-hc-teal/10 hover:shadow-hc-teal/20 transition-all shadow-xl active:scale-95 group/btn">
                    <svg className="w-4 h-4 inline-block mr-2 group-hover/btn:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                    View Risk Assessment
                  </button>
                )}
              </div>
            </div>

            {/* Stats */}
            <ClientStats entries={mergedDiary[selectedClient] || []} />

            {/* Filters */}
            <div className="flex flex-wrap items-center gap-3 mb-6 hc-clay-raised border border-white/5 p-3 md:p-4 rounded-xl lg:rounded-2xl shadow-xl backdrop-blur-xl">
              <div className="flex items-center gap-3">
                <span className="section-header text-hc-muted text-[11px] tracking-[0.3em]">Filter:</span>
                <select value={typeFilter} onChange={e => setTypeFilter(e.target.value)}
                  className="bg-hc-dark/80 border border-white/10 rounded-xl px-5 py-2.5 text-[11px] font-black uppercase tracking-wider text-hc-text focus:outline-none focus:border-hc-teal/50 shadow-inner min-w-[180px]">
                  <option value="">All Types</option>
                  {allTypes.map(t => (
                    <option key={t} value={t}>{t}</option>
                  ))}
                </select>
                <select value={severityFilter} onChange={e => setSeverityFilter(e.target.value)}
                  className="bg-hc-dark/80 border border-white/10 rounded-xl px-5 py-2.5 text-[11px] font-black uppercase tracking-wider text-hc-text focus:outline-none focus:border-hc-teal/50 shadow-inner min-w-[180px]">
                  <option value="">All Severities</option>
                  <option value="red">🔴 Red Flags Only</option>
                  <option value="amber">🟡 Amber Alerts</option>
                  <option value="none">No Flags</option>
                </select>
                {houseFilter && (
                  <div className="flex items-center gap-2 bg-hc-teal/20 border border-hc-teal/50 rounded-xl px-4 py-2 text-[11px] font-black uppercase text-hc-teal">
                    <span>🏠 {houseFilter}</span>
                    <button onClick={() => setHouseFilter('')} className="ml-2 hover:text-white">&times;</button>
                  </div>
                )}
              </div>
              
              <div className="h-6 w-px bg-white/10 mx-2 hidden md:block" />
              
              {(typeFilter || severityFilter || houseFilter) && (
                <button onClick={() => { setTypeFilter(''); setSeverityFilter(''); setHouseFilter(''); }}
                  className="text-[11px] font-black uppercase tracking-[0.3em] text-hc-muted hover:text-hc-text transition-colors underline decoration-white/10 underline-offset-8">
                  Clear Filter
                </button>
              )}
              
              <span className="text-[11px] font-black text-hc-teal-light tracking-[0.2em] ml-auto tabular-nums">
                {selectedEntries.length} INTELLIGENCE POINTS CAPTURED
              </span>
            </div>

            {/* Entries */}
            <div className="space-y-4">
              {selectedEntries.length === 0 ? (
                <div className="text-center py-24 hc-clay-raised border border-white/5 rounded-3xl animate-in zoom-in duration-700">
                  <div className="text-4xl mb-4 opacity-20 grayscale">🔍</div>
                  <div className="text-lg font-extrabold text-hc-text mb-2 uppercase tracking-tight">Zero Intercepts</div>
                  <div className="text-[11px] text-hc-muted uppercase tracking-[0.2em] font-bold">Adjust sensor parameters to restore stream visibility</div>
                </div>
              ) : selectedEntries.map((entry, idx) => (
                <div key={entry.id}
                  className={`hc-clay-raised border transition-all duration-500 rounded-[2rem] px-8 py-6 card-glow interactive-row group/entry animate-in slide-in-from-left-4
                    ${entry.severity === 'red' ? 'border-flag-red/30 bg-flag-red/[0.02] glow-red shadow-flag-red/5' : entry.severity === 'amber' ? 'border-flag-amber/25 bg-flag-amber/[0.01] glow-amber shadow-flag-amber/5' : 'border-white/5 hover:border-hc-teal/20'}`}
                  style={{ animationDelay: `${idx * 50}ms` }}>
                  <div className="flex items-start gap-6 relative z-10">
                    <div className="mt-2 flex-shrink-0">
                      {entry.severity === 'red' ? (
                        <div className="w-3 h-3 rounded-full bg-flag-red shadow-[0_0_12px_rgba(239,68,68,0.8)] animate-pulse" />
                      ) : entry.severity === 'amber' ? (
                        <div className="w-3 h-3 rounded-full bg-flag-amber shadow-[0_0_12px_rgba(245,158,11,0.8)]" />
                      ) : (
                        <div className="w-3 h-3 rounded-full bg-hc-border shadow-inner opacity-20 group-hover/entry:opacity-40 transition-opacity" />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-4 flex-wrap mb-4">
                        <span className="text-[11px] font-black px-4 py-1 rounded-full uppercase tracking-widest shadow-xl group-hover/entry:scale-105 transition-transform"
                          style={{ background: typeColor(entry.type) + '22', color: typeColor(entry.type), border: `1px solid ${typeColor(entry.type)}44` }}>
                          {entry.type}
                        </span>
                        <div className="flex items-center gap-3">
                          <span className="text-[11px] font-black text-hc-muted uppercase tracking-[0.2em] tabular-nums">{entry.date}</span>
                          {entry.carer && entry.carer !== 'Staff' && (
                            <>
                              <div className="w-1 h-1 rounded-full bg-white/10" />
                              <span className="text-[11px] font-black text-hc-teal-light uppercase tracking-widest group-hover/entry:text-hc-teal-light transition-colors">AGENT: {entry.carer}</span>
                            </>
                          )}
                        </div>
                      </div>
                      <p className="text-[15px] text-hc-text font-medium leading-relaxed whitespace-pre-wrap italic group-hover/entry:text-hc-text transition-colors px-1">"{entry.entry}"</p>
                      {entry.flags.length > 0 && (
                        <div className="flex flex-wrap gap-2.5 mt-6">
                          {entry.flags.map((f, i) => (
                            <span key={i} className={`pill text-[11px] font-black uppercase tracking-[0.15em] shadow-2xl py-1 px-3
                              ${entry.severity === 'red' ? 'pill-red shadow-flag-red/10' : 'pill-amber shadow-flag-amber/10'}`}>
                              {f}
                            </span>
                          ))}
                        </div>
                      )}
                    </div>

                    <div className="flex flex-col gap-2 opacity-0 group-hover/entry:opacity-100 transition-all duration-300">
                      <button 
                        onClick={() => onQuickAction({ type: 'action', content: entry.entry, client: selectedClient, house: entry.house })}
                        className="w-10 h-10 rounded-xl hc-clay-inset border border-hc-teal/20 flex items-center justify-center text-hc-teal hover:bg-hc-teal/20 transition-all shadow-lg shadow-hc-teal/10"
                        title="Convert to Action"
                      >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4" /></svg>
                      </button>
                      <button 
                        onClick={() => onQuickAction({ type: 'incident', content: entry.entry, client: selectedClient, house: entry.house })}
                        className="w-10 h-10 rounded-xl hc-clay-inset border border-flag-red/20 flex items-center justify-center text-flag-red hover:bg-flag-red/20 transition-all shadow-lg shadow-flag-red/10"
                        title="Log Incident"
                      >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4.5c-.77-.833-2.694-.833-3.464 0L3.34 16.5c-.77.833.192 2.5 1.732 2.5z" /></svg>
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useMemo, useRef, useState } from 'react';
import * as pdfjs from 'pdfjs-dist';
import { loadClients, saveClient, deleteClient, emptyClient, type ClientDocument, type FullClient } from '../lib/client-store';
import { purgeSystemDataAsync } from '../lib/governance-utils';
import { buildPBSHtml, buildRiskHtml, buildCarePlanHtml, buildEasyReadHtml, riskInfo } from '../lib/doc-renderer';
import type { ExportLayout } from '../lib/doc-renderer';
import { analyzeIntel, analyzeIntelFallback } from '../lib/intelligence';
import { mergeClientIdentity } from '../lib/client-identity-merge';
import { mergeCarePlanData, mergePBSData, mergeRiskData } from '../lib/intel-merge';
import { buildClusterNote, buildClusterTitle, clusterRiskItems } from '../lib/risk-assistant';
import { PBSBuilder } from './PBSBuilder';
import { RiskBuilder } from './RiskBuilder';
import { CarePlanBuilder } from './CarePlanBuilder';
import { Trash2, AlertTriangle, Sparkles, Loader2, FileText, CheckCircle, Upload, ExternalLink, X } from 'lucide-react';
import { uid } from '../lib/storage';

// Localized Sovereign PDF Worker (Vite-optimised)
import pdfWorker from 'pdfjs-dist/build/pdf.worker.mjs?url';
pdfjs.GlobalWorkerOptions.workerSrc = pdfWorker;

type SubView = 'list' | 'pbs' | 'risk' | 'careplan' | 'import';

export function ClientDocsPage() {
  const [subView, setSubView] = useState<SubView>('list');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [clients, setClients] = useState<FullClient[]>(() => loadClients());
  const [showNewModal, setShowNewModal] = useState(false);
  const [newName, setNewName] = useState('');
  const [filterText, setFilterText] = useState('');
  const [importText, setImportText] = useState('');
  const [importTarget, setImportTarget] = useState<string | null>(null);
  const [importResult, setImportResult] = useState<string[]>([]);
  const [importPreview, setImportPreview] = useState<{ name: string; dob: string; nhs: string; domainsDetected: number } | null>(null);
  const [isExtracting, setIsExtracting] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isUploading, setIsUploading] = useState<string | null>(null);
  const [exportLayout, setExportLayout] = useState<ExportLayout>('portrait');
  const [showAiPanel, setShowAiPanel] = useState(false);
  const [copiedToken, setCopiedToken] = useState('');
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const docUploadRef = useRef<HTMLInputElement>(null);
  const [sessionIntel, setSessionIntel] = useState<any>(null);

  const refresh = () => setClients(loadClients());

  const openPBS = (id: string) => { setSelectedId(id); setSubView('pbs'); };
  const openRisk = (id: string) => { setSelectedId(id); setSubView('risk'); };
  const openCarePlan = (id: string) => { setSelectedId(id); setSubView('careplan'); };
  const goBack = () => { refresh(); setSubView('list'); setSelectedId(null); };

  const handleDelete = (id: string, name: string) => {
    if (!confirm(`Delete all documents for ${name}? This cannot be undone.`)) return;
    deleteClient(id);
    refresh();
  };

  const handleCreate = () => {
    if (!newName.trim()) return;
    const client = emptyClient();
    client.name = newName.trim();
    client.preferredName = newName.trim().split(' ')[0];
    saveClient(client);
    setNewName('');
    setShowNewModal(false);
    refresh();
    openPBS(client.id);
  };

  const handleDocUpload = async (clientId: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(clientId);
    try {
      const url = `/api/staff/upload-document?filename=${encodeURIComponent(file.name)}`;
      const res = await fetch(url, {
        method: 'POST',
        body: file,
        credentials: 'include',
      });

      if (!res.ok) throw new Error('Upload failed');
      const blob = await res.json();

      const all = loadClients();
      const client = all.find(c => c.id === clientId);
      if (client) {
        const newDoc: ClientDocument = {
          id: uid(),
          name: file.name,
          url: blob.url,
          type: file.type,
          uploadedAt: new Date().toISOString(),
        };
        client.documents = [...(client.documents || []), newDoc];
        saveClient(client);
        refresh();
      }
    } catch (err) {
      console.error('Upload error:', err);
      alert('Failed to upload document. Ensure you are signed in.');
    } finally {
      setIsUploading(null);
      if (docUploadRef.current) docUploadRef.current.value = '';
    }
  };

  const deleteDoc = (clientId: string, docId: string) => {
    if (!confirm('Remove this document reference? The file will remain in blob storage but be unlinked from this profile.')) return;
    const all = loadClients();
    const client = all.find(c => c.id === clientId);
    if (client) {
      client.documents = (client.documents || []).filter(d => d.id !== docId);
      saveClient(client);
      refresh();
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsExtracting(true);
    setImportResult(['Reading PDF Content...']);

    try {
      const arrayBuffer = await file.arrayBuffer();
      const pdf = await pdfjs.getDocument({ data: arrayBuffer }).promise;
      let fullText = '';

      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const content = await page.getTextContent();
        let lastY: number | null = null;
        let pageText = '';
        for (const item of content.items as any[]) {
          if (!item.str) continue;
          const y = item.transform ? item.transform[5] : null;
          if (lastY !== null && y !== null && Math.abs(y - lastY) > 2) {
            pageText += '\n';
          } else if (pageText && !pageText.endsWith(' ') && !pageText.endsWith('\n')) {
            pageText += ' ';
          }
          pageText += item.str;
          lastY = y;
        }
        fullText += pageText + '\n';
      }

      setImportText(fullText);
      setImportResult(['Document text extracted. Use "Basic Pattern Sync" for the deterministic pass, or "Use AI" for the optional assistant.']);
      setShowAiPanel(false);
    } catch (err) {
      console.error('PDF extract error:', err);
      setImportResult(['Failed to read PDF. Try copy-pasting the text manually instead.']);
    } finally {
      setIsExtracting(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handlePreview = async (useAI = false) => {
    if (!importText.trim()) return;

    if (useAI) {
      setIsAnalyzing(true);
      setImportResult(['Initiating Clinical AI Intelligence Pipeline...']);
      try {
        const result = await analyzeIntel(importText);
        setImportResult([...result.gaps, 'Clinical analysis complete. Data mapped to CQC domains.']);
        const domainsDetected = result.carePlan.domains.filter(d => d.enabled).length;
        setImportPreview({
          name: result.client.name || 'Not detected',
          dob: result.client.dob || 'Not detected',
          nhs: result.client.nhs || 'Not detected',
          domainsDetected,
        });
        setSessionIntel(result);
      } catch (err: any) {
        setImportResult(['AI Intelligence failed: ' + err.message, 'Switching to pattern-match fallback...']);
        runLegacyPreview();
      } finally {
        setIsAnalyzing(false);
      }
    } else {
      runLegacyPreview();
    }
  };

  const runLegacyPreview = () => {
    const result = analyzeIntelFallback(importText);
    setImportResult(result.gaps);
    const domainsDetected = result.carePlan.domains.filter(d => d.enabled).length;
    setImportPreview({
      name: result.client.name || 'Not detected',
      dob: result.client.dob || 'Not detected',
      nhs: result.client.nhs || 'Not detected',
      domainsDetected,
    });
    setSessionIntel(result);
  };

  const riskItems = sessionIntel?.risk?.risks || [];
  const riskClusters = useMemo(() => clusterRiskItems(riskItems), [riskItems]);

  const copyText = async (token: string, text: string) => {
    await navigator.clipboard.writeText(text);
    setCopiedToken(token);
    window.setTimeout(() => setCopiedToken((current) => (current === token ? '' : current)), 1600);
  };

  const openAiPanel = async () => {
    if (!importText.trim()) return;
    await handlePreview(true);
    setShowAiPanel(true);
  };

  const handleImport = () => {
    const result = sessionIntel;
    if (!result) return;
    const today = new Date().toLocaleDateString('en-GB');

    if (importTarget) {
      const all = loadClients();
      const existing = all.find(c => c.id === importTarget);
      if (existing) {
        const identity = mergeClientIdentity(existing, result.client);
        
        const mergedCarePlan = mergeCarePlanData(existing.carePlan, result.carePlan, today);
        const mergedRisk = mergeRiskData(existing.risk, result.risk, today);
        const mergedPbs = mergePBSData(existing.pbs, result.pbs || null);
        
        const updated: FullClient = {
          ...identity,
          carePlan: mergedCarePlan,
          risk: mergedRisk,
          pbs: mergedPbs,
        };
        saveClient(updated);
        refresh();
        setImportText('');
        setImportPreview(null);
        setSubView('list');
      }
    } else {
      const client = emptyClient();
      const mergedIdentity = mergeClientIdentity(client, result.client);
      Object.assign(client, mergedIdentity);
      client.carePlan = result.carePlan;
      client.risk = result.risk;
      client.pbs = result.pbs || client.pbs;
      saveClient(client);
      refresh();
      setImportText('');
      setImportPreview(null);
      setSubView('list');
    }
    setSessionIntel(null);
  };

  const printDoc = (client: FullClient, type: 'pbs' | 'risk' | 'careplan' | 'easyread') => {
    let html = '';
    if (type === 'pbs') html = buildPBSHtml(client, undefined, exportLayout);
    else if (type === 'risk') html = buildRiskHtml(client, undefined, exportLayout);
    else if (type === 'easyread') html = buildEasyReadHtml(client, exportLayout);
    else html = buildCarePlanHtml(client, undefined, exportLayout);
    const doc = iframeRef.current?.contentDocument;
    if (!doc) return;
    doc.open(); doc.write(html); doc.close();
    setTimeout(() => iframeRef.current?.contentWindow?.print(), 400);
  };

  if (subView === 'pbs' && selectedId) return <PBSBuilder clientId={selectedId} onBack={goBack} />;
  if (subView === 'risk' && selectedId) return <RiskBuilder clientId={selectedId} onBack={goBack} />;
  if (subView === 'careplan' && selectedId) return <CarePlanBuilder clientId={selectedId} onBack={goBack} />;

  if (subView === 'import') {
    return (
      <div className="p-6 lg:p-10 xl:px-16 2xl:px-24 w-full animate-in fade-in duration-700">
        <button onClick={() => { setSubView('list'); setImportResult([]); setImportText(''); setImportPreview(null); }}
          className="group flex items-center gap-2 text-hc-muted hover:text-hc-text text-xs font-black uppercase tracking-[0.08em] mb-8 transition-all">
          <span className="w-6 h-6 rounded-lg hc-clay-inset flex items-center justify-center">←</span>
          Back
        </button>

        <h1 className="text-3xl font-extrabold text-hc-text mb-2 tracking-tight flex items-center gap-3">
          Intelligence Sync
          <span className="pill pill-teal text-[10px] font-black uppercase tracking-widest px-3 py-1">Operational Pipeline</span>
        </h1>
        <p className="text-hc-muted text-sm mb-10 max-w-2xl font-medium leading-relaxed">
          Upload person-centred clinical documents or raw unstructured text. The AI Brain will map all 21 care domains and 15 risk areas automatically.
        </p>

        <div className="flex flex-col md:flex-row gap-4 mb-8">
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={isExtracting || isAnalyzing}
            className="flex-1 flex items-center justify-center gap-3 hc-clay-raised text-hc-text text-[11px] font-black uppercase tracking-[0.2em] py-4 rounded-2xl transition-all hover:brightness-105"
          >
            <FileText className="w-5 h-5 text-hc-teal" />
            {isExtracting ? 'Extracting Text...' : 'Upload PDF Document'}
          </button>
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileSelect}
            accept=".pdf"
            className="hidden"
          />
        </div>

        <div className="bg-hc-teal/5 border border-hc-teal/20 rounded-2xl px-6 py-4 mb-8 flex items-center gap-4 group">
          <div className="w-10 h-10 rounded-xl bg-hc-teal/10 border border-hc-teal/20 flex items-center justify-center shrink-0">
            <Sparkles className="w-5 h-5 text-hc-teal animate-pulse" />
          </div>
          <div>
            <p className="text-xs text-hc-teal font-black uppercase tracking-wide mb-0.5">Clinical Protocol</p>
            <p className="text-sm text-hc-muted font-medium italic leading-relaxed">
              For Social Worker reports or Hospital Discharge notes, use the "Clinical AI Analysis" button below for maximum precision.
            </p>
          </div>
        </div>

        {importTarget && (
          <div className="pill pill-teal text-[10px] font-black px-4 py-2 mb-6 inline-flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-hc-teal animate-pulse" />
            TARGET OVERWRITE: {clients.find(c => c.id === importTarget)?.name || 'Unknown'}
          </div>
        )}

        <div className={`hc-clay-inset rounded-2xl p-1 overflow-hidden ${importPreview ? 'mb-4' : 'mb-6'}`}>
          <textarea
            value={importText}
            onChange={e => setImportText(e.target.value)}
            rows={importPreview ? 8 : 12}
            placeholder="Paste raw unstructured clinical text here..."
            className={`w-full bg-transparent p-6 text-hc-text font-mono text-sm leading-relaxed resize-y placeholder:text-hc-muted/60 focus:outline-none scrollbar-thin ${importPreview ? 'max-h-[220px]' : 'min-h-[320px]'}`}
          />
        </div>

        {importResult.length > 0 && (
          <div className={`bg-hc-border/10 border border-hc-border/30 rounded-2xl px-6 py-4 space-y-1 ${importPreview ? 'mb-4' : 'mb-6'}`}>
            {importResult.map((w, i) => (
              <p key={i} className="text-xs font-bold text-hc-muted uppercase tracking-wide leading-relaxed flex items-center gap-2">
                {w.includes('AI Analysis Complete') || w.includes('Clinical analysis complete')
                  ? <CheckCircle className="w-3 h-3 text-flag-green" />
                  : <span className="w-1 h-1 rounded-full bg-hc-teal/40" />
                }
                {w}
              </p>
            ))}
          </div>
        )}

        {importPreview && (
          <div className={`grid gap-6 mb-8 ${showAiPanel ? 'lg:grid-cols-[1.45fr_0.95fr]' : 'grid-cols-1'}`}>
            <div className="hc-clay-raised border-2 border-hc-teal/30 rounded-[2rem] p-8 animate-in zoom-in-95 duration-500 glow-teal relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 rounded-full bg-hc-teal/5 blur-[80px] -translate-y-1/2 translate-x-1/2" />
              <div className="relative z-10">
                <p className="section-header text-[10px] mb-6 flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-hc-teal animate-pulse" />
                  Detected Profile Structure
                </p>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-8">
                  <div className="hc-clay-inset rounded-2xl p-4">
                    <div className="section-header text-xs mb-1">Clinical Designation</div>
                    <div className="text-sm font-black text-hc-text truncate">{importPreview.name}</div>
                  </div>
                  <div className="hc-clay-inset rounded-2xl p-4">
                    <div className="section-header text-xs mb-1">Temporal ID</div>
                    <div className="text-sm font-black text-hc-text tabular-nums">{importPreview.dob}</div>
                  </div>
                  <div className="hc-clay-inset rounded-2xl p-4">
                    <div className="section-header text-xs mb-1">CQC Domains</div>
                    <div className="text-sm font-black text-hc-teal tabular-nums">{importPreview.domainsDetected} / 21</div>
                  </div>
                  <div className="hc-clay-inset rounded-2xl p-4">
                    <div className="section-header text-xs mb-1">Risk Logic</div>
                    <div className="text-sm font-black text-hc-teal">{riskClusters.length ? `${riskClusters.length} clusters` : 'ENABLED'}</div>
                  </div>
                </div>

                {riskClusters.length > 0 && (
                  <div className="mb-8">
                    <div className="flex items-center justify-between mb-4">
                      <div className="section-header text-[10px] flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-flag-amber animate-pulse" />
                        Risk Hotspots
                      </div>
                      <div className="text-[9px] font-black uppercase tracking-widest text-hc-muted">
                        {riskClusters.filter((cluster) => cluster.hotspot).length} clusters at 3+
                      </div>
                    </div>
                    <div className="grid gap-3 md:grid-cols-2">
                      {riskClusters.map((cluster) => {
                        const title = buildClusterTitle(cluster);
                        const note = buildClusterNote(cluster);
                        const token = `cluster:${cluster.key}`;
                        return (
                          <div
                            key={cluster.key}
                            className={`rounded-2xl p-4 border transition-all ${cluster.hotspot ? 'bg-flag-amber/8 border-flag-amber/30 shadow-[0_0_0_1px_rgba(250,204,21,0.05)]' : 'bg-hc-bone/50 border-hc-border/20'}`}
                          >
                            <div className="flex items-start justify-between gap-3">
                              <div className="min-w-0">
                                <div className="text-[10px] font-black uppercase tracking-[0.24em] text-hc-text truncate">
                                  {title}
                                </div>
                                <div className="text-[9px] font-black uppercase tracking-[0.2em] text-hc-muted mt-1">
                                  {cluster.hotspot ? 'Hotspot cluster' : 'Cluster building'}
                                </div>
                              </div>
                              <span className={`shrink-0 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${cluster.hotspot ? 'bg-flag-amber/15 text-flag-amber border border-flag-amber/25' : 'bg-hc-border/15 text-hc-muted border border-hc-border/20'}`}>
                                {cluster.count}
                              </span>
                            </div>
                            <div className="mt-3 text-[10px] text-hc-text/70 leading-relaxed max-h-24 overflow-hidden whitespace-pre-line">
                              {note}
                            </div>
                            <div className="mt-4 flex flex-wrap gap-2">
                              <button
                                onClick={() => copyText(`${token}:title`, title)}
                                className="px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest hc-clay-raised text-hc-muted hover:text-hc-teal transition-colors"
                              >
                                {copiedToken === `${token}:title` ? 'Copied title' : 'Copy title'}
                              </button>
                              <button
                                onClick={() => copyText(`${token}:note`, note)}
                                className="px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest hc-clay-raised text-hc-muted hover:text-hc-teal transition-colors"
                              >
                                {copiedToken === `${token}:note` ? 'Copied note' : 'Copy note'}
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}

                <div className="flex gap-4">
                  <button onClick={handleImport}
                    className="flex-1 btn-tactical text-[11px] py-4 rounded-xl">
                    Commit Intelligence to Profile
                  </button>
                  <button onClick={() => setImportPreview(null)}
                    className="px-8 btn-clay text-[11px] py-4 rounded-xl">
                    Discard
                  </button>
                </div>
              </div>
            </div>

            {showAiPanel && (
              <div className="hc-clay-raised border-2 border-hc-teal/20 rounded-[2rem] p-6 animate-in fade-in slide-in-from-right-4 duration-500 bg-hc-bone/90">
                <div className="flex items-center justify-between gap-4 mb-4">
                  <div>
                    <div className="text-[10px] font-black uppercase tracking-[0.28em] text-hc-teal">AI Sidecar</div>
                    <div className="text-[11px] text-hc-muted font-medium">Appears only when you click Use AI.</div>
                  </div>
                  <button
                    onClick={() => setShowAiPanel(false)}
                    className="w-9 h-9 rounded-xl hc-clay-inset text-hc-muted hover:text-hc-text transition-colors"
                    title="Close AI panel"
                  >
                    <X className="w-4 h-4 mx-auto" />
                  </button>
                </div>

                <div className="space-y-4">
                  <div className="rounded-2xl p-4 border border-hc-border/20 bg-white/30">
                    <div className="text-[9px] font-black uppercase tracking-[0.2em] text-hc-muted mb-2">What I can see</div>
                    <div className="text-[11px] text-hc-text/75 leading-relaxed">
                      {sessionIntel
                        ? `I can see ${riskClusters.length} risk cluster${riskClusters.length === 1 ? '' : 's'} and ${riskClusters.filter((cluster) => cluster.hotspot).length} hotspot${riskClusters.filter((cluster) => cluster.hotspot).length === 1 ? '' : 's'} in the extracted document.`
                        : 'Click "Use AI" to run the optional analysis pass and compare it with the deterministic cluster view.'}
                    </div>
                  </div>

                  <div className="rounded-2xl p-4 border border-hc-border/20 bg-white/30">
                    <div className="text-[9px] font-black uppercase tracking-[0.2em] text-hc-muted mb-2">Recommended move</div>
                    <div className="text-[11px] text-hc-text/75 leading-relaxed">
                      Build out the hotspot categories first, then paste each generated note into Nourish under the matching category heading. That keeps the pack readable when printed and gives you a fast manual fallback if AI is not needed.
                    </div>
                  </div>

                  {sessionIntel?.gaps?.length > 0 && (
                    <div className="rounded-2xl p-4 border border-hc-border/20 bg-white/30">
                      <div className="text-[9px] font-black uppercase tracking-[0.2em] text-hc-muted mb-2">AI gap cues</div>
                      <div className="space-y-1">
                        {sessionIntel.gaps.slice(0, 4).map((gap: string, idx: number) => (
                          <div key={idx} className="text-[10px] text-hc-text/70 leading-relaxed">
                            • {gap}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  <button
                    onClick={openAiPanel}
                    disabled={isAnalyzing || !importText.trim()}
                    className="w-full btn-tactical text-[10px] py-3 rounded-xl flex items-center justify-center gap-3 disabled:opacity-40"
                  >
                    {isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                    {isAnalyzing ? 'Thinking...' : 'Re-run AI'}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {!importPreview && (
          <div className="flex flex-col md:flex-row items-center gap-6">
            <button
              onClick={() => handlePreview(false)}
              disabled={!importText.trim() || isAnalyzing}
              className="w-full md:w-auto btn-clay disabled:opacity-20 text-[11px] px-8 py-4 rounded-xl"
            >
              Basic Pattern Sync
            </button>
            <button
              onClick={openAiPanel}
              disabled={!importText.trim() || isAnalyzing}
              className="w-full md:w-auto btn-clay disabled:opacity-20 text-[11px] px-8 py-4 rounded-xl border border-hc-teal/20 text-hc-teal"
            >
              Use AI
            </button>
            {!importTarget && (
              <div className="flex items-center gap-4 hc-clay-inset px-5 py-3 rounded-2xl ml-auto">
                <span className="text-[10px] font-black text-hc-muted uppercase tracking-widest">Target Map:</span>
                <select
                  value={importTarget || ''}
                  onChange={e => setImportTarget(e.target.value || null)}
                  className="bg-hc-bone border border-hc-border/30 rounded-xl px-4 py-2 text-[11px] font-black text-hc-text focus:outline-none focus:border-hc-teal/50 min-w-[180px]">
                  <option value="">New Clinical Profile</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  const filtered = filterText
    ? clients.filter(c => c.name.toLowerCase().includes(filterText.toLowerCase()))
    : clients;

  const pbsCount = clients.filter(c => c.pbs && c.pbs.aboutText).length;
  const riskCount = clients.filter(c => c.risk && c.risk.risks.some(r => r.title)).length;
  const cpCount = clients.filter(c => c.carePlan && c.carePlan.domains.some(d => d.enabled)).length;

  return (
    <div className="p-6 lg:p-10 xl:px-16 2xl:px-24 w-full animate-in fade-in duration-700">
      {/* Page header */}
      <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4 mb-6">
        <div>
          <h1 className="text-xl md:text-2xl font-extrabold text-hc-text mb-1 tracking-tight">People & Support Plans</h1>
          <div className="flex flex-wrap items-center gap-3">
            <span className="pill pill-blue text-xs font-black uppercase tracking-wide">{clients.length} People</span>
            <span className="pill pill-teal text-xs font-black uppercase tracking-wide">{pbsCount} PBS Profiles</span>
            <span className="pill pill-amber text-xs font-black uppercase tracking-wide">{riskCount} Risk Matrices</span>
            <span className="pill pill-purple text-xs font-black uppercase tracking-wide">{cpCount} Support Plans</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <select
            value={exportLayout}
            onChange={e => setExportLayout(e.target.value as ExportLayout)}
            className="bg-hc-bone border border-hc-border/30 rounded-xl px-3 py-2 text-[10px] font-black uppercase tracking-[0.08em] text-hc-text focus:outline-none"
            title="Default export orientation"
          >
            <option value="portrait">Portrait</option>
            <option value="landscape">Landscape</option>
          </select>
          <button onClick={() => { setImportTarget(null); setSubView('import'); }}
            className="flex items-center gap-2.5 btn-clay text-[10px] px-5 py-3 rounded-xl group">
            <Sparkles className="w-4 h-4 text-hc-teal group-hover:scale-110 transition-transform" />
            Intelligence Sync
          </button>
          <button onClick={() => setShowNewModal(true)}
            className="flex items-center gap-2.5 btn-tactical text-[10px] px-6 py-3 rounded-xl">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={3}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4" />
            </svg>
            Add Person
          </button>
        </div>
      </div>

      {/* Hidden inputs for document management */}
      <input
        type="file"
        ref={docUploadRef}
        onChange={(e) => selectedId && handleDocUpload(selectedId, e)}
        accept=".pdf,.doc,.docx"
        className="hidden"
      />

      {/* Search filter */}
      {clients.length > 2 && (
        <div className="mb-8 relative group max-w-md">
          <input
            type="text"
            value={filterText}
            onChange={e => setFilterText(e.target.value)}
            placeholder="Search people…"
            className="hc-clay-inset w-full rounded-xl px-10 py-3 text-sm text-hc-text focus:outline-none transition-all placeholder:text-hc-muted/50"
          />
          <div className="absolute left-3.5 top-1/2 -translate-y-1/2 opacity-40 group-focus-within:opacity-80 transition-opacity">
            <svg className="w-4 h-4 text-hc-teal" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>
      )}

      {/* Client cards */}
      {filtered.length === 0 ? (
        <div className="text-center py-24 hc-clay-raised rounded-3xl animate-in zoom-in duration-700">
          <div className="text-5xl mb-6 opacity-20">👥</div>
          <div className="text-lg font-extrabold text-hc-text mb-2 uppercase tracking-tight">{filterText ? 'No matches found' : 'No People Added Yet'}</div>
          <div className="text-[10px] text-hc-muted uppercase tracking-[0.2em] font-bold">{filterText ? 'Try a different search' : 'Click "Add Person" to get started'}</div>
        </div>
