            const cpDomains = client.carePlan?.domains.filter(d => d.enabled) || [];
            const cpFilled = cpDomains.filter(d => d.identifiedNeed).length;

            const topRisk = client.risk?.risks
              .filter(r => r.title)
              .reduce((max, r) => {
