                </button>
                <button onClick={handleCreate} disabled={!newName.trim()}
                  className="flex-[2] btn-tactical disabled:opacity-20 disabled:grayscale text-[11px] py-4 rounded-2xl">
                  Create
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <iframe ref={iframeRef} style={{ display: 'none' }} title="doc-print" />
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { 
  MessageSquare, Clipboard, Search, Terminal, Zap, Trash2, CheckCircle, 
  Clock, Phone, AlertCircle, Calendar, XCircle, ShieldAlert,
  Activity, Layers, HelpCircle
} from 'lucide-react';
import type { InterceptedIntel, InterceptVector } from '../lib/types';

export function CommunicationsPage() {
  const [rawText, setRawText] = useState('');
  const [intel, setIntel] = useState<InterceptedIntel[]>(() => {
    try {
      const saved = localStorage.getItem('hc-intercept-cache');
      return saved ? JSON.parse(saved) : [];
    } catch { return []; }
  });
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<InterceptVector | 'all'>('all');
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [showGuide, setShowGuide] = useState(false);
  const [parseError, setParseError] = useState(false);

  // SESSION PERSISTENCE ANCHOR
  useEffect(() => {
    localStorage.setItem('hc-intercept-cache', JSON.stringify(intel));
  }, [intel]);


  const stats = useMemo(() => {
    return {
      total: intel.length,
      alerts: intel.filter(m => m.type === 'alert').length,
      leave: intel.filter(m => m.type === 'leave').length,
      gaps: intel.filter(m => m.type === 'gap').length,
      messages: intel.filter(m => m.type === 'message').length,
    };
  }, [intel]);

  const filteredIntel = useMemo(() => {
    let out = intel;
    if (filterType !== 'all') out = out.filter(m => m.type === filterType);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      out = out.filter(m => 
        m.sender.toLowerCase().includes(q) || 
        m.content.toLowerCase().includes(q) ||
        (m.phone && m.phone.includes(q))
      );
    }
    return out;
  }, [intel, filterType, searchQuery]);

  function handleIntercept() {
    if (!rawText.trim()) return;

    const newIntel: InterceptedIntel[] = [];
    const text = rawText;

    // --- VECTOR 1: NOTICES & CLINICAL ALERTS ---
    const noticesMatch = text.match(/Notices([\s\S]*?)(?:View all notices|Birthdays)/);
    if (noticesMatch) {
      const section = noticesMatch[1];
      const items = section.split(/\d{2}\/\d{2}\/\d{4} \d{2}:\d{2}(?:new)?/).filter(i => i.trim());
      items.forEach(item => {
        const lines = item.trim().split('\n').map(l => l.trim()).filter(l => l);
        const title = lines[0] || 'Unknown Notice';
        const body = lines.slice(1).join('\n');
        
        let draft = "Acknowledged. Clinical Lead notified for audit.";
        if (title.toUpperCase().includes('MEDICATION ALERT')) {
          const clientMatch = body.match(/recorded for (.*?) by/);
          const client = clientMatch ? clientMatch[1] : 'Unknown';
          draft = `CRITICAL: Medication discrepancy detected for ${client}. Incident report workflow initialised. Please verify remaining stock immediately.`;
        }

        newIntel.push({
          id: `alert-${Math.random().toString(36).substr(2, 9)}`,
          type: 'alert',
          timestamp: 'RECENT',
          sender: 'SYSTEM_ALERT',
          content: `${title}\n${body}`,
          category: title.toUpperCase().includes('ALERT') ? 'critical' : 'general',
          draft,
          meta: { priority: title.toUpperCase().includes('ALERT') ? 'critical' : 'medium' }
        });
      });
    }

    // --- VECTOR 2: LEAVE REQUESTS ---
    const leaveMatch = text.match(/Outstanding Time Off Requests([\s\S]*?)Incoming Texts/);
    if (leaveMatch) {
      const section = leaveMatch[1];
      const lines = section.split('\n').map(l => l.trim()).filter(l => l && !l.includes('Respond'));
      lines.forEach(line => {
        const parts = line.split('\t'); 
        if (parts.length >= 4) {
          const [name, start, end, type] = parts;
          newIntel.push({
            id: `leave-${Math.random().toString(36).substr(2, 9)}`,
            type: 'leave',
            timestamp: 'PENDING',
            sender: name,
            content: `${type}: ${start} to ${end}`,
            category: type.toLowerCase(),
            draft: `Hi ${name.split(' ')[0]}, we've received your request for ${type} (${start} - ${end}). I've relayed this to the Operations Manager to check the rota coverage. We'll update you once validated.`,
            meta: { dateRange: `${start} - ${end}` }
          });
        }
      });
    }

    // --- VECTOR 3: OPERATIONAL GAPS ---
    const diaryMatch = text.match(/Today's diary([\s\S]*)$/);
    if (diaryMatch) {
      const section = diaryMatch[1];
      const items = section.split(/\r?\n\r?\n/).filter(i => i.toLowerCase().includes('- uncompleted'));
      items.forEach(item => {
        const lines = item.trim().split('\n').map(l => l.trim()).filter(l => l);
        const taskLine = lines.find(l => l.toLowerCase().includes('- uncompleted')) || '';
        const clientLine = lines.find(l => l.startsWith('Clients:')) || '';
        const staffLine = lines.find(l => l.startsWith('Created by:')) || '';

        const task = taskLine.replace(/Created on.*/, '').trim();
        const client = clientLine.replace('Clients:', '').trim();
        const staff = staffLine.replace('Created by:', '').trim();

        newIntel.push({
          id: `gap-${Math.random().toString(36).substr(2, 9)}`,
          type: 'gap',
          timestamp: 'LIVE',
          sender: staff || 'Unknown Staff',
          content: `FAILED_TASK: ${task}`,
          category: 'operational_failure',
          draft: `Hi ${staff.split(' ')[0]}, I see the "${task}" for ${client} is marked as uncompleted. Can you confirm if this was delayed or if there was a barrier to completion? We need this updated for the clinical record.`,
          meta: { client, uncompletedTask: task, priority: 'high' }
        });
      });
    }

    // --- VECTOR 4: INCOMING TEXTS ---
    const sectionStart = text.indexOf('Incoming Texts');
    if (sectionStart !== -1) {
      const content = text.substring(sectionStart + 'Incoming Texts'.length).split(/Birthdays|Today's diary/)[0];
      const messages = content.split(/\breply\b/i).filter(p => p.trim());
      messages.forEach(msg => {
        const lines = msg.trim().split('\n').map(l => l.trim()).filter(l => l);
        if (lines.length >= 2) {
          const timestamp = lines[0];
          const senderLine = lines[1];
          const body = lines.slice(2).join('\n');
          const nameMatch = senderLine.match(/^(.*?)(?:\s*\((.*?)\))?$/);
          const name = nameMatch ? nameMatch[1].trim() : senderLine;
          const phone = nameMatch ? nameMatch[2] : undefined;

          let category = 'general';
          const low = body.toLowerCase();
          if (low.includes('rota') || low.includes('shift')) category = 'rota';
          else if (low.includes('pay') || low.includes('money') || low.includes('timesheet')) category = 'finance';

          const firstName = name.split(' ')[0];
          let draft = `Hi ${firstName}, received. Relayed for review.`;
          if (category === 'rota') draft = `Hi ${firstName}, thanks for the rota update. Relayed to the Rota Manager.`;
          if (category === 'finance') draft = `Hi ${firstName}, thanks. Pushed to Finance Unit to verify against payroll records.`;

          newIntel.push({
            id: `msg-${Math.random().toString(36).substr(2, 9)}`,
            type: 'message',
            timestamp,
            sender: name,
            phone,
            content: body,
            category,
            draft
          });
        }
      });
    }

    if (newIntel.length === 0) {
      setParseError(true);
      setTimeout(() => setParseError(false), 5000);
      return;
    }

    setIntel([...newIntel, ...intel].slice(0, 500));
    setRawText('');
  }

  function copyDraft(msg: InterceptedIntel) {
    void navigator.clipboard.writeText(msg.draft);
    setCopiedId(msg.id);
    setTimeout(() => setCopiedId(null), 2000);
  }

  return (
    <div className="min-h-screen flex flex-col bg-hc-bone font-mono">
      {/* Header telemetry */}
      <div className="px-8 py-5 border-b border-hc-border flex items-center justify-between hc-clay-raised m-4">
        <div>
          <div className="flex items-center gap-3">
            <Layers className="w-6 h-6 text-hc-teal" />
            <h1 className="text-xl font-black text-hc-text tracking-widest uppercase">COMMS_INTERCEPT</h1>
          </div>
          <p className="text-[11px] font-bold text-hc-muted uppercase tracking-[0.3em] mt-1 ml-9">Multi-Vector Operational Intel Hub</p>
        </div>
        
        <div className="flex gap-3">
          <button 
            onClick={() => setShowGuide(!showGuide)}
            className="flex flex-col items-center justify-center px-4 hc-clay-raised hover:bg-hc-clay-dark transition-all rounded group"
          >
            <HelpCircle className="w-4 h-4 text-hc-teal mb-1 group-hover:scale-110 transition-transform" />
            <span className="text-[11px] font-black text-hc-muted uppercase">Guide</span>
          </button>
          {[
            { label: 'ALERTS', count: stats.alerts, color: 'text-hc-red', bg: 'bg-hc-red/10' },
            { label: 'GAPS', count: stats.gaps, color: 'text-hc-amber', bg: 'bg-hc-amber/10' },
            { label: 'LEAVE', count: stats.leave, color: 'text-hc-sage', bg: 'bg-hc-sage/10' },
            { label: 'TEXTS', count: stats.messages, color: 'text-hc-teal', bg: 'bg-hc-teal/10' }
          ].map(s => (
            <div key={s.label} className={`px-4 py-2 ${s.bg} border border-hc-border rounded-xl flex flex-col items-center min-w-[70px]`}>
              <span className={`text-[11px] font-black uppercase opacity-60 ${s.color}`}>{s.label}</span>
              <span className={`text-[11px] font-black tabular-nums ${s.color}`}>{s.count}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 flex min-h-0 overflow-hidden px-4 pb-4 gap-4">
        {/* Left: Input Terminals */}
        <div className="w-[450px] hc-clay-inset p-6 flex flex-col gap-6">
          
          {showGuide && (
            <div className="bg-hc-teal/10 border border-hc-teal/20 p-4 rounded-lg animate-in fade-in duration-300">
              <div className="text-[11px] font-black text-hc-teal uppercase mb-2">SYSTEM_GUIDANCE</div>
              <p className="text-[11px] text-hc-muted leading-relaxed uppercase">
                1. Navigate to your source operational dashboard.<br/>
                2. Press <span className="text-hc-text font-black">CTRL+A</span> then <span className="text-hc-text font-black">CTRL+C</span>.<br/>
                3. Paste the entire dump into the terminal below.<br/>
                4. Press <span className="text-hc-text font-black">SYNTHESIZE</span> to extract actionable intel.
              </p>
            </div>
          )}

          {parseError && (
            <div className="bg-flag-red/10 border border-flag-red/30 p-3 rounded-xl animate-in fade-in duration-300">
              <div className="text-[10px] font-black text-flag-red uppercase tracking-widest">Signal Loss — No intel detected</div>
              <p className="text-[10px] text-hc-muted mt-1">Ensure you pasted the full dashboard dump including section headers (Notices, Incoming Texts, etc.)</p>
            </div>
          )}

          <div className="flex-1 flex flex-col">
            <div className="flex items-center gap-2 mb-3">
              <Terminal className="w-4 h-4 text-hc-teal" />
              <h2 className="text-[11px] font-black text-hc-text uppercase tracking-widest">INGESTION_STREAM</h2>
            </div>
            <div className="relative flex-1 group">
              <textarea
                value={rawText}
                onChange={(e) => setRawText(e.target.value)}
                placeholder="PROMPT: PASTE FULL DASHBOARD DUMP HERE..."
                className="w-full h-full bg-hc-bone hc-clay-inset rounded-lg p-5 text-[11px] font-mono text-hc-text focus:ring-2 ring-hc-teal/30 outline-none resize-none transition-all placeholder:text-hc-muted/30"
              />
              <div className="absolute top-4 right-4 pointer-events-none opacity-5 group-hover:opacity-10 transition-opacity">
                <ShieldAlert className="w-12 h-12 text-hc-text" />
              </div>
            </div>
          </div>
          <div className="flex gap-2">
            <button
              onClick={handleIntercept}
              disabled={!rawText.trim()}
              className="flex-1 py-4 btn-tactical text-xs font-black uppercase tracking-[0.3em] rounded-lg transition-all shadow-lg flex items-center justify-center gap-3 active:scale-[0.98] disabled:opacity-20"
            >
              <Zap className="w-4 h-4 fill-current" />
              SYNTHESIZE
            </button>
            {intel.length > 0 && (
              <button
                onClick={() => setIntel([])}
                title="Clear all intel"
                className="px-4 py-4 hc-clay-raised border border-hc-border rounded-lg text-hc-muted hover:text-flag-red transition-colors"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>

        {/* Right: Intelligence Matrix */}
        <div className="flex-1 flex flex-col bg-transparent">
          <div className="p-4 hc-clay-raised mb-4 flex items-center justify-between">
            <div className="flex gap-1.5">
              {[
                { id: 'all', label: 'ALL_VECTORS' },
                { id: 'alert', label: 'CRITICAL_ALERTS' },
                { id: 'gap', label: 'OPS_GAPS' },
                { id: 'leave', label: 'LEAVE_LOG' },
                { id: 'message', label: 'COMMS' }
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setFilterType(f.id as any)}
                  className={`px-3 py-1.5 text-[11px] font-black uppercase tracking-widest rounded-xl transition-all ${filterType === f.id ? 'bg-hc-teal text-hc-bone shadow-inner' : 'text-hc-muted hover:bg-hc-clay-dark hover:text-hc-text'}`}>
                  {f.label}
                </button>
              ))}
            </div>
            <div className="relative w-64">
              <Search className="w-4 h-4 text-hc-muted absolute left-3 top-1/2 -translate-y-1/2" />
              <input 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="SEARCH_TELEMETRY..."
                className="w-full bg-hc-bone hc-clay-inset rounded-xl px-9 py-2 text-[11px] font-black text-hc-text outline-none focus:ring-2 ring-hc-teal/30 transition-all font-mono"
              />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto space-y-4 scrollbar-thin">
            {filteredIntel.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center opacity-20">
                <Activity className="w-16 h-16 mb-4 text-hc-muted" />
                <p className="text-sm font-black uppercase tracking-[0.5em] text-hc-muted">Ledger_Empty</p>
              </div>
            )}
            {filteredIntel.map((item) => (
              <div key={item.id} className="group animate-in fade-in slide-in-from-right-4 duration-300">
                <div className="hc-clay-raised rounded-2xl overflow-hidden hover:scale-[1.01] transition-all flex h-42 shadow-xl">
                  {/* Vector Accent */}
                  <div className={`w-1 shrink-0 ${
                    item.type === 'alert' ? 'bg-hc-red' : 
                    item.type === 'gap' ? 'bg-hc-amber' : 
                    item.type === 'leave' ? 'bg-hc-sage' : 'bg-hc-teal'
                  }`} />
                  
                  <div className="flex-1 flex overflow-hidden">
                    {/* Left: Intelligence Detail */}
                    <div className="flex-1 p-5 flex flex-col border-r border-hc-border/50 overflow-hidden">
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-3">
                          <div className={`w-7 h-7 rounded-lg flex items-center justify-center ${
                            item.type === 'alert' ? 'bg-hc-red/20 text-hc-red' : 
                            item.type === 'gap' ? 'bg-hc-amber/20 text-hc-amber' : 
                            item.type === 'leave' ? 'bg-hc-sage/20 text-hc-sage' : 'bg-hc-teal/20 text-hc-teal'
                          }`}>
                            {item.type === 'alert' && <AlertCircle className="w-4 h-4" />}
                            {item.type === 'gap' && <XCircle className="w-4 h-4" />}
                            {item.type === 'leave' && <Calendar className="w-4 h-4" />}
                            {item.type === 'message' && <MessageSquare className="w-4 h-4" />}
                          </div>
                          <div>
                            <div className="text-[11px] font-black text-hc-text tracking-tight uppercase tabular-nums">{item.sender}</div>
                            <div className="flex items-center gap-3 mt-0.5">
                              {item.phone && (
                                <div className="flex items-center gap-1 text-[11px] font-bold text-hc-muted uppercase tracking-widest">
                                  <Phone className="w-2.5 h-2.5" /> {item.phone}
                                </div>
                              )}
                              <div className="flex items-center gap-1 text-[11px] font-bold text-hc-muted uppercase tracking-widest">
                                <Clock className="w-2.5 h-2.5" /> {item.timestamp}
                              </div>
                            </div>
                          </div>
                        </div>
                        <span className={`px-2 py-0.5 rounded text-[11px] font-black uppercase tracking-[0.2em] border ${
                          item.type === 'alert' ? 'bg-hc-red/10 text-hc-red border-hc-red/20' : 
                          item.type === 'gap' ? 'bg-hc-amber/10 text-hc-amber border-hc-amber/20' : 
                          item.type === 'leave' ? 'bg-hc-sage/10 text-hc-sage border-hc-sage/20' : 'bg-hc-teal/10 text-hc-teal border-hc-teal/20'
                        }`}>
                          {item.type === 'gap' ? 'OPERATIONAL_FAILURE' : item.type}
                        </span>
                      </div>
                      <div className="flex-1 overflow-y-auto scrollbar-thin text-[11px] text-hc-text/80 font-medium leading-relaxed pr-3 font-mono">
                        {item.content.split('\n').map((line, i) => (
                          <div key={i} className="mb-0.5 last:mb-0">
                            {line.startsWith('FAILED_TASK:') ? <span className="text-hc-amber font-black">{line}</span> : line}
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Right: Command Draft */}
                    <div className="w-[320px] hc-clay-inset m-2 p-5 flex flex-col gap-3">
                      <div className="flex items-center justify-between">
                         <div className="text-[11px] font-black text-hc-muted uppercase tracking-[0.2em] flex items-center gap-2">
                           <Zap className="w-3.5 h-3.5" /> TACTICAL_DRAFT
                         </div>
                         <button 
                           onClick={() => setIntel(intel.filter(i => i.id !== item.id))}
                           className="text-hc-muted hover:text-hc-red transition-colors"
                         >
                           <Trash2 className="w-3" />
                         </button>
                      </div>
                      <div className="flex-1 bg-hc-bone/50 hc-clay-inset rounded-xl p-3 text-[11px] font-mono text-hc-teal leading-relaxed shadow-inner overflow-y-auto scrollbar-thin italic">
                        {item.draft}
                      </div>
                      <button 
                        onClick={() => copyDraft(item)}
                        className={`w-full py-2.5 rounded-xl flex items-center justify-center gap-2 transition-all font-black text-[11px] uppercase tracking-[0.2em] shadow-xl ${
                          copiedId === item.id ? 'bg-hc-teal text-hc-bone' : 'hc-clay-raised text-hc-text hover:bg-hc-clay-dark'
                        }`}
                      >
                        {copiedId === item.id ? <CheckCircle className="w-3.5 h-3.5" /> : <Clipboard className="w-3.5 h-3.5" />}
                        {copiedId === item.id ? 'COPIED' : 'COPY_DRAFT'}
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import type { StaffMember } from '../lib/types';
import { HAZELCARE_HOUSES } from '../lib/compliance-store';
import { ORG_CONFIG } from '../lib/config';
import { Shield, ChevronRight, Search, FileCheck, UserPlus } from 'lucide-react';

import { getAllEntriesAsync } from '../lib/entry-store';
import { computeStaffMonitoring } from '../lib/staff-monitoring';
import { detectClinicalGaps, type ClinicalGap } from '../lib/continuity-engine';
import { History, UserX, AlertCircle } from 'lucide-react';

interface Props {
  staff: StaffMember[];
  onUpdate: (staff: StaffMember[]) => void;
}

export function CompliancePage({ staff }: Props) {
  const [search, setSearch] = useState('');
  const [houseFilter, setHouseFilter] = useState('all');
  const [dbStaff, setDbStaff] = useState<any[]>([]);
  const [booting, setBooting] = useState(true);
  const [gaps, setGaps] = useState<ClinicalGap[]>([]);
  const [tab, setTab] = useState<'personnel' | 'integrity'>('integrity');

  useEffect(() => {
    void getAllEntriesAsync().then(all => {
      if (all.length === 0) { setBooting(false); return; }
      
      const summary: any = { 
        totalEntries: all.length,
        dateFrom: '', dateTo: '', allFlags: [], entryTypes: {}, housePerformance: {}, 
        houses: {} as any 
      };
      all.forEach(e => {
        const h = e.house || 'UNASSIGNED';
        if (!summary.houses[h]) {
          summary.houses[h] = { 
            name: h, 
            entries: [],
            incidents: [],
            safeguarding: [],
            medication: [],
            staffPerformance: [],
            healthSafety: [],
            handovers: [],
            dailySupport: [],
            flags: { red: 0, amber: 0, green: 0 }
          };
        }
        summary.houses[h].entries.push(e);
        if (e.severity === 'red') summary.houses[h].flags.red++;
        if (e.severity === 'amber') summary.houses[h].flags.amber++;
        if (e.severity === 'green') summary.houses[h].flags.green++;
      });

      const analytics = computeStaffMonitoring(summary, { house: 'all', dateFrom: '', dateTo: '' });
      
      // RUN CONTINUITY AUDIT
      const clinicalGaps = detectClinicalGaps(all);
      setGaps(clinicalGaps);
      
      // Combine ledger staff with discovered staff
      const discovered = analytics.staff.map(s => {
        const ledgerMatch = staff.find(ls => ls.name === s.carer);
        return {
          id: s.carer,
          name: s.carer,
          house: s.categoryBreakdown[0]?.category || 'Unknown',
          qualityScore: s.qualityScore,
          entryCount: s.categoryBreakdown.reduce((sum, c) => sum + c.count, 0),
          lastEntry: 'Active', // Ideally extract the latest date
          status: ledgerMatch ? 'Registered' : 'Discovered'
        };
      });

      setDbStaff(discovered);
      setBooting(false);
    });
  }, [staff]);

  const stats = useMemo(() => {
    const total = dbStaff.length;
    const compliant = dbStaff.filter(s => s.qualityScore >= 70).length;
    const pending = dbStaff.filter(s => s.qualityScore < 70 && s.qualityScore >= 45).length;
    const missing = dbStaff.filter(s => s.qualityScore < 45).length;
    return { total, compliant, pending, missing, rate: total ? Math.round((compliant / total) * 100) : 0 };
  }, [dbStaff]);

  const filteredStaff = useMemo(() => {
    return dbStaff.filter(s => {
      const matchSearch = s.name.toLowerCase().includes(search.toLowerCase());
      const matchHouse = houseFilter === 'all' || s.house.includes(houseFilter);
      return matchSearch && matchHouse;
    });
  }, [dbStaff, search, houseFilter]);

  // AUTO-SNAP: jump to top when filters or tabs change
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, [search, houseFilter, tab]);

  return (
    <div className="p-6 lg:p-10 max-w-[2560px] mx-auto animate-in fade-in duration-700">
      
      {/* ── Page Header ── */}
      <div className="mb-12 flex flex-col lg:flex-row lg:items-end justify-between gap-8 border-b border-hc-muted/10 pb-10">
        <div>
          <div className="flex items-center gap-3 mb-4">
             <Shield className="w-6 h-6 text-hc-teal" />
             <h1 className="text-2xl md:text-4xl font-black text-hc-text tracking-[0.2em] uppercase">Regulatory Audit</h1>
          </div>
          <p className="text-hc-muted text-sm font-bold opacity-80 uppercase tracking-wider leading-relaxed">
            Personnel Compliance & Credentialing Matrix — {ORG_CONFIG.name} Governance Standard.
          </p>
        </div>
        
        {/* KPI Slabs */}
        <div className="flex flex-wrap gap-6">
          {[
            { label: 'Network Health', value: `${stats.rate}%`, color: 'text-hc-teal' },
            { label: 'Missing Docs', value: stats.missing, color: 'text-flag-red' },
            { label: 'Pending Review', value: stats.pending, color: 'text-flag-amber' }
          ].map(kpi => (
            <div key={kpi.label} className="hc-clay-raised px-8 py-5 min-w-[160px]">
              <div className="text-[9px] font-black text-hc-muted uppercase tracking-[0.3em] mb-2">{kpi.label}</div>
              <div className={`text-2xl font-black ${kpi.color} tabular-nums tracking-tighter`}>{kpi.value}</div>
            </div>
          ))}
        </div>
      </div>

      {/* ── Tab Matrix ── */}
      <div className="flex gap-4 mb-12 border-b border-hc-border/10">
         <button 
           onClick={() => setTab('integrity')}
           className={`px-8 py-5 text-[10px] font-black uppercase tracking-[0.3em] transition-all border-b-2 
             ${tab === 'integrity' ? 'border-hc-teal text-hc-teal bg-hc-teal/5' : 'border-transparent text-hc-muted hover:text-hc-text opacity-40'}`}
         >
           Clinical Integrity Audit
         </button>
         <button 
           onClick={() => setTab('personnel')}
           className={`px-8 py-5 text-[10px] font-black uppercase tracking-[0.3em] transition-all border-b-2 
             ${tab === 'personnel' ? 'border-hc-teal text-hc-teal bg-hc-teal/5' : 'border-transparent text-hc-muted hover:text-hc-text opacity-40'}`}
         >
           Personnel Compliance
         </button>
      </div>

      {/* ── Tactical Filters (Only show for Personnel for now) ── */}
      {tab === 'personnel' && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
          <div className="md:col-span-2 relative group">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-hc-muted group-focus-within:text-hc-teal transition-colors w-4 h-4" />
            <input 
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="QUERY PERSONNEL RECORDS..." 
              className="w-full h-[60px] hc-clay-inset pl-16 pr-8 text-[11px] font-black uppercase tracking-[0.2em] text-hc-text focus:outline-none transition-all" 
            />
          </div>
          <select 
            value={houseFilter}
            onChange={e => setHouseFilter(e.target.value)}
            className="h-[60px] hc-clay-inset px-6 text-[10px] font-black uppercase tracking-[0.2em] text-hc-text outline-none"
          >
            <option value="all">ALL STATIONS</option>
            {HAZELCARE_HOUSES.map(h => <option key={h} value={h}>{h.toUpperCase()}</option>)}
          </select>
          <button className="h-[60px] btn-tactical flex items-center justify-center gap-3 shadow-xl">
             <UserPlus className="w-4 h-4" /> Add Personnel
          </button>
        </div>
      )}

      {/* ── CONTENT SWITCHER ── */}
      {tab === 'integrity' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           {/* Gaps List */}
           <div className="lg:col-span-2 space-y-4">
              <div className="flex items-center justify-between px-2 mb-4">
                 <h2 className="text-[11px] font-black text-hc-text uppercase tracking-[0.4em]">Evidence Continuity Gaps</h2>
                 <span className="pill !bg-flag-red text-hc-bone">{gaps.length} GAPS DETECTED</span>
              </div>
              <div className="space-y-3">
                 {gaps.slice(0, 50).map(gap => (
                   <div key={gap.id} className="hc-clay-raised p-6 flex flex-col md:flex-row md:items-center justify-between gap-6 hover:scale-[1.01] transition-transform relative overflow-hidden group">
                      {/* Operational Tag */}
                      <div className="absolute top-0 right-0 px-3 py-1 bg-hc-teal/10 border-b border-l border-hc-teal/20 text-[8px] font-black text-hc-teal uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                         Forensic Recon Active
                      </div>
                      
                      <div className="flex items-center gap-6">
                         <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${gap.severity === 'red' ? 'bg-flag-red/10 text-flag-red' : 'bg-flag-amber/10 text-flag-amber'}`}>
                            {gap.severity === 'red' ? <UserX size={24} /> : <History size={24} />}
                         </div>
                         <div>
                            <div className="flex items-center gap-2">
                               <div className="text-[13px] font-black text-hc-text uppercase tracking-tight">{gap.client}</div>
                               {gap.likelyCarers.length > 0 && <span className="text-[8px] font-black bg-hc-teal/20 text-hc-teal px-2 py-0.5 rounded-full uppercase">Inferred</span>}
                            </div>
                            <div className="text-[9px] font-black text-hc-muted uppercase tracking-widest mt-1">Station: {gap.house} · {gap.date}</div>
                         </div>
                      </div>

                      <div className="flex flex-col gap-3 md:items-end">
                         <div className="text-[9px] font-black text-hc-muted uppercase tracking-widest opacity-60">Prime Attendance Witness</div>
                         <div className="flex flex-wrap gap-2 justify-end">
                            {gap.likelyCarers.length > 0 ? (
                               gap.likelyCarers.map(c => (
                                 <span key={c} className="pill-teal !px-4 !py-1.5 border-hc-teal/40">{c.toUpperCase()}</span>
                               ))
                            ) : (
                               <span className="pill-red !px-4 !py-1.5 opacity-60 italic text-[8px]">No Witness Identified (Deep Silence)</span>
                            )}
                         </div>
                      </div>
                   </div>
                 ))}
                 {gaps.length > 50 && (
                    <div className="hc-clay-inset p-4 text-center rounded-2xl text-[9px] font-black text-hc-muted uppercase tracking-widest opacity-40">
                       + {gaps.length - 50} additional continuity gaps identified in historical data
                    </div>
                 )}
                 {gaps.length === 0 && !booting && (
                    <div className="hc-clay-inset p-20 text-center rounded-[3rem]">
                       <FileCheck className="w-16 h-16 text-hc-teal mx-auto mb-6 opacity-40" />
                       <div className="text-[11px] font-black text-hc-teal uppercase tracking-[0.5em]">Forensic Integrity: 100% — No Coverage Gaps Found.</div>
                    </div>
                 )}
              </div>
           </div>

           {/* Audit Intelligence Sidebar */}
           <div className="space-y-8">
              <div className="hc-clay-raised p-8 space-y-6">
                 <div className="flex items-center gap-3">
                    <AlertCircle className="text-hc-teal" />
                    <h3 className="text-xs font-black text-hc-text uppercase tracking-widest">Audit Context</h3>
                 </div>
                 <p className="text-[10px] font-bold text-hc-muted uppercase tracking-wider leading-relaxed">
                   The Sovereign continuity engine scans cross-client telemetry. If Andrew has a gap, but Sarah was recording notes for other clients, the system identifies Sarah as the witness for that missing shift.
                 </p>
                 <div className="h-px bg-hc-border opacity-10" />
                 <div className="space-y-4">
                    <div className="flex items-center justify-between">
                       <span className="text-[9px] font-black text-hc-muted uppercase tracking-tighter">Database Scan Rank</span>
                       <span className="text-[10px] font-black text-hc-teal">FORENSIC GRADE</span>
                    </div>
                    <div className="flex items-center justify-between">
                       <span className="text-[9px] font-black text-hc-muted uppercase tracking-tighter">Cross-Inference</span>
                       <span className="text-[10px] font-black text-hc-green">ACTIVE</span>
                    </div>
                 </div>
              </div>

              <div className="hc-clay-inset p-8 space-y-6 opacity-60">
                 <h3 className="text-[10px] font-black text-hc-text uppercase tracking-widest">Recovery Protocol</h3>
                 <p className="text-[9px] font-bold text-hc-muted uppercase tracking-wider leading-relaxed">
                   Use the identified witness list to initiate "Legacy Reconstruction" sessions with relevant personnel to close all clinical gaps.
                 </p>
              </div>
           </div>
        </div>
      ) : (
        <div className="hc-clay-raised overflow-hidden relative">
          <div className="overflow-x-auto scrollbar-thin">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-black/5 border-b border-hc-muted/10">
                  <th className="px-8 py-6 text-[10px] font-black text-hc-muted uppercase tracking-[0.3em]">Carer Identity</th>
                  <th className="px-8 py-6 text-[10px] font-black text-hc-muted uppercase tracking-[0.3em]">Station</th>
                  <th className="px-8 py-6 text-[10px] font-black text-hc-muted uppercase tracking-[0.3em]">Documentation Role</th>
                  <th className="px-8 py-6 text-[10px] font-black text-hc-muted uppercase tracking-[0.3em]">Clinical Accuracy</th>
                  <th className="px-8 py-6 text-[10px] font-black text-hc-muted uppercase tracking-[0.3em]">Log Volume</th>
                  <th className="px-8 py-6 text-[10px] font-black text-hc-muted uppercase tracking-[0.3em]">Operational Status</th>
                  <th className="px-8 py-6"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-hc-muted/5">
                {filteredStaff.map((s) => (
                  <tr key={s.id} className="hover:bg-black/[0.02] transition-colors group">
                    <td className="px-8 py-6">
                       <div className="flex items-center gap-4">
                          <div className="w-10 h-10 rounded-xl hc-clay-inset flex items-center justify-center font-black text-hc-muted text-xs uppercase">{s.name.charAt(0)}</div>
                          <div className="font-black text-sm text-hc-text tracking-tight uppercase">{s.name}</div>
                       </div>
                    </td>
                    <td className="px-8 py-6 text-[10px] font-black text-hc-muted uppercase tracking-widest">{s.house}</td>
                    <td className="px-8 py-6 text-[10px] font-bold text-hc-muted uppercase tracking-widest">Support Personnel</td>
                    <td className="px-8 py-6">
                        <div className="flex flex-col gap-1">
                           <span className={`text-[10px] font-black uppercase tracking-widest ${s.qualityScore >= 70 ? 'text-flag-green' : s.qualityScore >= 45 ? 'text-flag-amber' : 'text-flag-red'}`}>
                             {s.qualityScore}% Standard Adherence
                           </span>
                           <div className="h-1 w-24 rounded-full bg-black/10 overflow-hidden">
                              <div className={`h-full ${s.qualityScore >= 70 ? 'bg-flag-green' : s.qualityScore >= 45 ? 'bg-flag-amber' : 'bg-flag-red'}`} style={{width: `${s.qualityScore}%`}} />
                           </div>
                        </div>
                    </td>
                    <td className="px-8 py-6 text-[10px] font-bold text-hc-muted uppercase tracking-widest">{s.entryCount} Intelligence Points</td>
                    <td className="px-8 py-6">
                        <span className={`pill !bg-hc-bg border border-hc-muted/10 ${s.status === 'Registered' ? 'text-hc-teal' : 'text-hc-amber'}`}>
                          {s.status}
                        </span>
                    </td>
                    <td className="px-8 py-6 text-right">
                       <button className="p-3 rounded-xl hc-clay-raised text-hc-muted hover:text-hc-teal transition-all active:scale-90">
                          <ChevronRight className="w-4 h-4" />
                       </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {filteredStaff.length === 0 && (
              <div className="py-24 text-center">
                 <FileCheck className="w-12 h-12 text-hc-muted mx-auto mb-6 opacity-20" />
                 <div className="text-[11px] font-black text-hc-muted uppercase tracking-[0.4em]">No personnel records matched query.</div>
              </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
}

