// ─────────────────────────────────────────────────────────────────────────────
// TASK GENERATION ENGINE
// Maps care plan domains → Nourish task definitions
// ─────────────────────────────────────────────────────────────────────────────

type TaskFrequency = 'daily' | 'weekly' | 'event';

interface NourishTask {
  id: string;
  name: string;
  notes: string;
  frequency: TaskFrequency;
  mandatory: boolean;
  source: string;
  domain: string;
  evidence: string[];
}

function cleanLine(input: string, max = 2000): string {
  const normalized = (input || '').replace(/\s+/g, ' ').trim();
  if (!normalized) return '';
  if (normalized.length <= max) return normalized;
  return normalized.slice(0, max - 1).trimEnd() + '…';
}

const DAILY_DOMAIN_KEYWORDS = [
  'medication', 'mental health', 'personal care', 'hygiene', 'nutrition',
  'hydration', 'daily routine', 'continence', 'mobility', 'pain',
  'sleep', 'infection', 'communication', 'engagement', 'social',
];

const WEEKLY_DOMAIN_KEYWORDS = [
  'skin integrity', 'pressure care', 'financial', 'cultural', 'spiritual',
  'environmental', 'rights', 'intimacy', 'adaptive',
];

const EVENT_DOMAIN_KEYWORDS = [
  'safeguarding', 'incident', 'aggression', 'deterioration',
];

function inferFrequency(domainTitle: string): TaskFrequency {
  const lower = domainTitle.toLowerCase();
  if (EVENT_DOMAIN_KEYWORDS.some(k => lower.includes(k))) return 'event';
  if (WEEKLY_DOMAIN_KEYWORDS.some(k => lower.includes(k))) return 'weekly';
  if (DAILY_DOMAIN_KEYWORDS.some(k => lower.includes(k))) return 'daily';
  return 'daily'; // default
}

function isMandatoryTask(domainTitle: string, notes: string): boolean {
  const lower = domainTitle.toLowerCase() + ' ' + notes.toLowerCase();
  return (
    lower.includes('medication') ||
    lower.includes('mental health') ||
    lower.includes('fire') ||
    lower.includes('risk') ||
    lower.includes('safeguarding') ||
    lower.includes('aggression')
  );
}

function buildTaskName(domain: CarePlanDomain, clientName: string): string {
  const title = domain.title;
  const firstName = clientName.split(' ')[0] || 'Client';
  
  // Try to find a specific action word from the identified need to make it less generic
  const need = (domain.identifiedNeed || '').toLowerCase();
  let action = '';
  
  if (title.includes('Nutrition')) {
    if (need.includes('breakfast')) action = 'with Breakfast';
    else if (need.includes('lunch')) action = 'with Lunch';
    else if (need.includes('dinner') || need.includes('tea')) action = 'with Dinner';
    else action = 'with Meals & Hydration';
  } else if (title.includes('Personal Care')) {
    if (need.includes('shower')) action = 'to Shower';
    else if (need.includes('bath')) action = 'to Bath';
    else if (need.includes('dress')) action = 'to Dress & Groom';
    else action = 'with Personal Care';
  } else if (title.includes('Environment')) {
    action = 'to maintain a Safe Environment';
  } else if (title.includes('Social')) {
    action = 'to engage in Social Activities';
  }

  const taskNames: Record<string, string> = {
    'Medication Management & Safety': `Support ${firstName} with Medication`,
    'Mental Health & Emotional Wellbeing': `${firstName}'s Emotional Wellbeing Check`,
    'Personal Care & Physical Presentation': `Support ${firstName} ${action || 'with Personal Care'}`,
    'Continence & Personal Hygiene': `Support ${firstName} with Hygiene & Continence`,
    'Nutrition, Hydration & Diet': `Help ${firstName} ${action || 'with Nutrition & Hydration'}`,
    'Life Skills & Daily Routine': `Support ${firstName}'s Daily Routine`,
    'Social Engagement & Relationships': `Help ${firstName} ${action || 'Socialise & Connect'}`,
    'Mobility, Movement & Exercise': `Support ${firstName} with Mobility`,
    'Pain Management & Comfort': `Pain & Comfort Check for ${firstName}`,
    'Rest & Sleep Patterns': `Support ${firstName}'s Sleep Pattern`,
    'Infection Control & Public Health': `Infection Control for ${firstName}`,
    'Communication & Sensory Integration': `Support ${firstName}'s Communication`,
    'Environment & Physical Safety': `Help ${firstName} ${action || 'stay Safe & Secure'}`,
    'Adaptive Living Environment': `Support ${firstName} in their Home`,
    'Skin Integrity & Pressure Care': `Skin & Pressure Care for ${firstName}`,
    'Financial Management & Autonomy': `Support ${firstName} with Finances`,
    'Rights, Choice & Inclusion': `Support ${firstName}'s Rights & Choices`,
    'Holistic Health & Vitality': `Health & Vitality Check for ${firstName}`,
    'Respiratory Health & Support': `Support ${firstName}'s Respiratory Health`,
    'Cultural, Spiritual & Personal Beliefs': `Support ${firstName}'s Beliefs & Culture`,
    'Intimacy & Personal Expression': `Support ${firstName}'s Personal Expression`,
  };

  return taskNames[title] || `${title} (${firstName})`;
}

function buildTaskNotes(domain: CarePlanDomain): string {
  const needLine = cleanLine(domain.identifiedNeed, 1000);
  const supportLine = cleanLine(domain.howToAchieve || domain.plannedOutcomes, 1000);
  const riskLine = cleanLine(domain.riskMitigation || domain.riskTitle, 1000);
  const parts: string[] = [];
  if (needLine) parts.push(`Need: ${needLine}`);
  if (supportLine) parts.push(`Support: ${supportLine}`);
  if (riskLine) parts.push(`Watch for: ${riskLine}`);
  parts.push('Staff should keep this brief, specific and person-centred. Record who was involved, what happened, why support was needed, how support was provided, what the person accepted or declined, and the outcome.');
  return parts.join('\n');
}

function collectEvidence(domain: CarePlanDomain): string[] {
  const evidence: string[] = [];
  if (domain.identifiedNeed?.trim()) evidence.push(`Need: ${domain.identifiedNeed.trim()}`);
  if (domain.riskTitle?.trim()) evidence.push(`Risk: ${domain.riskTitle.trim()}`);
  if (domain.riskDescription?.trim()) evidence.push(`Risk detail: ${domain.riskDescription.trim()}`);
  if (domain.riskMitigation?.trim()) evidence.push(`Mitigation: ${domain.riskMitigation.trim()}`);
  if (domain.howToAchieve?.trim()) evidence.push(`Support method: ${domain.howToAchieve.trim()}`);
  return evidence;
}

function generateTasksFromCarePlan(client: FullClient): NourishTask[] {
  if (!client.carePlan?.domains) return [];

  const enabledDomains = client.carePlan.domains.filter(d => d.enabled);
  if (enabledDomains.length === 0) return [];

  return enabledDomains
    .map(domain => {
      const evidence = collectEvidence(domain);
      const notes = buildTaskNotes(domain);
      const frequency = inferFrequency(domain.title);
      const name = buildTaskName(domain, client.name);
      const mandatory = isMandatoryTask(domain.title, notes);
      const source = `Care Plan - ${domain.title}${domain.riskTitle ? ` / Risk: ${domain.riskTitle}` : ''}`;

      return { 
        id: `cp-${domain.title.replace(/\s+/g, '-')}`,
        name, notes, frequency, mandatory, source, domain: domain.title, evidence 
      };
    })
    .filter(task => task.evidence.length > 0);
}

function generateTasksFromRiskAssessment(client: FullClient): NourishTask[] {
  const risk = client.risk;
  if (!risk?.risks?.length) return [];

  return risk.risks
    .filter(r => (r.title || '').trim().length > 0)
    .map(riskItem => {
      const controls = (riskItem.controls || []).map(c => cleanLine(c, 120)).filter(Boolean);
      const description = cleanLine(riskItem.description, 160);
      const notesLines: string[] = [];
      if (description) notesLines.push(`Risk context: ${description}`);
      if (controls.length) notesLines.push(`Controls: ${controls.slice(0, 2).join(' | ')}`);
      notesLines.push('Record: trigger observed, action taken, client response, escalation if needed.');

      return {
        id: `risk-${riskItem.title.replace(/\s+/g, '-')}`,
        name: `Risk Response - ${cleanLine(riskItem.title, 72)}`,
        notes: notesLines.join('\n'),
        frequency: 'event' as TaskFrequency,
        mandatory: true,
        source: `Risk Assessment - ${riskItem.title}`,
        domain: 'Risk Assessment',
        evidence: [
          `Risk: ${riskItem.title}`,
          ...controls.map(c => `Control: ${c}`),
        ],
      };
    });
}

function generateTasksFromSupportPlan(client: FullClient): NourishTask[] {
  const needs = client.supportPlan?.needs || [];
  if (!needs.length) return [];

  return needs
    .filter(need => (need.area || '').trim().length > 0)
    .map(need => {
      const area = cleanLine(need.area, 90);
      const support = cleanLine(need.howToSupport || need.canDoMyself, 170);
      const risk = cleanLine(need.risks, 140);
      const notes: string[] = [];
      if (support) notes.push(`Support: ${support}`);
      if (risk) notes.push(`Risk focus: ${risk}`);
      notes.push('Record: what was done, client response, refusal/escalation.');

      const sourceText = [need.canDoMyself, need.howToSupport, need.risks].join(' ').toLowerCase();
      const mandatory = /risk|safeguard|medication|aggress|falls|self-harm|incident/i.test(sourceText);

      return {
        id: `sp-${area.replace(/\s+/g, '-')}`,
        name: `Support Plan - ${area}`,
        notes: notes.join('\n'),
        frequency: inferFrequency(area),
        mandatory,
        source: `Support Plan - ${area}`,
        domain: area,
        evidence: [
          need.canDoMyself ? `Need: ${cleanLine(need.canDoMyself, 180)}` : '',
          need.howToSupport ? `Support method: ${cleanLine(need.howToSupport, 180)}` : '',
          need.risks ? `Risk: ${cleanLine(need.risks, 150)}` : '',
        ].filter(Boolean),
      };
    });
}

function dedupeTasks(tasks: NourishTask[]): NourishTask[] {
  const seen = new Set<string>();
  const out: NourishTask[] = [];
  for (const task of tasks) {
    const key = task.name.toLowerCase().trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(task);
  }
  return out;
}

function generateTasksForClient(client: FullClient): NourishTask[] {
  const fromCarePlan = generateTasksFromCarePlan(client);
  const fromRisk = generateTasksFromRiskAssessment(client);
  const fromSupportPlan = generateTasksFromSupportPlan(client);
  return dedupeTasks([...fromCarePlan, ...fromRisk, ...fromSupportPlan]).filter(task => task.evidence.length > 0);
}

function formatForExport(client: FullClient, tasks: NourishTask[]): string {
  const daily = tasks.filter(t => t.frequency === 'daily');
  const weekly = tasks.filter(t => t.frequency === 'weekly');
  const event = tasks.filter(t => t.frequency === 'event');
  const date = new Date().toLocaleDateString('en-GB');

  let out = `NOTE TITLE: CareOps Personalised Tasks (Care Plan Aligned) - ${client.name}\n`;
  out += `Generated: ${date} | Source: CareOps - Care Plan Builder\n\n`;
  out += `PURPOSE\n`;
  out += `These tasks are derived directly from ${client.name}'s current care plans, support plans and risk assessments to show what support needs to happen and how it should be evidenced.\n\n`;
  out += `RULES\n`;
  out += `- Build as Client Tasks in Nourish.\n`;
  out += `- Set Task Notes mandatory for all tasks marked [MANDATORY].\n`;
  out += `- Keep notes short enough for staff to use on shift.\n`;
  out += `- Do not change tasks without updating the underlying care plan/risk assessment first.\n`;
  out += `- Do not create tasks without evidence from care plan, support plan, or risk fields.\n\n`;
  out += `-----------------------------------------------------\n`;

  if (daily.length > 0) {
    out += `DAILY TASKS\n\n`;
    daily.forEach((t, i) => {
      out += `${i + 1}. Task name: ${t.name}${t.mandatory ? ' [MANDATORY]' : ''}\n`;
      out += `   Frequency: Daily\n`;
      out += `   Task Notes: ${t.notes.replace(/\n/g, '\n   ')}\n`;
      out += `   Source: ${t.source}\n`;
      if (t.evidence.length) {
        out += `   Evidence:\n`;
        t.evidence.forEach(ev => { out += `   - ${ev}\n`; });
      }
      out += `\n`;
    });
  }

  if (weekly.length > 0) {
    out += `WEEKLY TASKS\n\n`;
    weekly.forEach((t, i) => {
      out += `${i + 1}. Task name: ${t.name}${t.mandatory ? ' [MANDATORY]' : ''}\n`;
      out += `   Frequency: Weekly\n`;
      out += `   Task Notes: ${t.notes.replace(/\n/g, '\n   ')}\n`;
      out += `   Source: ${t.source}\n`;
      if (t.evidence.length) {
        out += `   Evidence:\n`;
        t.evidence.forEach(ev => { out += `   - ${ev}\n`; });
      }
      out += `\n`;
    });
  }

  if (event.length > 0) {
    out += `EVENT-DRIVEN TASKS (create only when triggered)\n\n`;
    event.forEach((t, i) => {
      out += `${i + 1}. Task name: ${t.name}\n`;
      out += `   Frequency: When triggered\n`;
      out += `   Task Notes: ${t.notes.replace(/\n/g, '\n   ')}\n`;
      out += `   Source: ${t.source}\n`;
      if (t.evidence.length) {
        out += `   Evidence:\n`;
        t.evidence.forEach(ev => { out += `   - ${ev}\n`; });
      }
      out += `\n`;
    });
  }

  out += `-----------------------------------------------------\n`;
  out += `REVIEW\n`;
  out += `Review tasks at the next scheduled care plan review, or sooner if there is a significant change in risk, presentation, medication, or environmental safety.\n`;

  return out;
}

// DOCX Generation Helper
async function generateBeautifulDocx(client: FullClient, tasks: NourishTask[]) {
  const daily = tasks.filter(t => t.frequency === 'daily');
  const weekly = tasks.filter(t => t.frequency === 'weekly');
  const event = tasks.filter(t => t.frequency === 'event');
  const dateStr = new Date().toLocaleDateString('en-GB');

  const border = { style: BorderStyle.SINGLE, size: 1, color: "E5E7EB" };
  const cellMargins = { top: 120, bottom: 120, left: 180, right: 180 };

  const buildTaskRows = (taskList: NourishTask[], label: string) => {
    if (taskList.length === 0) return [];
    
    const rows = [
      new TableRow({
        children: [
          new TableCell({
            columnSpan: 2,
            shading: { fill: "F3F4F6", type: ShadingType.CLEAR },
            margins: cellMargins,
            children: [
              new Paragraph({
                children: [
                  new TextRun({ text: label, bold: true, size: 20, color: "4B5563" })
                ]
              })
            ]
          })
        ]
      })
    ];

    taskList.forEach((t, i) => {
      rows.push(
        new TableRow({
          children: [
            new TableCell({
              width: { size: 2500, type: WidthType.DXA },
              borders: { bottom: border, right: border },
              margins: cellMargins,
              children: [
                new Paragraph({
                  children: [
                    new TextRun({ text: `${i + 1}. ${t.name}`, bold: true, size: 22, color: "111827" }),
                    ...(t.mandatory ? [new TextRun({ text: "\n[MANDATORY]", bold: true, size: 16, color: "EF4444" })] : [])
                  ]
                })
              ]
            }),
            new TableCell({
              width: { size: 7500, type: WidthType.DXA },
              borders: { bottom: border },
              margins: cellMargins,
              children: [
                new Paragraph({
                  children: [
                    new TextRun({ text: "TASK NOTES INSTRUCTION:", bold: true, size: 16, color: "9CA3AF" })
                  ],
                  spacing: { after: 120 }
                }),
                ...t.notes.split('\n').map(line => new Paragraph({
                  children: [new TextRun({ text: line, size: 20, color: "374151" })],
                  spacing: { after: 80 }
                }))
              ]
            })
          ]
        })
      );
    });

    return rows;
  };

  const doc = new Document({
    styles: {
      default: { document: { run: { font: "Arial", size: 24 } } }
    },
    sections: [{
      properties: {
        page: {
          margin: { top: 720, right: 720, bottom: 720, left: 720 }
        }
      },
      headers: {
        default: new Header({
          children: [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              children: [
                new TextRun({ text: "HAZEL CARE LTD - OPERATIONS HUB", bold: true, size: 18, color: "0D9488" })
              ]
            })
          ]
        })
      },
      footers: {
        default: new Footer({
          children: [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              children: [
                new TextRun({ text: "Page ", size: 16, color: "9CA3AF" }),
                new TextRun({ children: [PageNumber.CURRENT], size: 16, color: "9CA3AF" }),
                new TextRun({ text: " | Generated: " + dateStr, size: 16, color: "9CA3AF" })
              ]
            })
          ]
        })
      },
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          heading: HeadingLevel.HEADING_1,
          children: [
            new TextRun({ text: client.name, bold: true, size: 40, color: "111827" })
          ]
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [
            new TextRun({ text: "Full Task Pack for Nourish / Care System Entry", size: 24, color: "6B7280" })
          ],
          spacing: { after: 400 }
        }),
        new Table({
          width: { size: 10000, type: WidthType.DXA },
          rows: [
            ...buildTaskRows(daily, "DAILY TASKS"),
            ...buildTaskRows(weekly, "WEEKLY TASKS"),
            ...buildTaskRows(event, "EVENT-DRIVEN TASKS")
          ]
        })
      ]
    }]
  });

  const blob = await Packer.toBlob(doc);
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `Nourish-Task-Pack-${client.name.replace(/\s+/g, '-')}.docx`;
  a.click();
  URL.revokeObjectURL(url);
}

// COMPONENTS
const FREQ_CONFIG = {
  daily: { label: 'Daily', icon: <Clock size={12} />, color: 'text-hc-teal', bg: 'bg-hc-teal/10 border-hc-teal/20' },
  weekly: { label: 'Weekly', icon: <Calendar size={12} />, color: 'text-flag-amber', bg: 'bg-flag-amber/10 border-flag-amber/20' },
  event: { label: 'Event-Driven', icon: <Zap size={12} />, color: 'text-flag-red', bg: 'bg-flag-red/10 border-flag-red/20' },
};

function TaskCard({ task, index, onUpdate }: { task: NourishTask; index: number, onUpdate?: (id: string, notes: string) => void }) {
  const [expanded, setExpanded] = useState(false);
  const [copied, setCopied] = useState<'name' | 'notes' | ''>('');
  const [editingNotes, setEditingNotes] = useState(false);
  const [notesDraft, setNotesDraft] = useState(task.notes);
  const freq = FREQ_CONFIG[task.frequency];

  const copyValue = async (kind: 'name' | 'notes', text: string, e?: MouseEvent<HTMLButtonElement>) => {
    e?.stopPropagation();
    await navigator.clipboard.writeText(text);
    setCopied(kind);
    window.setTimeout(() => setCopied((current) => (current === kind ? '' : current)), 1500);
  };

  return (
    <div className={`hc-clay-raised rounded-2xl overflow-hidden border ${task.mandatory ? 'border-flag-red/20' : 'border-hc-border/5'} transition-all`}>
      <div
        onClick={() => setExpanded(e => !e)}
        className="w-full flex items-start gap-3 p-4 text-left hover:bg-white/[0.02] transition-all cursor-pointer"
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            setExpanded((current) => !current);
          }
        }}
      >
        {/* Index */}
        <span className="w-6 h-6 rounded-lg hc-clay-inset flex items-center justify-center text-[10px] font-black text-hc-muted shrink-0 mt-0.5">
          {index}
        </span>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-[11px] font-black text-hc-text uppercase tracking-wide">{task.name}</span>
            {task.mandatory && (
              <span className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-flag-red/10 border border-flag-red/20 text-[9px] font-black text-flag-red uppercase tracking-widest">
                <AlertTriangle size={8} /> Mandatory Notes
              </span>
            )}
          </div>
          <div className="flex items-center gap-2 mt-2 flex-wrap">
            <button
              onClick={(e) => copyValue('name', task.name, e)}
              className="px-2.5 py-1 rounded-lg hc-clay-inset text-[9px] font-black uppercase tracking-widest text-hc-muted hover:text-hc-teal transition-colors"
            >
              {copied === 'name' ? 'Copied name' : 'Copy name'}
            </button>
            <button
              onClick={(e) => copyValue('notes', task.notes, e)}
              className="px-2.5 py-1 rounded-lg hc-clay-inset text-[9px] font-black uppercase tracking-widest text-hc-muted hover:text-hc-teal transition-colors"
            >
              {copied === 'notes' ? 'Copied notes' : 'Copy notes'}
            </button>
          </div>
          <div className="flex items-center gap-2 mt-1.5 flex-wrap">
            <span className={`flex items-center gap-1 px-2 py-0.5 rounded-full border text-[9px] font-black uppercase tracking-widest ${freq.bg} ${freq.color}`}>
              {freq.icon} {freq.label}
            </span>
            <span className="text-[9px] text-hc-muted truncate max-w-[200px]">{task.source}</span>
          </div>
        </div>

        <span className="text-hc-muted shrink-0 mt-1">
          {expanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
        </span>
      </div>

      {expanded && (
        <div className="px-4 pb-4 space-y-3 border-t border-hc-border/10 pt-3 animate-in slide-in-from-top-2 duration-200">
          <div>
            <div className="flex items-center justify-between mb-1.5">
              <div className="text-[8px] font-black text-hc-muted uppercase tracking-widest">Task Notes Instruction</div>
              <button 
                onClick={() => setEditingNotes(!editingNotes)}
                className="text-[8px] font-black text-hc-teal uppercase tracking-widest hover:underline"
              >
                {editingNotes ? 'Preview' : 'Edit Manually'}
              </button>
            </div>
            
            {editingNotes ? (
              <textarea
                value={notesDraft}
                onChange={(e) => setNotesDraft(e.target.value)}
                onBlur={() => onUpdate?.(task.id, notesDraft)}
                rows={5}
                className="w-full hc-clay-inset rounded-xl p-3 text-[11px] text-hc-text bg-hc-surface font-mono outline-none focus:ring-1 focus:ring-hc-teal/30"
              />
            ) : (
              <div className="hc-clay-inset rounded-xl p-3 text-[11px] text-hc-text/80 leading-relaxed whitespace-pre-line">
                {task.notes}
              </div>
            )}
            
            <button
              onClick={(e) => copyValue('notes', task.notes, e)}
              className="mt-2 text-[9px] font-black uppercase tracking-widest text-hc-teal hover:underline"
            >
              {copied === 'notes' ? 'Copied notes' : 'Copy notes'}
            </button>
          </div>
          <div>
            <div className="text-[8px] font-black text-hc-muted uppercase tracking-widest mb-1">Source</div>
            <div className="text-[10px] text-hc-muted font-bold">{task.source}</div>
          </div>
          {task.evidence.length > 0 && (
            <div>
              <div className="text-[8px] font-black text-hc-muted uppercase tracking-widest mb-1">Evidence</div>
              <ul className="list-disc pl-4 space-y-1 text-[10px] text-hc-muted">
                {task.evidence.map((ev, i) => (
                  <li key={i}>{ev}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function FreqSection({
  label, tasks, freq, icon, onTaskUpdate
}: {
  label: string;
  tasks: NourishTask[];
  freq: TaskFrequency;
  icon: React.ReactNode;
  onTaskUpdate?: (id: string, notes: string) => void;
}) {
  const [open, setOpen] = useState(true);
  const cfg = FREQ_CONFIG[freq];

  if (tasks.length === 0) return null;

  return (
    <div className="space-y-2">
      <button
        onClick={() => setOpen(o => !o)}
        className="w-full flex items-center gap-3 px-1"
      >
        <span className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest ${cfg.color}`}>
          {icon} {label}
          <span className="ml-1 px-1.5 py-0.5 rounded-full hc-clay-inset text-hc-muted text-[9px]">
            {tasks.length}
          </span>
        </span>
        <div className="flex-1 h-px bg-hc-border/10" />
        <ChevronDown size={12} className={`text-hc-muted transition-transform duration-200 ${open ? '' : '-rotate-90'}`} />
      </button>

      {open && (
        <div className="space-y-2 animate-in slide-in-from-top-2 duration-200">
          {tasks.map((t, i) => (
            <TaskCard key={`${freq}-${i}`} task={t} index={i + 1} onUpdate={onTaskUpdate} />
          ))}
        </div>
      )}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN PAGE
// ─────────────────────────────────────────────────────────────────────────────

export function NourishTaskPack() {
  const [clients, setClients] = useState<FullClient[]>(() => loadClients());
  const clientHasTaskSources = (client: FullClient) =>
    !!client.carePlan?.domains?.some(d => d.enabled) ||
    !!client.supportPlan?.needs?.some(n => (n.area || '').trim().length > 0) ||
    !!client.risk?.risks?.some(r => (r.title || '').trim().length > 0);
  
  const [selectedId, setSelectedId] = useState<string>(() => {
    const first = clients.find(c => clientHasTaskSources(c));
    return first?.id || clients[0]?.id || '';
  });

  const [copied, setCopied] = useState(false);
  const [importLoading, setImportLoading] = useState(false);
  const [importInfo, setImportInfo] = useState('');
  const [refineInput, setRefineInput] = useState('');
  const [refining, setRefining] = useState(false);

  useEffect(() => {
    const syncClients = () => setClients(loadClients());
    syncClients();
    window.addEventListener('storage', syncClients);
    window.addEventListener('hc-clients-updated', syncClients);
    return () => {
      window.removeEventListener('storage', syncClients);
      window.removeEventListener('hc-clients-updated', syncClients);
    };
  }, []);

  useEffect(() => {
    if (selectedId && clients.some(c => c.id === selectedId)) return;
    const fallback = clients.find(c => clientHasTaskSources(c)) || clients[0];
    if (fallback) setSelectedId(fallback.id);
  }, [clients, selectedId]);

  // STRESS TEST HANDLER
  const triggerStressTest = async () => {
    try {
      const stressClient = await runTaskStressTest();
      setClients(prev => [stressClient, ...prev]);
      setSelectedId(stressClient.id);
      setImportInfo('🚀 STRESS TEST ACTIVE: 1,000 TASKS INJECTED');
    } catch (e) {
      alert(e instanceof Error ? e.message : 'Stress test failed');
    }
  };

  const selectedClient = useMemo(
    () => clients.find(c => c.id === selectedId) || null,
    [clients, selectedId]
  );

  // Local state for manually overridden tasks or refined results
  const [manualOverrides, setManualOverrides] = useState<Record<string, string>>({});

  const tasks = useMemo(() => {
    if (!selectedClient) return [];
    const baseTasks = generateTasksForClient(selectedClient);
    return baseTasks.map(t => ({
      ...t,
      notes: manualOverrides[t.id] || t.notes
    }));
  }, [selectedClient, manualOverrides]);

  const daily = tasks.filter(t => t.frequency === 'daily');
  const weekly = tasks.filter(t => t.frequency === 'weekly');
  const event = tasks.filter(t => t.frequency === 'event');

  const exportText = useMemo(
    () => (selectedClient ? formatForExport(selectedClient, tasks) : ''),
    [selectedClient, tasks]
  );

  const handleCopy = async () => {
    if (!exportText) return;
    await navigator.clipboard.writeText(exportText);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDocxExport = async () => {
    if (!selectedClient || tasks.length === 0) return;
    try {
      await generateBeautifulDocx(selectedClient, tasks);
    } catch (e) {
      console.error('DOCX Export Failed:', e);
      alert('Failed to generate Word document. Falling back to text download.');
      handleDownloadTxt();
    }
  };

  const handleDownloadTxt = () => {
    if (!exportText || !selectedClient) return;
    const blob = new Blob([exportText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nourish-task-pack-${selectedClient.name.replace(/\s+/g, '-').toLowerCase()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleTaskUpdate = (id: string, notes: string) => {
    setManualOverrides(prev => ({ ...prev, [id]: notes }));
  };

  const handleVaultUpload = async (file: File) => {
    if (!selectedClient) return;
    setImportLoading(true);
    setImportInfo(`Absorbing ${file.name}...`);
    try {
      const text = await extractFileText(file);
      const clientsList = loadClients();
      const profile = clientsList.find(c => c.id === selectedId);
      if (!profile) return;
      
      const newDoc: VaultDoc = {
        id: `vault-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        name: file.name,
        text,
        uploadedAt: new Date().toISOString(),
      };
      
      profile.vaultDocs = [...(profile.vaultDocs || []), newDoc];
      saveClient(profile);
      setImportInfo(`Intelligence updated with ${file.name}`);
    } catch (e) {
      setImportInfo(`Import failed: ${e instanceof Error ? e.message : 'Unknown'}`);
    } finally {
      setImportLoading(false);
    }
  };

  const handleRemoveDoc = (docId: string) => {
    if (!selectedClient) return;
    const profile = clients.find(c => c.id === selectedId);
    if (!profile) return;
    profile.vaultDocs = (profile.vaultDocs || []).filter(d => d.id !== docId);
    saveClient(profile);
    setImportInfo('Document removed');
  };

  const runAIRefinement = async () => {
    if (!refineInput.trim() || !selectedClient) return;
    setRefining(true);
    try {
      // Simulate AI interaction by processing the current task list based on input
      // In a real scenario, this would fetch from /api/staff/enhance-task-pack
      const res = await fetch('/api/staff/enhance-note', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          text: formatForExport(selectedClient, tasks),
          noteType: 'Nourish Task Pack',
          clientName: selectedClient.name,
          refineInstructions: `Update this task pack based on: ${refineInput}. Return the full updated pack.`,
          includeEvidenceTrail: false,
        })
      });

      if (res.ok) {
        const data = await res.json();
        // Since the API returns a string, we might need a parser if we want to map back to tasks
        // For now, let's append the AI refinement to the notes of the relevant tasks or update manually
        // Alternatively, show the AI result in a preview for the user to "Apply"
        alert('AI Refinement received! In a full implementation, this would map the updated instructions back to each individual task card.');
      } else {
        throw new Error('AI at capacity');
      }
    } catch (e) {
      alert('Refinement failed. Try a smaller request.');
    } finally {
      setRefining(false);
      setRefineInput('');
    }
  };

  const clientsWithPlans = clients.filter(c => clientHasTaskSources(c));
  const clientsNoPlan = clients.filter(c => !clientHasTaskSources(c));

  return (
    <div className="flex h-full min-h-screen">

      {/* ── LEFT: Client picker ── */}
      <aside className="w-72 shrink-0 border-r border-hc-border/10 p-4 space-y-6 overflow-y-auto bg-hc-surface/30">
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <ClipboardList size={16} className="text-hc-teal" />
            <span className="text-[10px] font-black text-hc-teal uppercase tracking-widest">Select Client</span>
          </div>

          <div className="space-y-1">
            {clientsWithPlans.map(c => (
              <button
                key={c.id}
                onClick={() => { setSelectedId(c.id); setManualOverrides({}); }}
                className={`w-full text-left px-4 py-3 rounded-2xl transition-all flex items-center justify-between gap-2 group ${
                  selectedId === c.id
                    ? 'hc-clay-pressed text-hc-teal'
                    : 'text-hc-text/60 hover:text-hc-text hover:hc-clay-raised'
                }`}
              >
                <div className="flex items-center gap-2 min-w-0">
                  <User size={12} className="shrink-0 opacity-60" />
                  <span className="text-[10px] font-black uppercase tracking-wide truncate">{c.name}</span>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Intelligence Vault Section */}
        {selectedClient && (
          <div className="pt-6 border-t border-hc-border/10 space-y-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Paperclip size={14} className="text-hc-teal" />
                <span className="text-[9px] font-black text-hc-teal uppercase tracking-widest">Intelligence Vault</span>
              </div>
              <label className="cursor-pointer p-1.5 rounded-lg hc-clay-raised hover:text-hc-teal transition-colors">
                <RefreshCw size={12} className={importLoading ? 'animate-spin' : ''} />
                <input type="file" className="hidden" onChange={e => e.target.files?.[0] && handleVaultUpload(e.target.files[0])} />
              </label>
            </div>

            <div className="space-y-2">
              {(selectedClient.vaultDocs || []).map(doc => (
                <div key={doc.id} className="flex items-center justify-between gap-2 p-2 rounded-xl bg-hc-surface/50 border border-hc-border/5 group">
                  <div className="flex items-center gap-2 min-w-0">
                    <FileText size={10} className="text-hc-muted shrink-0" />
                    <span className="text-[9px] font-bold text-hc-text truncate">{doc.name}</span>
                  </div>
                  <button onClick={() => handleRemoveDoc(doc.id)} className="opacity-0 group-hover:opacity-100 p-1 text-flag-red hover:bg-flag-red/10 rounded-md transition-all">
                    <X size={10} />
                  </button>
                </div>
              ))}
              {(!selectedClient.vaultDocs || selectedClient.vaultDocs.length === 0) && (
                <div className="text-center py-4 border border-dashed border-hc-border/20 rounded-2xl">
                  <p className="text-[8px] text-hc-muted uppercase tracking-widest">No additional intel</p>
                </div>
              )}
            </div>
            {importInfo && <p className="text-[8px] text-hc-teal italic">{importInfo}</p>}
          </div>
        )}
      </aside>

      {/* ── RIGHT: Task pack ── */}
      <main className="flex-1 overflow-y-auto p-6 pb-32 space-y-6">

        {/* Header */}
        <div className="flex items-start justify-between gap-4">
          <div>
            <h1 
              onClick={(e) => e.detail === 3 && triggerStressTest()}
              className="text-[11px] font-black text-hc-teal uppercase tracking-widest mb-1 cursor-default select-none"
              title="Double-click for info, Triple-click for Stress Test"
            >
              Nourish Task Pack Generator
            </h1>
            <p className="text-[10px] text-hc-muted font-bold">
              {selectedClient
                ? `${tasks.length} tasks derived from ${selectedClient.name}'s care plan + risk assessment`
                : 'Select a client to generate their care/risk aligned task pack'}
            </p>
          </div>

          {tasks.length > 0 && (
            <div className="flex items-center gap-2 shrink-0">
              <button
                onClick={handleDocxExport}
                className="flex items-center gap-2 px-4 py-2.5 bg-hc-teal text-hc-bone rounded-xl text-[10px] font-black hover:bg-hc-teal-dark transition-all uppercase tracking-widest shadow-lg"
              >
                <Download size={13} /> Beautiful Doc (.docx)
              </button>
              <button
                onClick={handleCopy}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  copied
                    ? 'bg-hc-teal/20 text-hc-teal border border-hc-teal/30'
                    : 'hc-clay-raised text-hc-muted hover:text-hc-teal'
                }`}
              >
                {copied ? <Check size={13} /> : <Copy size={13} />}
                {copied ? 'Copied!' : 'Copy All'}
              </button>
            </div>
          )}
        </div>

        {selectedClient && tasks.length > 0 && (
          <>
            {/* Stats bar */}
            <div className="grid grid-cols-4 gap-3">
              {[
                { label: 'Total Tasks', value: tasks.length, color: 'text-hc-text' },
                { label: 'Daily', value: daily.length, color: 'text-hc-teal' },
                { label: 'Weekly', value: weekly.length, color: 'text-flag-amber' },
                { label: 'Event-Driven', value: event.length, color: 'text-flag-red' },
              ].map(s => (
                <div key={s.label} className="hc-clay-raised rounded-2xl p-4 text-center">
                  <div className={`text-2xl font-black tabular-nums ${s.color}`}>{s.value}</div>
                  <div className="text-[8px] font-black text-hc-muted uppercase tracking-widest mt-1">{s.label}</div>
                </div>
              ))}
            </div>

            {/* Task sections */}
            <div className="space-y-6">
              <FreqSection
                label="Daily Tasks"
                tasks={daily}
                freq="daily"
                icon={<Clock size={12} />}
                onTaskUpdate={handleTaskUpdate}
              />
              <FreqSection
                label="Weekly Tasks"
                tasks={weekly}
                freq="weekly"
                icon={<Calendar size={12} />}
                onTaskUpdate={handleTaskUpdate}
              />
              <FreqSection
                label="Event-Driven Tasks"
                tasks={event}
                freq="event"
                icon={<Zap size={12} />}
                onTaskUpdate={handleTaskUpdate}
              />
            </div>
          </>
        )}
      </main>

      {/* AI Refinement Interaction Layer */}
      {selectedClient && tasks.length > 0 && (
        <div className="fixed bottom-6 right-6 left-[20rem] z-50">
          <div className="max-w-4xl mx-auto hc-clay-raised rounded-[2rem] p-3 flex items-center gap-3 border border-hc-teal/20 backdrop-blur-xl bg-hc-surface/80">
            <div className="flex-1 relative">
              <Sparkles size={14} className={`absolute left-4 top-1/2 -translate-y-1/2 text-hc-teal ${refining ? 'animate-spin' : ''}`} />
              <input
                value={refineInput}
                onChange={e => setRefineInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && runAIRefinement()}
                placeholder="Talk to Intelligence... (e.g. 'Make the medication task more detailed' or 'Change breakfast to lunch')"
                className="w-full pl-10 pr-4 py-3 rounded-2xl hc-clay-inset bg-transparent text-[11px] font-bold text-hc-text outline-none placeholder:text-hc-muted/50"
              />
            </div>
            <button
              onClick={runAIRefinement}
              disabled={!refineInput.trim() || refining}
              className="p-3 rounded-2xl bg-hc-teal text-hc-bone hover:scale-105 active:scale-95 transition-all disabled:opacity-40 disabled:grayscale"
            >
              {refining ? <RefreshCw size={16} className="animate-spin" /> : <Send size={16} />}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useRef, useCallback } from 'react';
import { loadClients, saveClient, emptyPBS } from '../lib/client-store';
import { buildPBSHtml } from '../lib/doc-renderer';
import type { ExportLayout } from '../lib/doc-renderer';
import { SignaturePanel, emptySignatories } from '../components/SignaturePad';
import { parseUniversalText } from '../lib/universal-import';
import { getAllEntries } from '../lib/entry-store';
import { extractFileText } from '../lib/universal-extractor';
import { mergeClientIdentity } from '../lib/client-identity-merge';
import { mergePBSData } from '../lib/intel-merge';
import { Sparkles, ChevronRight, ArrowLeft, Plus, Printer, Trash2, CheckCircle } from 'lucide-react';
import type { FullClient } from '../lib/client-store';
import type { Sig } from '../components/SignaturePad';

interface Props {
  clientId: string;
  onBack: () => void;
}

const SECTIONS = [
  'Personal Profile',
  'About Me',
  'Diagnoses & Presentation',
  'Behaviour as Communication',
  'Proactive Support',
  'Early Warning Signs',
  'Reactive Strategies',
  'Post-Incident Support',
  'Preferences & Triggers',
  'Medication Management & Safety Support',
  'Reviews & Professionals',
  'Sign-Off',
];

// ─── SHARED FIELD COMPONENTS ─────────────────────────────────────────────────

function Field({ label, value, onChange, area = false, rows = 3, placeholder = '' }: {
  label: string; value: string; onChange: (v: string) => void;
  area?: boolean; rows?: number; placeholder?: string;
}) {
  const cls = 'w-full hc-clay-inset px-5 py-4 text-[13px] font-black text-hc-text focus:outline-none focus:ring-2 focus:ring-hc-teal/20 placeholder:text-hc-muted/40 shadow-inner transition-all';
  return (
    <div className="mb-6 group animate-in fade-in slide-in-from-left-2 duration-500 text-hc-text">
      <label className="text-[11px] mb-2.5 ml-1 block font-black text-hc-muted tracking-[0.2em] group-focus-within:text-hc-teal transition-colors uppercase">{label}</label>
      {area
        ? <textarea value={value} onChange={e => onChange(e.target.value)} rows={rows} placeholder={placeholder} className={cls + ' resize-y scrollbar-thin italic'} />
        : <input type="text" value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} className={cls} />}
    </div>
  );
}

function ListField({ label, items, onChange, placeholder = 'Enter details…', rows = 1 }: {
  label: string; items: string[]; onChange: (items: string[]) => void;
  placeholder?: string; rows?: number;
}) {
  const update = (i: number, v: string) => { const a = [...items]; a[i] = v; onChange(a); };
  const add = () => onChange([...items, '']);
  const remove = (i: number) => onChange(items.filter((_, idx) => idx !== i));
  return (
    <div className="mb-8 animate-in fade-in slide-in-from-left-2 duration-500 text-hc-text">
      <div className="flex items-center justify-between mb-4 px-1">
        <label className="text-[11px] font-black text-hc-muted tracking-[0.2em] uppercase">{label}</label>
        <button onClick={add} className="text-[11px] font-black text-hc-teal hover:brightness-90 uppercase tracking-widest transition-all">+ Add Protocol</button>
      </div>
      <div className="space-y-3.5">
        {items.map((item, i) => (
          <div key={i} className="flex gap-4 items-start group">
            {rows > 1
              ? <textarea value={item} onChange={e => update(i, e.target.value)} rows={rows} placeholder={placeholder}
                  className="flex-1 hc-clay-inset px-5 py-4 text-[13px] font-black text-hc-text focus:outline-none focus:ring-2 focus:ring-hc-teal/20 resize-y placeholder:text-hc-muted/40 shadow-inner transition-all italic" />
              : <input value={item} onChange={e => update(i, e.target.value)} placeholder={placeholder}
                  className="flex-1 hc-clay-inset px-5 py-4 text-[13px] font-black text-hc-text focus:outline-none focus:ring-2 focus:ring-hc-teal/20 shadow-inner transition-all" />}
            <button onClick={() => remove(i)} className="mt-2 w-10 h-10 rounded-xl hc-clay-raised flex items-center justify-center text-hc-muted hover:text-hc-red transition-all">
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        ))}
        {items.length === 0 && (
          <button onClick={add}
            className="w-full hc-clay-raised border-2 border-dashed border-hc-border rounded-[1.5rem] py-10 text-[11px] font-black text-hc-muted hover:text-hc-teal hover:border-hc-teal/30 transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-4">
            <Plus className="w-4 h-4" />
            Initialise Protocol Array
          </button>
        )}
      </div>
    </div>
  );
}

function TableEditor({ label, rows, onChange, cols, addRow }: {
  label: string;
  rows: Record<string, string>[];
  onChange: (rows: Record<string, string>[]) => void;
  cols: { key: string; label: string; area?: boolean }[];
  addRow: () => Record<string, string>;
}) {
  const update = (i: number, key: string, v: string) => {
    const a = [...rows];
    a[i] = { ...a[i], [key]: v };
    onChange(a);
  };
  const add = () => onChange([...rows, addRow()]);
  const remove = (i: number) => onChange(rows.filter((_, idx) => idx !== i));
  return (
    <div className="mb-8 animate-in fade-in slide-in-from-left-2 duration-500">
      <div className="flex items-center justify-between mb-4 px-1">
        <label className="section-header text-[11px] text-hc-muted tracking-[0.2em] uppercase">{label}</label>
        <button onClick={add} className="text-[11px] font-black text-hc-teal hover:text-hc-text uppercase tracking-widest transition-all">+ Add New Row</button>
      </div>
      <div className="space-y-4">
        {rows.map((row, i) => (
          <div key={i} className="hc-clay-raised rounded-[2rem] p-6 relative group transition-all">
            <button onClick={() => remove(i)}
              className="absolute top-4 right-4 w-10 h-10 rounded-xl hc-clay-inset flex items-center justify-center text-hc-muted hover:text-hc-red transition-all opacity-0 group-hover:opacity-100 shadow-xl z-10">
              <Trash2 className="w-4 h-4" />
            </button>
            <div className={`grid gap-6 ${cols.length >= 2 ? 'md:grid-cols-2' : 'grid-cols-1'}`}>
              {cols.map(col => (
                <div key={col.key} className={col.area && cols.length === 1 ? 'w-full' : ''}>
                  <label className="section-header text-[11px] mb-2 ml-1 block text-hc-muted opacity-60 uppercase tracking-[0.2em]">{col.label}</label>
                  {col.area
                    ? <textarea value={row[col.key] || ''} onChange={e => update(i, col.key, e.target.value)}
                        rows={3} className="w-full hc-clay-inset rounded-2xl px-5 py-3 text-[13px] text-hc-text focus:outline-none focus:ring-2 ring-hc-teal/20 shadow-inner resize-none font-black italic" />
                    : <input type="text" value={row[col.key] || ''} onChange={e => update(i, col.key, e.target.value)}
                        className="w-full hc-clay-inset rounded-2xl px-5 py-3 text-[13px] text-hc-text focus:outline-none focus:ring-2 ring-hc-teal/20 shadow-inner font-black" />}
                </div>
              ))}
            </div>
          </div>
        ))}
        {rows.length === 0 && (
          <button onClick={add}
            className="w-full hc-clay-raised border-2 border-dashed border-hc-border rounded-[2rem] py-10 text-[11px] font-black text-hc-muted hover:text-hc-teal transition-all uppercase tracking-[0.3em] flex items-center justify-center gap-3">
            <Plus className="w-5 h-5" />
            Add Details
          </button>
        )}
      </div>
    </div>
  );
}

// ─── MAIN COMPONENT ──────────────────────────────────────────────────────────
export function PBSBuilder({ clientId, onBack }: Props) {
  const [client, setClient] = useState<FullClient>(() => {
    const all = loadClients();
    return all.find(c => c.id === clientId) || all[0];
  });
  const [section, setSection] = useState(0);
  const [saved, setSaved] = useState(true);
  const [exportLayout, setExportLayout] = useState<ExportLayout>('portrait');
  const [importing, setImporting] = useState(false);
  const [importStatus, setImportStatus] = useState('');
  const [sigs, setSigs] = useState<Sig[]>(() =>
    emptySignatories(
      loadClients().find(c => c.id === clientId)?.completedBy || 'Brooklyn Ruvinga',
      loadClients().find(c => c.id === clientId)?.keyWorker || '',
      loadClients().find(c => c.id === clientId)?.responsible || '',
    )
  );
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const importFileRef = useRef<HTMLInputElement>(null);

  const update = useCallback((patch: Partial<FullClient>) => {
    setClient(prev => {
      const next = { ...prev, ...patch };
      saveClient(next);
      setSaved(true);
      return next;
    });
  }, []);

  const updatePBS = useCallback((patch: Partial<NonNullable<FullClient['pbs']>>) => {
    setClient(prev => {
      const today = new Date().toLocaleDateString('en-GB');
      const pbs = { ...(prev.pbs || emptyPBS(today)), ...patch };
      const next = { ...prev, pbs };
      saveClient(next);
      setSaved(true);
      return next;
    });
  }, []);

  const generatePDF = () => {
    const html = buildPBSHtml(client, sigs, exportLayout);
    const doc = iframeRef.current?.contentDocument;
    if (!doc) return;
    doc.open(); doc.write(html); doc.close();
    setTimeout(() => iframeRef.current?.contentWindow?.print(), 400);
  };

  const today = new Date().toLocaleDateString('en-GB');
  const pbs = client.pbs || emptyPBS(today);

  const [synthStatus, setSynthStatus] = useState('');

  const handleSynthesisePBS = () => {
    const all = getAllEntries();
    const clientEntries = all.filter(e =>
      e.client && client.name && e.client.toLowerCase().includes(client.name.split(' ')[0].toLowerCase())
    );
    if (!clientEntries.length) {
      setSynthStatus('No diary entries found for this client. Import a diary CSV first.');
      return;
    }

    setClient(prev => {
      const today = new Date().toLocaleDateString('en-GB');
      const nextPbs = { ...(prev.pbs || emptyPBS(today)) };

      // About text — only if blank
      if (!nextPbs.aboutText) {
        const positiveEntries = clientEntries.filter(e =>
          /enjoyed|happy|smile|laugh|participat|engaged|independ|achieved|positive/.test((e.entry || '').toLowerCase())
        );
        if (positiveEntries.length) {
          nextPbs.aboutText = positiveEntries.slice(0, 2).map(e => e.entry).join(' ');
        }
      }

      // Finds difficult — from incident/challenging entries
      const challengingEntries = clientEntries.filter(e =>
        /refus|agitat|distress|upset|shout|aggress|challeng|difficult|anxious|meltdown/.test((e.entry || '').toLowerCase())
      );
      if (challengingEntries.length) {
        const existing = new Set(nextPbs.findsDifficult.filter(Boolean).map(s => s.toLowerCase()));
        const themes = ['transitions and unexpected changes', 'sensory overload', 'unmet communication needs',
          'crowded environments', 'changes to routine', 'waiting and uncertainty'];
        challengingEntries.forEach(e => {
          const text = e.entry.toLowerCase();
          if (text.includes('wait') && !existing.has('waiting and uncertainty')) { existing.add('waiting and uncertainty'); themes.push('waiting and uncertainty'); }
          if ((text.includes('noise') || text.includes('crowd')) && !existing.has('crowded environments')) existing.add('crowded environments');
          if ((text.includes('routine') || text.includes('change')) && !existing.has('changes to routine')) existing.add('changes to routine');
        });
        const newDifficult = Array.from(existing).filter(t => !nextPbs.findsDifficult.map(s => s.toLowerCase()).includes(t));
        nextPbs.findsDifficult = [...nextPbs.findsDifficult.filter(Boolean), ...newDifficult].slice(0, 7);
      }

      // Warning signs — from entries where escalation occurred
      const incidentEntries = clientEntries.filter(e =>
        (e.type === 'incident' || /incident|escalat|emergency|urgent/.test((e.entry || '').toLowerCase()))
      );
      if (incidentEntries.length && nextPbs.warningSignRows.every(r => !r.sign)) {
        const newWarnings = [
          { sign: 'Increased pacing or restlessness', staffAction: 'Offer a quiet space and calm 1:1 interaction.' },
          { sign: 'Refusing to engage with normal routines', staffAction: 'Do not press. Offer alternatives and allow space.' },
          { sign: 'Raised vocal tone or repetitive speech', staffAction: 'Lower own voice, reduce environmental stimulation.' },
        ];
        nextPbs.warningSignRows = newWarnings;
      }

      // What works — from positive entries
      const positiveEntries = clientEntries.filter(e =>
        /calm|settled|enjoy|happy|participat|help|support|positive|liked|prefer/.test((e.entry || '').toLowerCase())
      );
      if (positiveEntries.length && nextPbs.whatWorks.every(s => !s)) {
        nextPbs.whatWorks = [
          'Consistent 1:1 support from familiar staff',
          'Person-centred communication at their pace',
          'Clear explanations of what is happening and why',
          'Choices offered before transitions',
        ];
      }

      const next = { ...prev, pbs: nextPbs };
      saveClient(next);
      setSynthStatus(`Synthesised from ${clientEntries.length} entries (${challengingEntries.length} challenging, ${incidentEntries.length} incidents). Review each section.`);
      return next;
    });
  };

  const importDataset = async (file: File) => {
    setImporting(true);
    setImportStatus('Reading dataset...');
    try {
      const rawText = await extractFileText(file);
      const parsed = parseUniversalText(rawText);
      const sourceRisk = parsed.client.risk;
      const sourceCarePlan = parsed.carePlan;

      setClient(prev => {
        const nextPbs = mergePBSData(prev.pbs, parsed.pbs || null) || { ...(prev.pbs || emptyPBS(today)) };

        if (sourceCarePlan?.biography && !nextPbs.aboutText) nextPbs.aboutText = sourceCarePlan.biography;
        if (sourceRisk?.risks?.length) {
          const titles = sourceRisk.risks.map((r) => r.title).filter(Boolean);
          if (titles.length) nextPbs.findsDifficult = Array.from(new Set([...(nextPbs.findsDifficult || []), ...titles])).slice(0, 7);
          const warnings = sourceRisk.risks.flatMap((r) => r.earlyWarnings || []).filter(Boolean).slice(0, 8);
          if (warnings.length) {
            const newRows = warnings.map((w) => ({ sign: w, staffAction: 'Follow de-escalation and escalation procedure.' }));
            const existingSigns = new Set(nextPbs.warningSignRows.map(r => r.sign.toLowerCase().trim()));
            for (const row of newRows) {
              if (!existingSigns.has(row.sign.toLowerCase().trim())) {
                nextPbs.warningSignRows.push(row);
              }
            }
          }
        }

        const base = mergeClientIdentity(prev, parsed.client);
        const next: FullClient = { ...base, pbs: nextPbs };
        saveClient(next);
        return next;
      });
      setImportStatus('Dataset imported and merged into PBS draft. Review each section before print.');
    } catch (err: any) {
      setImportStatus(`Import failed: ${err?.message || 'unknown error'}`);
    } finally {
      setImporting(false);
      if (importFileRef.current) importFileRef.current.value = '';
    }
  };

  const sectionComplete = (i: number) => {
    if (i === 0) return !!(client.name && client.dob);
    if (i === 1) return !!(pbs.aboutText);
    if (i === 2) return pbs.diagnosisRows.some(r => r.diagnosis);
    if (i === 3) return pbs.functionRows.some(r => r.behaviour);
    if (i === 4) return pbs.envStrategies.some(Boolean);
    if (i === 5) return pbs.warningSignRows.some(r => r.sign);
    if (i === 6) return !!(pbs.reactiveStep1);
    if (i === 7) return pbs.postImmediate.some(Boolean);
    if (i === 8) return pbs.whatWorks.some(Boolean);
    if (i === 9) return pbs.medicationRows?.some(r => r.name);
    if (i === 10) return !!(pbs.reviewSchedule);
    if (i === 11) return sigs.some(s => s.data);
    return false;
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-hc-bg animate-in fade-in duration-700">
      {/* Header */}
      <div className="flex items-center gap-6 px-8 py-5 hc-clay-raised m-4 z-20 shadow-2xl">
        <button onClick={onBack}
          className="group flex items-center gap-3 text-hc-muted hover:text-hc-text text-[11px] font-black uppercase tracking-[0.2em] transition-all duration-500 active:scale-90">
          <span className="w-10 h-10 rounded-xl hc-clay-inset flex items-center justify-center group-hover:bg-hc-clay-dark transition-all">
            <ArrowLeft className="w-5 h-5 group-hover:-translate-x-0.5 transition-transform" />
          </span>
          Back
        </button>
        
        <div className="h-8 w-px bg-hc-border hidden md:block" />
        
        <div className="flex-1 min-w-0">
          <h1 className="text-xl font-black text-hc-text tracking-tighter uppercase flex items-center gap-3">
            <span>{client.name || 'PERSON PROFILE'}</span>
            <span className="pill pill-teal text-[11px] font-black tracking-widest px-3 py-0.5 shadow-lg">PBS PLAN BUILDER</span>
          </h1>
          <div className="flex items-center gap-3 mt-1">
            <span className="text-[11px] font-bold text-hc-muted uppercase tracking-widest">Positive Behaviour Support Planning</span>
            <span className={`text-[11px] font-black uppercase tracking-widest tabular-nums ${saved ? 'text-flag-green' : 'text-flag-amber animate-pulse'}`}>
              {saved ? '✓ DATA SAVED' : '● SAVING CHANGES...'}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={handleSynthesisePBS}
            className="px-5 py-2.5 rounded-xl hc-clay-raised text-[11px] font-black uppercase tracking-[0.2em] text-hc-teal hover:text-hc-text hover:bg-hc-clay-dark flex items-center gap-2 transition-all shadow-md">
            <Sparkles className="w-4 h-4" /> Synthesise from Intelligence
          </button>
          <button
            onClick={() => importFileRef.current?.click()}
            disabled={importing}
            className="px-5 py-2.5 rounded-xl hc-clay-raised text-[11px] font-black uppercase tracking-[0.2em] text-hc-teal hover:bg-hc-clay-dark hover:text-hc-text transition-colors disabled:opacity-50"
          >
            {importing ? 'Importing...' : 'Import dataset'}
          </button>
          <input
            ref={importFileRef}
            type="file"
            accept=".pdf,.txt,.csv,.md"
            className="hidden"
            onChange={(e) => {
              const f = e.target.files?.[0];
              if (f) importDataset(f);
            }}
          />
          <div className="relative group">
            <select
              value={exportLayout}
              onChange={e => setExportLayout(e.target.value as ExportLayout)}
              className="appearance-none bg-hc-bone hc-clay-inset border border-hc-border hover:border-hc-teal/50 rounded-xl pl-4 pr-10 py-2.5 text-[11px] font-black uppercase tracking-[0.2em] text-hc-text outline-none cursor-pointer transition-colors shadow-inner"
              title="Export page orientation"
            >
              <option value="portrait">Portrait</option>
              <option value="landscape">Landscape</option>
            </select>
            <ChevronRight className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-hc-muted pointer-events-none rotate-90" />
          </div>
          <button onClick={generatePDF}
            className="flex items-center gap-3 px-8 py-3 btn-tactical text-[11px] font-black uppercase tracking-[0.2em] rounded-2xl shadow-xl hover:scale-105 active:scale-95 transition-all group">
            <Printer className="w-5 h-5 group-hover:scale-110 transition-transform" />
            Print PBS Plan
          </button>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden px-4 pb-4 gap-4">
        {/* Section nav */}
        <div className="w-72 flex-shrink-0 hc-clay-inset overflow-y-auto scrollbar-thin">
          <div className="p-6 border-b border-hc-border bg-hc-clay-dark/20">
            <p className="section-header text-[11px] text-hc-muted tracking-[0.3em] uppercase">Plan Sections</p>
          </div>
          <div className="py-4">
            {SECTIONS.map((name, i) => (
              <button key={i} onClick={() => setSection(i)}
                className={`w-full text-left px-6 py-4 text-[11px] font-black uppercase tracking-widest flex items-center gap-4 transition-all duration-500 group relative overflow-hidden active:scale-95
                  ${section === i ? 'bg-hc-teal/10 text-hc-teal shadow-inner' : 'text-hc-muted hover:text-hc-text hover:bg-hc-clay-dark'}`}>
                {section === i && <div className="absolute left-0 top-0 bottom-0 w-1 bg-hc-teal shadow-[0_0_15px_#1c4e4e] z-10" />}
                <div className={`w-2.5 h-2.5 rounded-full flex-shrink-0 transition-all duration-700 relative z-10 ${sectionComplete(i) ? 'bg-hc-teal scale-110' : 'bg-hc-border group-hover:bg-hc-muted'}`} />
                <span className="flex-1 truncate relative z-10 group-hover:translate-x-1 transition-transform duration-500">{name}</span>
                {sectionComplete(i) && (
                  <CheckCircle className="w-3.5 h-3.5 text-hc-teal/60 relative z-10" />
                )}
              </button>
            ))}
          </div>
        </div>

        {/* Section content */}
        <div className="flex-1 overflow-y-auto p-10 hc-clay-raised scrollbar-thin">
          <div className="max-w-3xl mx-auto animate-in slide-in-from-bottom-4 duration-700">
            {!!synthStatus && (
              <div className="mb-4 text-[11px] font-black rounded-xl px-4 py-3 border border-hc-teal/30 bg-hc-teal/10 text-hc-teal flex items-center gap-2 animate-in slide-in-from-top-2">
                <Sparkles className="w-3.5 h-3.5 shrink-0" />{synthStatus}
              </div>
            )}
            {!!importStatus && (
              <div className="mb-6 text-[11px] font-black rounded-xl px-4 py-3 border border-hc-teal/30 bg-hc-teal/10 text-hc-teal">
                {importStatus}
              </div>
            )}
            
            <div className="mb-12 flex items-center gap-6">
              <div className="w-20 h-20 rounded-3xl hc-clay-inset flex items-center justify-center text-3xl font-black text-hc-teal shadow-2xl animate-float">
                {section + 1}
              </div>
              <div>
                <h2 className="text-3xl font-black text-hc-text tracking-tighter uppercase mb-1">{SECTIONS[section]}</h2>
                <div className="flex items-center gap-2">
                  <div className="w-1 h-1 rounded-full bg-hc-teal animate-pulse" />
                  <p className="text-[11px] font-black text-hc-muted uppercase tracking-[0.3em]">Configuring Section {section + 1} of 12</p>
                </div>
              </div>
            </div>

            <div className="space-y-2">
              {/* 0 — Personal Profile */}
              {section === 0 && (
                <div className="animate-in fade-in duration-700">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8">
                    <Field label="Full Name" value={client.name} onChange={v => update({ name: v })} />
                    <Field label="Preferred Name" value={client.preferredName} onChange={v => update({ preferredName: v })} />
                    <Field label="Date of Birth" value={client.dob} onChange={v => update({ dob: v })} />
                    <Field label="NHS Number" value={client.nhs} onChange={v => update({ nhs: v })} />
                    <Field label="Phone Number" value={client.phone} onChange={v => update({ phone: v })} />
                    <Field label="Admission Date" value={client.dateOfAdmission} onChange={v => update({ dateOfAdmission: v })} />
                    <Field label="Review Date" value={client.reviewDate} onChange={v => update({ reviewDate: v })} />
                  </div>
                  <Field label="Primary Address" value={client.address} onChange={v => update({ address: v })} area rows={2} />
                  <ListField label="Diagnoses" items={client.diagnoses} onChange={v => update({ diagnoses: v })} placeholder="e.g. Autism Spectrum Disorder" />
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 mt-8 pt-8 border-t border-hc-border">
                    <Field label="Key Worker" value={client.keyWorker} onChange={v => update({ keyWorker: v })} />
                    <Field label="Responsible Manager" value={client.responsible} onChange={v => update({ responsible: v })} />
                    <Field label="Completed By" value={client.completedBy} onChange={v => update({ completedBy: v })} />
                    <Field label="Plan Date" value={pbs.planDate} onChange={v => updatePBS({ planDate: v })} />
                  </div>
                </div>
              )}

              {/* 1 — About Me */}
              {section === 1 && (
                <div className="animate-in fade-in duration-700">
                  <Field label="About the Person (Summary)" value={pbs.aboutText}
                    onChange={v => updatePBS({ aboutText: v })} area rows={8}
                    placeholder="Summarise the person's core strengths, personality, interests, and how they like to be supported..." />
                  <div className="h-8" />
                  <ListField label="Important to Me" items={pbs.whatMatters}
                    onChange={v => updatePBS({ whatMatters: v })} placeholder="e.g. Spending time in my private space" />
                  <ListField label="How I Communicate Best" items={pbs.communicatesBest}
                    onChange={v => updatePBS({ communicatesBest: v })} placeholder="e.g. Short, clear sentences and visual aids" />
                  <ListField label="What I Find Difficult" items={pbs.findsDifficult}
                    onChange={v => updatePBS({ findsDifficult: v })} placeholder="e.g. Sudden changes to my Life Skills & Daily Routine" />
                </div>
              )}

              {/* 2 — Diagnoses */}
              {section === 2 && (
                <div className="animate-in fade-in duration-700">
                  <p className="text-[13px] font-black text-hc-muted mb-8 leading-relaxed italic border-l-2 border-hc-teal pl-4 py-1">"Describe how each diagnosis affects the person's daily life and support needs."</p>
                  <TableEditor
                    label="Diagnoses & Presentation Table"
                    rows={pbs.diagnosisRows as unknown as Record<string, string>[]}
                    onChange={v => updatePBS({ diagnosisRows: v as unknown as typeof pbs.diagnosisRows })}
                    cols={[
                      { key: 'diagnosis', label: 'Diagnosis' },
                      { key: 'presentation', label: 'How it affects me', area: true },
                    ]}
                    addRow={() => ({ diagnosis: '', presentation: '' })}
                  />
                  <Field label="Key Support Principle" value={pbs.keyPrinciple}
                    onChange={v => updatePBS({ keyPrinciple: v })} area rows={4} placeholder="What is the single most important thing staff should remember when supporting this person?" />
                </div>
              )}

              {/* 3 — Function */}
              {section === 3 && (
                <div className="animate-in fade-in duration-700">
                  <p className="text-[13px] font-black text-hc-muted mb-8 leading-relaxed italic border-l-2 border-hc-teal pl-4 py-1">"Describe specific behaviours and what the person might be trying to communicate through them."</p>
                  <TableEditor
                    label="Behaviour as Communication Analysis"
                    rows={pbs.functionRows as unknown as Record<string, string>[]}
                    onChange={v => updatePBS({ functionRows: v as unknown as typeof pbs.functionRows })}
                    cols={[
                      { key: 'behaviour', label: 'The Behaviour' },
                      { key: 'func', label: 'What they are communicating', area: true },
                    ]}
                    addRow={() => ({ behaviour: '', func: '' })}
                  />
                </div>
              )}

              {/* 4 — Proactive Support */}
              {section === 4 && (
                <div className="animate-in fade-in duration-700 space-y-4">
                  <ListField label="Adaptive Living Environment & Surroundings" items={pbs.envStrategies}
                    onChange={v => updatePBS({ envStrategies: v })} />
                  <ListField label="Structure & Life Skills & Daily Routine" items={pbs.routineStrategies}
                    onChange={v => updatePBS({ routineStrategies: v })} />
                  <ListField label="Relationships & Interaction" items={pbs.relationshipStrategies}
                    onChange={v => updatePBS({ relationshipStrategies: v })} />
                  <ListField label="Communication Strategies" items={pbs.communicationStrategies}
                    onChange={v => updatePBS({ communicationStrategies: v })} />
                  <ListField label="Digital & Online Safety (Optional)" items={pbs.onlineSafetyStrategies || []}
                    onChange={v => updatePBS({ onlineSafetyStrategies: v })} />
                </div>
              )}

              {/* 5 — Early Warning Signs */}
              {section === 5 && (
                <div className="animate-in fade-in duration-700">
                  <p className="text-[13px] font-black text-hc-muted mb-8 leading-relaxed italic border-l-2 border-hc-teal pl-4 py-1">"Identify signs that the person is beginning to feel distressed and how staff should respond immediately."</p>
                  <TableEditor
                    label="Early Warning Signs & Actions"
                    rows={pbs.warningSignRows as unknown as Record<string, string>[]}
                    onChange={v => updatePBS({ warningSignRows: v as unknown as typeof pbs.warningSignRows })}
                    cols={[
                      { key: 'sign', label: 'The Sign/Behaviour', area: true },
                      { key: 'staffAction', label: 'How staff should respond', area: true },
                    ]}
                    addRow={() => ({ sign: '', staffAction: '' })}
                  />
                </div>
              )}

              {/* 6 — Reactive Strategies */}
              {section === 6 && (
                <div className="animate-in fade-in duration-700">
                  <p className="text-[13px] font-black text-hc-muted mb-8 leading-relaxed italic border-l-2 border-hc-red pl-4 py-1">"Step-by-step de-escalation strategies to follow when behaviour has intensified."</p>
                  <div className="space-y-2">
                    {[
                      ['Step 1 — Low Arousal Response (Voice/Body)', pbs.reactiveStep1, (v: string) => updatePBS({ reactiveStep1: v })],
                      ['Step 2 — Giving Space', pbs.reactiveStep2, (v: string) => updatePBS({ reactiveStep2: v })],
                      ['Step 3 — Reducing Demands', pbs.reactiveStep3, (v: string) => updatePBS({ reactiveStep3: v })],
                      ['Step 4 — Redirection (Suggested phrases)', pbs.reactiveStep4, (v: string) => updatePBS({ reactiveStep4: v })],
                      ['Step 5 — Validation & Reassurance', pbs.reactiveStep5, (v: string) => updatePBS({ reactiveStep5: v })],
                      ['Step 6 — Managing Conflict', pbs.reactiveStep6, (v: string) => updatePBS({ reactiveStep6: v })],
                      ['Step 7 — Emergency Response (if required)', pbs.reactiveStep7, (v: string) => updatePBS({ reactiveStep7: v })],
                    ].map(([label, value, onChange], i) => (
                      <Field key={i} label={label as string} value={value as string} onChange={onChange as (v: string) => void} area rows={2} />
                    ))}
                  </div>
                  <div className="mt-8">
                    <Field label="Calming Strategies (Optional)" value={pbs.walksNote}
                      onChange={v => updatePBS({ walksNote: v })} area rows={3} placeholder="Describe specific calming activities or routines..." />
                  </div>
                </div>
              )}

              {/* 7 — Post-Incident Support */}
              {section === 7 && (
                <div className="animate-in fade-in duration-700 space-y-6">
                  <ListField label="Immediate Support for the Person" items={pbs.postImmediate}
                    onChange={v => updatePBS({ postImmediate: v })} rows={2} />
                  <ListField label="Debriefing & Support for Staff" items={pbs.postDebrief}
                    onChange={v => updatePBS({ postDebrief: v })} rows={2} />
                  <ListField label="Required Documentation & Reporting" items={pbs.staffResponsibilities}
                    onChange={v => updatePBS({ staffResponsibilities: v })} />
                </div>
              )}

              {/* 8 — What Works */}
              {section === 8 && (
                <div className="animate-in fade-in duration-700 grid grid-cols-1 md:grid-cols-2 gap-8">
                  <ListField label="✓ What Works Best" items={pbs.whatWorks}
                    onChange={v => updatePBS({ whatWorks: v })} placeholder="e.g. Using a calm and quiet voice" />
                  <ListField label="✗ What to Avoid" items={pbs.doesntWork}
                    onChange={v => updatePBS({ doesntWork: v })} placeholder="e.g. Raising your voice or making sudden moves" />
                </div>
              )}

              {/* 9 — Medication Management & Safety */}
              {section === 9 && (
                <div className="animate-in fade-in duration-700">
                  <TableEditor
                    label="Medication Management & Safety Record"
                    rows={pbs.medicationRows as unknown as Record<string, string>[]}
                    onChange={v => updatePBS({ medicationRows: v as unknown as typeof pbs.medicationRows })}
                    cols={[
                      { key: 'name', label: 'Medication Name' },
                      { key: 'dose', label: 'Dosage' },
                      { key: 'when', label: 'When to take' },
                      { key: 'purpose', label: 'Purpose' },
                      { key: 'notes', label: 'Additional Notes' },
                    ]}
                    addRow={() => ({ name: '', dose: '', when: 'AM', purpose: '', notes: '' })}
                  />
                  <div className="mt-8">
                    <Field label="Administration & Preference Notes"
                      value={pbs.medicationNote} onChange={v => updatePBS({ medicationNote: v })} area rows={5}
                      placeholder="Refusal protocols, side-effect monitoring, and specific preferences for taking Medication Management & Safety..." />
                  </div>
                </div>
              )}

              {/* 10 — Multi-Agency & Review */}
              {section === 10 && (
                <div className="animate-in fade-in duration-700">
                  <TableEditor
                    label="Involved Professionals & Agencies"
                    rows={pbs.agencyRows as unknown as Record<string, string>[]}
                    onChange={v => updatePBS({ agencyRows: v as unknown as typeof pbs.agencyRows })}
                    cols={[
                      { key: 'service', label: 'Service / Agency' },
                      { key: 'role', label: 'Role' },
                      { key: 'status', label: 'Status' },
                    ]}
                    addRow={() => ({ service: '', role: '', status: 'ACTIVE' })}
                  />
                  <div className="h-8" />
                  <Field label="Review Schedule" value={pbs.reviewSchedule}
                    onChange={v => updatePBS({ reviewSchedule: v })} area rows={3} />
                  <Field label="Person's Involvement" value={pbs.serviceUserInvolvement}
                    onChange={v => updatePBS({ serviceUserInvolvement: v })} area rows={2} />
                </div>
              )}

              {/* 11 — Signatures */}
              {section === 11 && (
                <div className="animate-in zoom-in-95 duration-700">
                  <SignaturePanel sigs={sigs} onChange={setSigs} />
                </div>
              )}
            </div>

            {/* Navigation */}
            <div className="flex justify-between mt-16 pt-8 border-t border-hc-border relative z-10">
              {section > 0
                ? <button onClick={() => setSection(s => s - 1)}
                    className="flex items-center gap-3 px-8 py-4 hc-clay-raised text-[11px] font-black uppercase tracking-[0.2em] text-hc-muted hover:text-hc-text transition-all duration-500 hover:bg-hc-clay-dark active:scale-90 shadow-xl">
                    <ArrowLeft className="w-4 h-4" />
                    Previous Section
                  </button>
                : <div />}
              {section < SECTIONS.length - 1
                ? <button onClick={() => setSection(s => s + 1)}
                    className="flex items-center gap-3 px-10 py-4 btn-tactical text-[11px] font-black uppercase tracking-[0.2em] rounded-2xl shadow-2xl hover:scale-105 active:scale-95 transition-all">
                    Next Section
                    <ChevronRight className="w-4 h-4" />
                  </button>
                : <button onClick={generatePDF}
                    className="flex items-center gap-3 px-10 py-4 btn-tactical text-[11px] font-black uppercase tracking-[0.2em] rounded-2xl shadow-2xl hover:scale-105 active:scale-95 transition-all group/btn">
                    <Printer className="w-5 h-5 group-hover/btn:scale-110 transition-transform" />
                    Print PBS Plan
                  </button>}
            </div>
          </div>
        </div>
      </div>

      <iframe ref={iframeRef} style={{ display: 'none' }} title="pbs-print" />
    </div>
  );
}

