// Utility badge removed in favor of high-fidelity clay pills in render loop

export function StaffPage({ staff, onUpdate }: Props) {
  const [search, setSearch] = useState('');
  const [houseFilter, setHouseFilter] = useState('all');
  const [editMember, setEditMember] = useState<StaffMember | null>(null);
  const [docDrawerMember, setDocDrawerMember] = useState<StaffMember | null>(null);
  const [integrityScores, setIntegrityScores] = useState<Record<string, number>>({});

  // Background Intelligence: Pull scores from the 13k database
  useEffect(() => {
    void getAllEntriesAsync().then(all => {
      if (all.length === 0) return;
      const summary: any = {
        totalEntries: all.length,
        dateFrom: '', dateTo: '', allFlags: [], entryTypes: {}, housePerformance: {},
        houses: {} as any
      };
      // Build a house-grouped summary for the scoring engine
      all.forEach(e => {
        const h = e.house || 'UNASSIGNED';
        if (!summary.houses[h]) summary.houses[h] = { name: h, entries: [] };
        summary.houses[h].entries.push(e);
      });

      const analytics = computeStaffMonitoring(summary, { house: 'all', dateFrom: '', dateTo: '' });
      const scoreMap: Record<string, number> = {};
      analytics.staff.forEach(s => { scoreMap[s.carer] = s.qualityScore; });
      setIntegrityScores(scoreMap);

      // Auto-Discovery: If we find staff in the notes who aren't in the ledger, we should eventually suggest enrolling them
    });
  }, []);

  const houses = [...new Set(staff.map(s => s.house))].sort();
  if (houses.length === 0) houses.push(...HAZELCARE_HOUSES);

  const filtered = staff.filter(s => {
    if (houseFilter !== 'all' && s.house !== houseFilter) return false;
    if (search && !s.name.toLowerCase().includes(search.toLowerCase()) && !s.role.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  function saveMember(s: StaffMember) {
    const updated = staff.find(x => x.id === s.id)
      ? staff.map(x => x.id === s.id ? s : x)
      : [...staff, s];
    onUpdate(updated);
    setEditMember(null);
  }

  const totalActive = staff.filter(s => s.status === 'active').length;
  const totalSickness = staff.filter(s => s.status === 'sickness').length;
  const totalSicknessEvents = staff.reduce((sum, s) => sum + s.sicknessThisMonth, 0);
  const totalLatenessEvents = staff.reduce((sum, s) => sum + s.latenessThisMonth, 0);

  // Group by house
  const byHouse: Record<string, StaffMember[]> = {};
  for (const s of filtered) {
    (byHouse[s.house] ??= []).push(s);
  }

  return (
    <div className="p-10 flex flex-col gap-12 bg-hc-bg">
      <div className="flex flex-col md:flex-row items-center justify-between gap-8 pb-10 border-b border-hc-border">
        <div>
          <div className="flex items-center gap-4 mb-2">
             <div className="w-10 h-10 rounded-2xl hc-clay-raised flex items-center justify-center">
                <Users size={20} className="text-hc-teal" />
             </div>
             <h1 className="text-3xl font-black text-hc-text tracking-tighter uppercase">Personnel Ledger</h1>
          </div>
          <p className="text-[11px] font-bold text-hc-muted uppercase tracking-[0.4em] ml-14">Organisational Asset Oversight & Stability Matrix</p>
        </div>
        <button onClick={() => setEditMember(emptyStaff())} className="btn-clay btn-clay-teal h-[64px] px-10">
           <Plus size={16} /> Enroll New Unit
        </button>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-8">
        {[
          { label: 'Active_Personnel', value: totalActive, colorClass: 'text-hc-teal' },
          { label: 'Off_Sick', value: totalSickness, colorClass: 'text-hc-red' },
          { label: 'Sickness_Load', value: totalSicknessEvents, colorClass: 'text-hc-amber' },
          { label: 'Latency_Events', value: totalLatenessEvents, colorClass: 'text-hc-muted' },
        ].map(kpi => (
          <div key={kpi.label} className="hc-clay-raised p-8 flex flex-col gap-4">
             <div className="text-[11px] font-black text-hc-muted uppercase tracking-[0.3em]">{kpi.label}</div>
             <div className={`text-4xl font-black tabular-nums transition-all ${kpi.colorClass}`}>{kpi.value}</div>
          </div>
        ))}
      </div>

      <div className="hc-clay-raised p-6 flex flex-col md:flex-row gap-6 items-center">
        <div className="relative group flex-1">
           <Search className="w-5 h-5 text-hc-muted absolute left-4 top-1/2 -translate-y-1/2 group-focus-within:text-hc-teal transition-colors" />
           <input value={search} onChange={e => setSearch(e.target.value)} placeholder="QUERY PERSONNEL DATABASE..." 
              className="hc-clay-inset w-full pl-12 pr-6 py-4 text-sm font-bold text-hc-text outline-none focus:ring-2 focus:ring-hc-teal/20" />
        </div>
        <div className="flex items-center gap-4">
           <span className="text-[11px] font-black text-hc-muted uppercase tracking-[0.3em]">Sector_Lock:</span>
           <select value={houseFilter} onChange={e => setHouseFilter(e.target.value)} className="hc-clay-inset px-6 py-4 text-[11px] font-black uppercase tracking-widest text-hc-text min-w-[200px]">
              <option value="all">ALL SECTORS</option>
              {houses.map(h => <option key={h} value={h}>{h}</option>)}
           </select>
        </div>
      </div>

      <div className="space-y-16">
        {Object.entries(byHouse).sort(([a], [b]) => a.localeCompare(b)).map(([house, members]) => (
          <div key={house} className="flex flex-col gap-8">
             <div className="flex items-center gap-6 p-4">
                <h2 className="text-2xl font-black text-hc-text tracking-tighter uppercase">{house} COMMAND</h2>
                <div className="hc-clay-pill px-4 py-1.5 hc-clay-raised text-[11px] font-black text-hc-teal uppercase">{members.length} UNITS</div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-10">
                {members.map((member) => (
                   <div key={member.id} className="hc-clay-raised p-8 flex flex-col gap-8 group/card transition-all hover:translate-y-[-6px]">
                      <div className="flex items-center justify-between">
                         <div className="w-14 h-14 rounded-2xl hc-clay-inset flex items-center justify-center text-xl font-black text-hc-teal">
                            {member.name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase()}
                         </div>
                         <div className={`px-4 py-1.5 hc-clay-raised text-[11px] font-black uppercase tracking-widest ${member.status === 'active' ? 'text-hc-teal' : 'text-hc-red'}`}>
                            {member.status}
                         </div>
                      </div>

                      {integrityScores[member.name] !== undefined && (
                        <div className={`absolute -top-3 -right-3 h-8 px-4 rounded-full hc-clay-raised flex items-center justify-center text-[10px] font-black uppercase tracking-widest z-10 animate-in zoom-in duration-500 ${integrityScores[member.name] >= 70 ? 'text-flag-green bg-flag-green/10' : 'text-flag-red bg-flag-red/10 glow-red animate-pulse'}`}>
                          {integrityScores[member.name]}% Integrity
                        </div>
                      )}

                      <div>
                         <div className="text-lg font-black text-hc-text tracking-tight mb-1">{member.name}</div>
                         <div className="text-[11px] font-bold text-hc-muted uppercase tracking-[0.2em]">{member.role}</div>
                      </div>

                      <div className="grid grid-cols-3 gap-6">
                         <div className="flex flex-col items-center">
                            <span className={`text-xl font-black tabular-nums transition-all ${member.sicknessThisMonth > 2 ? 'text-hc-red' : 'text-hc-text'}`}>{member.sicknessThisMonth}</span>
                            <span className="text-[11px] font-black text-hc-muted uppercase">SICK</span>
                         </div>
                         <div className="flex flex-col items-center">
                            <span className="text-xl font-black tabular-nums text-hc-text">{member.latenessThisMonth}</span>
                            <span className="text-[11px] font-black text-hc-muted uppercase">LATE</span>
                         </div>
                         <div className="flex flex-col items-center">
                            <span className="text-xl font-black tabular-nums text-hc-teal">{member.nextSupervision ? daysUntil(member.nextSupervision) + 'D' : '—'}</span>
                            <span className="text-[11px] font-black text-hc-muted uppercase">SUP.</span>
                         </div>
                      </div>

                      <div className="flex gap-3 mt-auto pt-4">
                         <button onClick={() => setEditMember(member)} className="btn-clay !px-3 !py-3 !rounded-xl opacity-0 group-hover/card:opacity-100 transition-all"><Edit2 size={14} /></button>
                         <button onClick={() => setDocDrawerMember(member)} className="btn-clay !px-3 !py-3 !rounded-xl opacity-0 group-hover/card:opacity-100 transition-all"><Shield size={14} /></button>
                      </div>
                   </div>
                ))}
             </div>
          </div>
        ))}
      </div>

      {filtered.length === 0 && (
        <div className="hc-clay-inset py-32 text-center">
          <div className="text-5xl mb-6 opacity-20">👥</div>
          <div className="text-lg font-black text-hc-text mb-2 uppercase tracking-tight">Personnel Database Empty</div>
          <div className="text-[11px] text-hc-muted uppercase tracking-[0.4em] font-bold">Clear sector filters or enroll a new unit to activate intelligence.</div>
        </div>
      )}

      {editMember && <StaffModal staff={editMember} onSave={saveMember} onClose={() => setEditMember(null)} />}
      {docDrawerMember && <StaffDocumentDrawer staff={docDrawerMember} onClose={() => setDocDrawerMember(null)} />}
    </div>
  );
}

import { useState, useRef, useMemo, useEffect } from 'react';
import type { WeekSummary, TemplateType } from '../lib/types';
import { TEMPLATES } from '../lib/types';
import { escapeHtml } from '../lib/html-escape';
import { logAuditAction, getLineageForEntries } from '../lib/audit';

/** Escape user-derived strings embedded in report HTML. */
function ex(s: string | undefined | null): string {
  return escapeHtml(s == null ? '' : String(s));
}

interface Props {
  weekData: WeekSummary | null;
}

const TEMPLATE_CONTEXT_KEY = 'hc-template-import-context';

interface TemplateImportContext {
  selectedTemplateIds?: TemplateType[];
  source?: string;
  at?: string;
  monitoringRunId?: string;
  house?: string;
  dateFrom?: string;
  dateTo?: string;
  escalationCount?: number;
  avgHouseQuality?: number;
}

function readTemplateImportContext(): TemplateImportContext | null {
  try {
    const raw = localStorage.getItem(TEMPLATE_CONTEXT_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as TemplateImportContext;
  } catch {
    return null;
  }
}

function loadRecommendedTemplateIds(): TemplateType[] {
  return readTemplateImportContext()?.selectedTemplateIds || [];
}

function monitoringContextBlock(ctx: TemplateImportContext | null): string {
  if (!ctx || ctx.source !== 'staff-monitoring') return '';
  const win =
    ctx.dateFrom && ctx.dateTo ? `${ex(ctx.dateFrom)} — ${ex(ctx.dateTo)}` : 'REGISTRY_FEED';
  const esc =
    ctx.escalationCount != null && ctx.escalationCount > 0
      ? `<div style="margin-top:4px;"><strong>Escalations:</strong> ${ctx.escalationCount}</div>`
      : '';
  const q =
    ctx.avgHouseQuality != null
      ? `<div style="margin-top:2px;"><strong>Quality Index:</strong> ${ctx.avgHouseQuality}/100</div>`
      : '';
  const scope = ctx.house ? ex(ctx.house).toUpperCase() : 'GLOBAL_SCOPE';
  return `
  <div style="background:#f8fafc; border: 1px solid #cbd5e1; padding: 12px 15px; margin-bottom: 20px; font-size: 10px; color: #334155; line-height: 1.4; font-family: 'Consolas', 'Monaco', monospace;">
    <div style="font-weight: 900; text-transform: uppercase; letter-spacing: 0.1em; color: #020617; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; margin-bottom: 8px;">INTELLIGENCE_CONTEXT_SITREP</div>
    <div>WINDOW: ${win}</div>
    <div>SCOPE: ${scope}</div>
    ${esc}
    ${q}
    <div style="margin-top: 6px; color: #94a3b8; font-size: 8px;">SNAPSHOT_AT: ${ex(ctx.at || '')}</div>
  </div>`;
}

const FOOTER_HTML = `
  <div style="margin-top: auto; padding-top: 20px; text-align: center; border-top: 2px solid #0f172a; padding-bottom: 10px;">
    <div style="color: #0f172a; font-size: 10px; font-weight: 900; letter-spacing: 0.3em; text-transform: uppercase;">HAZEL CARE OPERATIONS</div>
    <div style="color: #64748b; font-size: 8px; font-weight: 700; margin-top: 4px; letter-spacing: 0.15em;">CLASSIFIED DIAGNOSTIC RECORD // DO NOT REDISTRIBUTE</div>
  </div>
`;

function renderHeader(title: string, subtitle: string, color: string) {
  const t = ex(title).toUpperCase();
  const s = ex(subtitle).toUpperCase();
  const now = new Date();
  const dateStr = now.toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });
  const timeStr = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
  return `
  <div style="display: flex; align-items: flex-start; justify-content: space-between; border-bottom: 4px solid ${color || '#0f172a'}; padding-bottom: 18px; margin-bottom: 28px;">
    <div style="flex: 1;">
      <h1 style="margin: 0; font-size: 26px; font-weight: 900; color: #0f172a; text-transform: uppercase; letter-spacing: -0.04em; line-height: 1;">${t}</h1>
      <p style="margin: 6px 0 0; font-size: 10px; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.2em;">${s}</p>
      <p style="margin: 10px 0 0; font-size: 9px; font-weight: 600; color: #94a3b8; letter-spacing: 0.1em;">Generated: ${dateStr} at ${timeStr} &nbsp;|&nbsp; CONFIDENTIAL — INTERNAL USE ONLY</p>
    </div>
    <div style="text-align: right; padding-left: 24px; display: flex; flex-direction: column; align-items: flex-end; gap: 4px;">
      <img src="/logo-formal.png" alt="CareOps" style="height: 44px; width: auto; object-fit: contain;" onerror="this.style.display='none'; this.nextElementSibling.style.display='block';" />
      <div style="display:none; font-weight: 900; font-size: 14px; color: #0f172a; letter-spacing: -0.02em;">HAZEL CARE LTD</div>
      <div style="font-size: 8px; font-weight: 700; color: #94a3b8; letter-spacing: 0.25em; text-transform: uppercase;">NC CareOps Operations</div>
    </div>
  </div>`;
}

function generateQualityMeeting(data: WeekSummary, mon: TemplateImportContext | null): string {
  const COLOR = '#0f172a';
  const houses = Object.values(data.houses).sort((a, b) => a.name.localeCompare(b.name));
  let html = renderHeader('Quality & Compliance SITREP', 'Regional Operational Audit Broadcast', COLOR);
  html += monitoringContextBlock(mon);
  html += '<p>Audit of all regional units for clinical compliance and operational safety.</p>';
  html += '<table style="width:100%; border-collapse:collapse; margin-top:15px; font-size:10px;">';
  html += '<tr style="background:#f1f5f9;">' +
    '<th style="border:1px solid #cbd5e1; padding:8px; text-align:left;">OPERATIONAL_UNIT</th>' +
    '<th style="border:1px solid #cbd5e1; padding:8px; text-align:center;">CRITICAL_ALERTS</th>' +
    '<th style="border:1px solid #cbd5e1; padding:8px; text-align:center;">MED_ERRORS</th>' +
    '<th style="border:1px solid #cbd5e1; padding:8px; text-align:center;">INCIDENTS</th>' +
    '</tr>';
  houses.forEach(h => {
    html += `<tr>
      <td style="border:1px solid #cbd5e1; padding:8px; font-weight:700;">${ex(h.name)}</td>
      <td style="border:1px solid #cbd5e1; padding:8px; text-align:center; color:${h.flags.red > 0 ? '#ef4444' : '#64748b'};">${h.flags.red}</td>
      <td style="border:1px solid #cbd5e1; padding:8px; text-align:center;">${h.medication.filter(e => e.severity === 'red').length}</td>
      <td style="border:1px solid #cbd5e1; padding:8px; text-align:center;">${h.incidents.length}</td>
    </tr>`;
  });
  html += '</table>' + FOOTER_HTML;
  return html;
}

function generateMonthlyReview(data: WeekSummary, mon: TemplateImportContext | null): string {
  const COLOR = '#0f172a';
  const houses = Object.values(data.houses).sort((a, b) => a.name.localeCompare(b.name));
  let html = renderHeader('Monthly Unit Review', 'Unit-Level Diagnostic Performance Audit', COLOR);
  html += monitoringContextBlock(mon);
  houses.forEach(h => {
    html += `<div style="margin-top:20px; border:1px solid #e2e8f0; padding:15px; page-break-inside:avoid;">
      <div style="font-weight:900; font-size:12px; border-bottom:2px solid #0f172a; padding-bottom:5px; margin-bottom:10px;">UNIT: ${ex(h.name)}</div>
      <div style="display:grid; grid-template-columns: repeat(3, 1fr); gap:10px; font-size:9px;">
        <div><strong>Log Volume:</strong> ${h.entries.length} points</div>
        <div style="color:${h.flags.red > 0 ? '#ef4444' : 'inherit'};"><strong>Critical Flags:</strong> ${h.flags.red}</div>
        <div><strong>Staff Activity:</strong> ${new Set(h.entries.map(e => e.carer)).size} commanders</div>
      </div>
    </div>`;
  });
  html += FOOTER_HTML;
  return html;
}

function generateServiceSitrep(data: WeekSummary, mon: TemplateImportContext | null): string {
  const COLOR = '#0f172a';
  let html = renderHeader('Service SITREP', 'Global Operational Readiness & Status', COLOR);
  html += monitoringContextBlock(mon);
  html += `<div style="background:#0f172a; color:#fff; padding:20px; text-align:center; margin-bottom:25px;">
    <div style="font-size:32px; font-weight:900;">${data.totalEntries}</div>
    <div style="font-size:10px; font-weight:700; letter-spacing:0.2em;">TOTAL_DIAGNOSTIC_POINTS_SYNCED</div>
  </div>`;
  html += FOOTER_HTML;
  return html;
}

function generateIncidentsSitrep(data: WeekSummary, mon: TemplateImportContext | null): string {
  const COLOR = '#ef4444';
  let html = renderHeader('Incident Sitrep', 'High-Severity Operational Intercepts', COLOR);
  html += monitoringContextBlock(mon);
  const allInc = Object.values(data.houses).flatMap(h => h.incidents);
  if (allInc.length === 0) html += '<p style="text-align:center; padding:40px; color:#64748b; font-weight:900;">NO_INCIDENTS_LOGGED_FOR_PERIOD</p>';
  else {
    allInc.forEach(i => {
      html += `<div style="border:2px solid #ef4444; margin-bottom:15px; padding:15px;">
        <div style="display:flex; justify-content:space-between; border-bottom:1px solid #fee2e2; padding-bottom:8px; margin-bottom:10px;">
          <span style="font-weight:900; color:#ef4444;">${ex(i.house)} // ${ex(i.client)}</span>
          <span style="font-family:monospace; font-weight:700;">${ex(i.date)}</span>
        </div>
        <div style="font-size:11px; line-height:1.5;">${ex(i.entry)}</div>
      </div>`;
    });
  }
  html += FOOTER_HTML;
  return html;
}

function generateSafeguardingSitrep(data: WeekSummary, mon: TemplateImportContext | null): string {
  const COLOR = '#be185d';
  let html = renderHeader('Safeguarding Sitrep', 'Sensitive Vulnerability & Risk Management', COLOR);
  html += monitoringContextBlock(mon);
  const allSafe = Object.values(data.houses).flatMap(h => h.safeguarding);
  allSafe.forEach(s => {
